-- 2026-10-14 내용 검토 수정 (단원 34, 활동 17)
update public.lessons set title=$j$중국 친구에게 뭐라고 인사할까?$j$, content=$j${"quiz": [{"q": "중국 친구를 처음 만났을 때 하는 인사는 무엇일까요?", "answer": 2, "choices": ["再见", "晚安", "你好", "明天见"], "explain": "你好(nǐ hǎo)는 만났을 때 하는 '안녕' 인사예요."}, {"q": "할아버지께 높여서 인사할 때 알맞은 말은 무엇일까요?", "answer": 0, "choices": ["您好", "你们好", "晚安", "再见"], "explain": "어른께는 你 대신 높임말 您을 써서 您好(nín hǎo)라고 해요."}, {"q": "자기 전에 가족에게 하는 인사는 무엇일까요?", "answer": 3, "choices": ["早上好", "晚上好", "老师好", "晚安"], "explain": "晚安(wǎn'ān)은 '잘 자'라는 뜻이에요."}, {"q": "'내일 만나'라는 뜻의 인사는 무엇일까요?", "answer": 1, "choices": ["大家好", "明天见", "你好", "早上好"], "explain": "明天(내일) + 见(만나다) = 明天见(míngtiān jiàn)이에요."}, {"q": "再见의 병음으로 알맞은 것은 무엇일까요?", "answer": 0, "choices": ["zàijiàn", "zǎoshang", "wǎn'ān", "dàjiā"], "explain": "再见은 zàijiàn(짜이지엔)이라고 읽어요."}], "intro": "새 친구를 만나면 가장 먼저 인사를 하지요. 중국어 인사 你好(nǐ hǎo, 니 하오) 하나만 알아도 중국 친구와 웃으며 이야기를 시작할 수 있어요.", "summary": ["만나면 你好(nǐ hǎo), 어른께는 您好(nín hǎo), 선생님께는 老师好(lǎoshī hǎo)라고 해요.", "아침에는 早上好, 저녁에는 晚上好, 자기 전에는 晚安이라고 해요.", "헤어질 때는 再见(zàijiàn), 내일 또 만나면 明天见(míngtiān jiàn)이라고 해요."], "keywords": [{"word": "你好", "meaning": "nǐ hǎo(니 하오). 언제나 쓰는 인사 '안녕'"}, {"word": "您", "meaning": "nín(닌). 어른을 높여 부르는 '당신'"}, {"word": "老师", "meaning": "lǎoshī(라오스). 선생님"}, {"word": "再见", "meaning": "zàijiàn(짜이지엔). 헤어질 때 인사"}], "sections": [{"paras": ["你好(nǐ hǎo, 니 하오)는 '안녕'이라는 뜻이에요. 你(nǐ)는 '너', 好(hǎo)는 '좋다'라는 뜻이라서 '너에게 좋은 일이 있기를!' 하는 반가운 마음이 담겨 있어요.", "친구가 你好! 하고 인사하면 나도 똑같이 你好! 하고 대답하면 돼요.", "你와 好는 둘 다 3성이에요. 3성 두 개가 이어지면 앞 글자는 2성처럼 살짝 올려 '니(ní) 하오'로 말하면 자연스러워요."], "figure": "두 아이가 손을 흔들며 인사하는 모습", "example": "A: 你好！(nǐ hǎo, 니 하오) 안녕! / B: 你好！(nǐ hǎo, 니 하오) 안녕!", "heading": "언제나 쓸 수 있는 인사 你好"}, {"paras": ["할머니, 할아버지 같은 어른께는 你 대신 높임말 您(nín)을 써서 您好(nín hǎo, 닌 하오)라고 인사해요.", "선생님께는 老师好(lǎoshī hǎo, 라오스 하오)라고 해요. 老师는 '선생님'이에요.", "친구 여러 명에게는 你们好(nǐmen hǎo, 니먼 하오), 모두에게 한꺼번에 인사할 때는 大家好(dàjiā hǎo, 다지아 하오)라고 해요."], "figure": "교실 앞에서 학생들이 선생님께 고개를 숙여 인사하는 모습", "example": "老师好！(lǎoshī hǎo) 선생님, 안녕하세요! / 大家好！(dàjiā hǎo) 여러분, 안녕하세요!", "heading": "어른과 여러 사람에게 하는 인사"}, {"paras": ["아침에는 早上好(zǎoshang hǎo, 짜오상 하오)라고 해요. '좋은 아침'이라는 뜻이에요.", "저녁에 만나면 晚上好(wǎnshang hǎo, 완상 하오)라고 인사해요.", "잠자리에 들기 전에는 晚安(wǎn'ān, 완안)이라고 말해요. '잘 자'라는 뜻이에요."], "figure": "해가 뜨는 아침, 노을 지는 저녁, 달이 뜬 밤을 세 칸으로 나눈 그림", "example": "🌅 早上好(zǎoshang hǎo) 좋은 아침 / 🌆 晚上好(wǎnshang hǎo) 저녁 인사 / 🌙 晚安(wǎn'ān) 잘 자", "heading": "아침, 저녁, 자기 전 인사"}, {"paras": ["헤어질 때는 再见(zàijiàn, 짜이지엔)이라고 해요. '다시 만나'라는 뜻이에요.", "내일 또 만날 친구에게는 明天见(míngtiān jiàn, 밍티엔 지엔)이라고 말해요. 明天은 '내일', 见은 '만나다'예요."], "figure": "학교 정문 앞에서 아이들이 손을 흔들며 헤어지는 모습", "example": "A: 再见！(zàijiàn) 잘 가! / B: 明天见！(míngtiān jiàn) 내일 만나!", "heading": "헤어질 때 인사"}], "parent_tip": "아이가 어른께도 你好를 쓰는 경우가 많으니, 높임말 您好를 함께 연습해 주세요. 하루 동안 집에서 아침에는 早上好, 잠들기 전에는 晚安으로 인사를 주고받는 '중국어 인사 하루'를 해 보면 금방 익숙해집니다.", "expressions": [{"en": "你好", "ko": "안녕", "note": "nǐ hǎo (니 하오)"}, {"en": "您好", "ko": "안녕하세요(어른께 높여서)", "note": "nín hǎo (닌 하오)"}, {"en": "老师好", "ko": "선생님, 안녕하세요", "note": "lǎoshī hǎo (라오스 하오)"}, {"en": "你们好", "ko": "얘들아, 안녕(여러 명에게)", "note": "nǐmen hǎo (니먼 하오)"}, {"en": "大家好", "ko": "여러분, 안녕하세요", "note": "dàjiā hǎo (다지아 하오)"}, {"en": "早上好", "ko": "좋은 아침(아침 인사)", "note": "zǎoshang hǎo (짜오상 하오)"}, {"en": "晚上好", "ko": "저녁 인사", "note": "wǎnshang hǎo (완상 하오)"}, {"en": "晚安", "ko": "잘 자", "note": "wǎn'ān (완안)"}, {"en": "再见", "ko": "잘 가, 다시 만나", "note": "zàijiàn (짜이지엔)"}, {"en": "明天见", "ko": "내일 만나", "note": "míngtiān jiàn (밍티엔 지엔)"}]}$j$::jsonb where slug='c3-05';
update public.lessons set title=$j$중국어로 하나부터 열까지 셀 수 있을까?$j$, content=$j${"quiz": [{"q": "🍎🍎🍎 사과의 수를 중국어로 바르게 쓴 것은 무엇일까요?", "answer": 2, "choices": ["一", "二", "三", "四"], "explain": "사과가 3개이므로 三(sān)이에요. 가로줄도 3개예요."}, {"q": "九의 뜻은 무엇일까요?", "answer": 0, "choices": ["9", "6", "7", "8"], "explain": "九(jiǔ, 지우)는 9예요."}, {"q": "숫자 4를 뜻하는 四의 병음은 무엇일까요?", "answer": 2, "choices": ["shí", "sān", "sì", "liù"], "explain": "四는 4성 sì(쓰)예요. shí는 10을 뜻하는 十이에요."}, {"q": "二 + 三 = ? 알맞은 것을 고르세요.", "answer": 3, "choices": ["四", "六", "七", "五"], "explain": "2 + 3 = 5이므로 五(wǔ)예요."}, {"q": "중국 손가락 숫자에서 엄지와 새끼손가락만 펴면 몇일까요?", "answer": 0, "choices": ["六", "八", "九", "十"], "explain": "엄지와 새끼손가락을 펴면 六(liù, 6)이에요."}], "intro": "계단을 오를 때, 사탕을 나눌 때 우리는 숫자를 세요. 중국어 숫자 열 개만 알면 나이도, 전화번호도 말할 수 있어요. 손가락을 펴고 같이 세어 봐요!", "summary": ["一(yī) 二(èr) 三(sān) 四(sì) 五(wǔ) 六(liù) 七(qī) 八(bā) 九(jiǔ) 十(shí), 그리고 0은 零(líng)이에요.", "四(sì, 4성)와 十(shí, 2성)은 소리가 비슷하니 성조와 혀 모양으로 구별해요.", "중국에서는 한 손의 손가락 모양으로 6~10도 나타내요."], "keywords": [{"word": "一 二 三", "meaning": "yī èr sān. 1, 2, 3. 가로줄 개수가 숫자예요."}, {"word": "四와 十", "meaning": "sì(4)와 shí(10). 소리가 비슷해 헷갈리기 쉬워요."}, {"word": "零", "meaning": "líng(링). 숫자 0"}, {"word": "손가락 숫자", "meaning": "중국에서 한 손으로 1~10을 나타내는 방법"}], "sections": [{"paras": ["一(yī, 이)은 1, 二(èr, 얼)은 2, 三(sān, 싼)은 3이에요.", "세 글자는 가로줄 개수가 숫자와 같아요. 줄 하나는 1, 줄 둘은 2, 줄 셋은 3이라서 쉽게 외울 수 있어요.", "二(èr)는 혀끝을 살짝 말아 올리며 '얼'처럼 소리 내요."], "figure": "가로줄 하나, 둘, 셋이 그어진 카드 옆에 사과가 하나, 둘, 셋 놓인 그림", "example": "🍎 一(yī) / 🍎🍎 二(èr) / 🍎🍎🍎 三(sān)", "heading": "一, 二, 三은 줄의 개수예요"}, {"paras": ["四(sì, 쓰)는 4, 五(wǔ, 우)는 5, 六(liù, 리우)는 6이에요.", "四(sì)는 4성으로 뚝 떨어지고, 혀끝을 윗니 뒤에 대고 '쓰'라고 해요. 열을 뜻하는 十(shí, 스)과 헷갈리지 않게 조심해요.", "五(wǔ)는 3성이라 낮게 눌렀다가 살짝 올려요."], "figure": "주사위 눈 4, 5, 6이 나란히 놓인 그림", "example": "四(sì) 4 / 五(wǔ) 5 / 六(liù) 6", "heading": "四, 五, 六"}, {"paras": ["七(qī, 치)는 7, 八(bā, 빠)는 8, 九(jiǔ, 지우)는 9, 十(shí, 스)은 10이에요.", "아무것도 없는 0은 零(líng, 링)이라고 해요. 전화번호를 말할 때 자주 써요.", "十(shí)은 혀를 말아 2성으로 올리며 '스', 四(sì)는 혀를 펴고 4성으로 내리며 '쓰'예요."], "figure": "1부터 10까지 숫자가 적힌 계단을 아이가 한 칸씩 올라가는 그림", "example": "七(qī) 7 / 八(bā) 8 / 九(jiǔ) 9 / 十(shí) 10 / 零(líng) 0", "heading": "七, 八, 九, 十 그리고 零"}, {"paras": ["중국 사람들은 한 손으로 1부터 10까지 나타내요. 1~5는 우리처럼 손가락을 펴요.", "六은 엄지와 새끼손가락만 펴고, 七은 엄지·검지·중지 끝을 모아요. 八은 엄지와 검지를 펴서 'ㄴ' 모양을 만들고, 九는 검지를 갈고리처럼 구부려요.", "十은 두 검지를 십자로 겹치거나 주먹을 쥐어 나타내요. 시장에서 값을 말할 때 자주 써요."], "figure": "중국식 손가락 숫자 6, 7, 8, 9, 10을 한 손으로 만든 다섯 개의 손 모양 그림", "example": "🤙 六(liù) / 🤌 七(qī) / 八(bā)은 엄지+검지 'ㄴ' 모양", "heading": "중국에서는 한 손으로 열까지 세요"}], "parent_tip": "四(sì)와 十(shí)를 구별하는 것이 가장 어렵습니다. 계단을 오르거나 간식을 셀 때 중국어로 세어 보게 하고, 부모님이 손가락 숫자를 보여 주면 아이가 중국어로 말하는 놀이를 해 보세요. 집 전화번호를 중국어로 말해 보는 것도 좋은 연습입니다.", "expressions": [{"en": "零", "ko": "0", "note": "líng (링)"}, {"en": "一", "ko": "1, 하나", "note": "yī (이)"}, {"en": "二", "ko": "2, 둘", "note": "èr (얼)"}, {"en": "三", "ko": "3, 셋", "note": "sān (싼)"}, {"en": "四", "ko": "4, 넷", "note": "sì (쓰)"}, {"en": "五", "ko": "5, 다섯", "note": "wǔ (우)"}, {"en": "六", "ko": "6, 여섯", "note": "liù (리우)"}, {"en": "七", "ko": "7, 일곱", "note": "qī (치)"}, {"en": "八", "ko": "8, 여덟", "note": "bā (빠)"}, {"en": "九", "ko": "9, 아홉", "note": "jiǔ (지우)"}, {"en": "十", "ko": "10, 열", "note": "shí (스)"}]}$j$::jsonb where slug='c3-06';
update public.lessons set title=$j$식당에서 중국어로 주문해 볼까요?$j$, content=$j${"quiz": [{"q": "식당에서 我要饺子。라고 하면 무슨 뜻일까요?", "answer": 1, "choices": ["만두를 좋아해요.", "만두 주세요.", "만두는 얼마예요?", "만두가 어디 있어요?"], "explain": "我要 ~ 는 '~을 원해요', 곧 '~ 주세요'예요."}, {"q": "콜라 '한 잔'을 말할 때 알맞은 세는 말은?", "answer": 2, "choices": ["个", "碗", "杯", "岁"], "explain": "음료는 잔을 뜻하는 杯(bēi)로 세요."}, {"q": "'햄버거 두 개 주세요.'를 바르게 쓴 것은?", "answer": 0, "choices": ["我要两个汉堡。", "我要二个汉堡。", "我要汉堡两个。", "我两个要汉堡。"], "explain": "두 개는 两个이고, 我要 + 수 + 세는 말 + 음식 순서예요."}, {"q": "종업원이 还要别的吗？라고 물었어요. 더 필요 없을 때 대답은?", "answer": 3, "choices": ["我要米饭。", "好的。", "你要什么？", "不要了，谢谢。"], "explain": "不要了，谢谢。는 '이제 됐어요, 고마워요.'예요."}, {"q": "식당에서 종업원을 부를 때 하는 말은?", "answer": 1, "choices": ["老师！", "服务员！", "再见！", "你好吗？"], "explain": "服务员(fúwùyuán, 푸우위엔)은 '종업원'이에요. 服务员！ 하고 부른 뒤 我要 ~ 로 주문해요."}], "intro": "중국 식당에 갔는데 메뉴를 주문해야 해요! 두근두근하지만 걱정 마세요. '我要(wǒ yào)' 한마디만 알면 먹고 싶은 음식을 시킬 수 있어요.", "summary": ["我要 + 음식: '~ 주세요.' 종업원은 服务员！으로 불러요.", "수와 음식 사이에 세는 말을 넣어요: 一个(개), 一碗(그릇), 一杯(잔). 2는 两!", "你要什么？(무엇을 드릴까요?) / 还要别的吗？(더 필요하세요?) / 不要了，谢谢。(됐어요, 고마워요.)"], "keywords": [{"word": "要 (yào)", "meaning": "원하다, 필요하다 (我要 = ~ 주세요)"}, {"word": "个 (ge)", "meaning": "개 (물건을 세는 말)"}, {"word": "碗 (wǎn)", "meaning": "그릇 (그릇에 담긴 음식을 세는 말)"}, {"word": "杯 (bēi)", "meaning": "잔 (음료를 세는 말)"}, {"word": "服务员 (fúwùyuán)", "meaning": "종업원"}], "sections": [{"paras": ["要(yào, 야오)는 '원하다, 필요하다'예요. 我要 뒤에 음식 이름을 붙이면 '나는 ~을 원해요', 곧 '~ 주세요'가 돼요.", "我要饺子。(wǒ yào jiǎozi, 워 야오 지아오쯔)는 '만두 주세요.'예요. 식당에서 종업원을 부를 때는 服务员！(fúwùyuán, 푸우위엔)이라고 해요."], "figure": "식당 테이블 위에 김이 나는 만두 접시와 젓가락이 놓인 모습", "example": "服务员！我要饺子。(저기요! 만두 주세요.)", "heading": "我要(wǒ yào) — '~ 주세요'"}, {"paras": ["중국어는 수와 물건 사이에 '세는 말'을 넣어요. 우리말 '한 그릇, 한 잔, 한 개'와 비슷해요.", "个(ge, 거)는 '개', 碗(wǎn, 완)은 '그릇', 杯(bēi, 베이)는 '잔'이에요. 一个汉堡(yí ge hànbǎo)는 햄버거 한 개, 一碗面条(yì wǎn miàntiáo)는 국수 한 그릇, 一杯可乐(yì bēi kělè)는 콜라 한 잔이에요.", "一는 뒤 글자에 따라 yí, yì로 소리가 살짝 바뀌니 병음을 보고 읽어요. 두 개를 말할 때는 二이 아니라 两(liǎng)을 써요. 两个汉堡 = 햄버거 두 개!"], "figure": "국수 한 그릇, 콜라 한 잔, 햄버거 두 개가 나란히 놓인 쟁반", "example": "我要一碗面条。(국수 한 그릇 주세요.) / 我要两个汉堡。(햄버거 두 개 주세요.)", "heading": "몇 개인지 말하기 — 세는 말(양사)"}, {"paras": ["종업원은 먼저 你要什么？(nǐ yào shénme, 니 야오 선머), '무엇을 드릴까요?'라고 물어요. 그러면 我要 ~ 로 대답해요.", "주문한 뒤에는 还要别的吗？(hái yào bié de ma, 하이 야오 비에 더 마), '다른 것도 필요하세요?'라고 물을 수 있어요.", "더 필요 없으면 不要了，谢谢。(bú yào le, xièxie, 부 야오 러 씨에시에), '이제 됐어요, 고마워요.'라고 해요. 종업원은 好的(hǎo de, 하오 더), '알겠습니다'라고 대답해요."], "figure": "앞치마를 두른 종업원이 메모지를 들고 아이의 주문을 받는 모습", "example": "A: 还要别的吗？  B: 不要了，谢谢。  A: 好的。", "heading": "종업원이 묻는 말에 대답해요"}, {"paras": ["饺子(jiǎozi, 지아오쯔) 만두, 面条(miàntiáo, 미엔티아오) 국수, 米饭(mǐfàn, 미판) 밥이에요.", "汉堡(hànbǎo, 한바오) 햄버거, 可乐(kělè, 커러) 콜라, 水(shuǐ, 수이) 물이에요. 좋아하는 음식 이름을 넣어 我要 ~ 로 연습해 보세요."], "figure": "만두, 국수, 밥, 물컵이 각각 담긴 작은 그릇들", "example": "我要一碗米饭和一杯水。(밥 한 그릇과 물 한 잔 주세요.) — 和(hé)는 '~와/과'", "heading": "중국 음식 이름을 알아 두어요"}], "parent_tip": "우리말은 '햄버거 두 개'처럼 음식 이름이 먼저 나오지만 중국어는 '两个汉堡'처럼 수와 세는 말이 앞에 온다는 점을 아이가 헷갈립니다. 一의 성조가 yí(一个)·yì(一碗, 一杯)로 바뀌는 것은 지금은 병음을 보고 읽는 정도로 충분합니다. 집에서 식사 때 '你要什么？'로 묻고 '我要一碗米饭。'으로 답하는 식당 놀이를 해 보세요.", "expressions": [{"en": "服务员！", "ko": "저기요! (종업원을 부를 때)", "note": "fúwùyuán (푸우위엔)"}, {"en": "你要什么？", "ko": "무엇을 드릴까요? / 뭐 먹을래?", "note": "nǐ yào shénme (니 야오 선머)"}, {"en": "我要一碗面条。", "ko": "국수 한 그릇 주세요.", "note": "wǒ yào yì wǎn miàntiáo (워 야오 이 완 미엔티아오)"}, {"en": "我要两个汉堡。", "ko": "햄버거 두 개 주세요.", "note": "wǒ yào liǎng ge hànbǎo (워 야오 량 거 한바오)"}, {"en": "我要一杯可乐。", "ko": "콜라 한 잔 주세요.", "note": "wǒ yào yì bēi kělè (워 야오 이 베이 커러)"}, {"en": "我要饺子。", "ko": "만두 주세요.", "note": "wǒ yào jiǎozi (워 야오 지아오쯔)"}, {"en": "还要别的吗？", "ko": "다른 것도 필요하세요?", "note": "hái yào bié de ma (하이 야오 비에 더 마)"}, {"en": "不要了，谢谢。", "ko": "이제 됐어요, 고마워요.", "note": "bú yào le, xièxie (부 야오 러, 씨에시에)"}, {"en": "好的。", "ko": "알겠습니다. / 좋아요.", "note": "hǎo de (하오 더)"}, {"en": "米饭", "ko": "밥", "note": "mǐfàn (미판)"}]}$j$::jsonb where slug='c5-06';
update public.lessons set title=$j$이거 얼마예요? 중국어로 물건 사기$j$, content=$j${"quiz": [{"q": "这个多少钱？의 뜻은?", "answer": 0, "choices": ["이거 얼마예요?", "이거 살게요.", "이거 뭐예요?", "이거 좋아요?"], "explain": "这个는 '이것', 多少钱은 '얼마예요?'예요."}, {"q": "물건이 너무 비쌀 때 하는 말은?", "answer": 2, "choices": ["很便宜。", "我买这个。", "太贵了！", "好的。"], "explain": "太贵了！(tài guì le)는 '너무 비싸요!'예요."}, {"q": "二十块는 얼마일까요?", "answer": 1, "choices": ["12위안", "20위안", "2위안", "200위안"], "explain": "二十은 20이라서 20위안이에요."}, {"q": "여러 물건을 사고 '모두 얼마예요?'라고 물을 때 알맞은 말은?", "answer": 3, "choices": ["那个多少钱？", "便宜一点儿吧。", "我买这个。", "一共多少钱？"], "explain": "一共(모두 합해서) + 多少钱(얼마)이에요."}, {"q": "便宜(piányi)의 뜻은?", "answer": 0, "choices": ["싸다", "비싸다", "사다", "크다"], "explain": "便宜는 '싸다', 贵는 '비싸다'예요."}], "intro": "중국 시장에서 예쁜 판다 열쇠고리를 발견했어요! 값이 궁금할 때는 뭐라고 물어야 할까요? 오늘은 값을 묻고, 깎아 달라고 하고, 물건을 사는 말을 배워요.", "summary": ["这个多少钱？(이거 얼마예요?) / 那个多少钱？(저거 얼마예요?)", "값은 숫자 + 块로 말해요: 十块(10위안), 两块(2위안), 一百块(100위안).", "太贵了！(너무 비싸요!) / 便宜一点儿吧。(싸게 해 주세요.) / 一共多少钱？(모두 얼마예요?)"], "keywords": [{"word": "多少钱 (duōshao qián)", "meaning": "얼마예요?"}, {"word": "这个 / 那个 (zhège / nàge)", "meaning": "이것 / 저것"}, {"word": "块 (kuài)", "meaning": "위안(중국 돈 단위)을 말로 할 때 쓰는 말"}, {"word": "贵 / 便宜 (guì / piányi)", "meaning": "비싸다 / 싸다"}, {"word": "一共 (yígòng)", "meaning": "모두 합해서"}], "sections": [{"paras": ["这个(zhège, 저거)는 '이것', 那个(nàge, 나거)는 '저것'이에요. 多少钱(duōshao qián, 둬사오 치엔)은 '얼마예요?'라는 뜻이에요. 这个의 소리 '저거'는 우리말 '저거(저것)'와 비슷하게 들리지만 뜻은 '이것'이에요. 헷갈리지 않게 조심해요!", "그래서 물건을 가리키며 这个多少钱？(zhège duōshao qián)이라고 하면 '이거 얼마예요?'가 돼요. 멀리 있는 물건은 那个多少钱？이라고 물어요."], "figure": "시장 진열대 위의 판다 열쇠고리를 손가락으로 가리키는 아이", "example": "这个多少钱？(이거 얼마예요?) / 那个多少钱？(저거 얼마예요?)", "heading": "这个多少钱？— 이거 얼마예요?"}, {"paras": ["중국 돈의 단위는 위안(元, yuán)이에요. 말할 때는 元 대신 块(kuài, 콰이)를 많이 써요.", "十块钱(shí kuài qián, 스 콰이 치엔)은 '10위안이에요', 二十五块(èrshíwǔ kuài)는 '25위안'이에요. 끝의 钱은 빼고 말해도 돼요.", "2위안은 两块(liǎng kuài), 100위안은 一百块(yìbǎi kuài, 이바이 콰이)예요. 2를 셀 때 两을 쓰는 규칙, 기억나지요?"], "figure": "작은 동전과 지폐 모양 장난감 돈이 지갑 옆에 놓인 모습", "example": "A: 这个多少钱？  B: 十五块。(15위안이에요.)", "heading": "값은 숫자 + 块(kuài)로 말해요"}, {"paras": ["너무 비쌀 때는 太贵了！(tài guì le, 타이 꾸이 러)라고 해요. 太 ~ 了는 '너무 ~하다'예요.", "싸다는 便宜(piányi, 피엔이)예요. 很便宜。는 '아주 싸요.'이고, 便宜一点儿吧。(piányi yìdiǎnr ba, 피엔이 이디얼 바)는 '조금 싸게 해 주세요.'예요."], "figure": "가게 주인과 아이가 웃으며 물건값을 이야기하는 시장 풍경", "example": "A: 这个三十块。  B: 太贵了！便宜一点儿吧。", "heading": "비싸요! 깎아 주세요!"}, {"paras": ["买(mǎi, 마이)는 '사다'예요. 我买这个。(wǒ mǎi zhège, 워 마이 저거)는 '이거 살게요.'예요.", "여러 개를 샀다면 一共多少钱？(yígòng duōshao qián, 이꽁 둬사오 치엔), '모두 얼마예요?'라고 물어요. 一共은 '모두 합해서'라는 뜻이에요.", "값을 더하는 건 수학 시간처럼 하면 돼요. 연필이 五块, 공책이 八块라면 一共十三块예요."], "figure": "연필과 공책을 계산대 위에 올려놓은 아이의 손", "example": "A: 一共多少钱？  B: 一共十三块。(모두 13위안이에요.)", "heading": "사기로 했다면 — 我买这个 / 一共多少钱？"}], "parent_tip": "중국 돈은 위안(元)이지만 일상 회화에서는 块를 주로 쓴다는 점, 2위안은 两块라는 점을 짚어 주세요. 장난감 돈과 집안 물건에 가격표를 붙여 '这个多少钱？—○块'로 가게 놀이를 하면, 숫자 복습과 더하기 연습(一共)을 함께 할 수 있습니다.", "expressions": [{"en": "这个多少钱？", "ko": "이거 얼마예요?", "note": "zhège duōshao qián (저거 둬사오 치엔)"}, {"en": "那个多少钱？", "ko": "저거 얼마예요?", "note": "nàge duōshao qián (나거 둬사오 치엔)"}, {"en": "十块钱。", "ko": "10위안이에요.", "note": "shí kuài qián (스 콰이 치엔)"}, {"en": "两块", "ko": "2위안", "note": "liǎng kuài (량 콰이)"}, {"en": "一百块", "ko": "100위안", "note": "yìbǎi kuài (이바이 콰이)"}, {"en": "太贵了！", "ko": "너무 비싸요!", "note": "tài guì le (타이 꾸이 러)"}, {"en": "很便宜。", "ko": "아주 싸요.", "note": "hěn piányi (헌 피엔이)"}, {"en": "便宜一点儿吧。", "ko": "조금 싸게 해 주세요.", "note": "piányi yìdiǎnr ba (피엔이 이디얼 바)"}, {"en": "我买这个。", "ko": "이거 살게요.", "note": "wǒ mǎi zhège (워 마이 저거)"}, {"en": "一共多少钱？", "ko": "모두 얼마예요?", "note": "yígòng duōshao qián (이꽁 둬사오 치엔)"}]}$j$::jsonb where slug='c5-07';
update public.lessons set title=$j$중국어로 '나는 ~할 수 있어요' 말해 볼까요?$j$, content=$j${"quiz": [{"q": "我会游泳。의 뜻은?", "answer": 1, "choices": ["나는 수영을 좋아해요.", "나는 수영할 수 있어요.", "나는 수영을 못 해요.", "너는 수영할 수 있니?"], "explain": "会는 '할 수 있다', 游泳은 '수영하다'예요."}, {"q": "'나는 피아노를 못 쳐요.'를 바르게 쓴 것은?", "answer": 2, "choices": ["我会弹钢琴。", "我不喜欢弹钢琴。", "我不会弹钢琴。", "你会弹钢琴吗？"], "explain": "'못 하다'는 会 앞에 不를 붙인 不会예요."}, {"q": "不会에서 不는 어떻게 읽을까요?", "answer": 0, "choices": ["bú (부)", "bù (뿌)", "bū", "bǔ"], "explain": "会(huì)가 4성이라서 앞의 不는 bú(2성)로 올려 읽어요."}, {"q": "汉语(Hànyǔ)의 뜻은?", "answer": 3, "choices": ["한국어", "영어", "일본어", "중국어"], "explain": "汉语는 '중국어'예요. 한국어는 韩语(Hányǔ)예요."}, {"q": "A: 你会骑自行车吗？ — 자전거를 탈 줄 알 때 짧은 대답은?", "answer": 0, "choices": ["会！", "不会。", "喜欢。", "在那儿。"], "explain": "会！는 '할 수 있어!'라는 짧은 대답이에요."}], "intro": "수영, 자전거, 피아노… 여러분이 배워서 할 수 있게 된 것은 무엇인가요? 오늘은 중국어로 '할 수 있어요', '못 해요'를 말하고 친구에게 물어보는 법을 배워요.", "summary": ["我会 + 하는 일: '나는 ~할 수 있어요.' (배워서 익힌 솜씨)", "못 할 때는 不会(bú huì): 我不会游泳。", "你会 ~ 吗？로 묻고 会！/ 不会。로 대답해요. 我会说一点儿汉语。= 중국어 조금 해요."], "keywords": [{"word": "会 (huì)", "meaning": "(배워서) ~할 줄 알다, ~할 수 있다"}, {"word": "不会 (bú huì)", "meaning": "~할 줄 모르다, 못 하다"}, {"word": "说 (shuō)", "meaning": "말하다"}, {"word": "汉语 (Hànyǔ)", "meaning": "중국어"}, {"word": "一点儿 (yìdiǎnr)", "meaning": "조금"}], "sections": [{"paras": ["会(huì, 후이)는 '(배워서) ~할 줄 알다, ~할 수 있다'예요. 我会 뒤에 하는 일을 붙이면 '나는 ~할 수 있어요'가 돼요.", "我会游泳。(wǒ huì yóuyǒng, 워 후이 여우융)은 '나는 수영할 수 있어요.'예요. 游泳은 '수영하다'예요.", "会는 연습해서 익힌 솜씨에 써요. 수영, 자전거, 악기, 외국어처럼 배워야 할 수 있는 것들이지요."], "figure": "수영장 가장자리에서 물안경을 쓰고 있는 아이", "example": "我 + 会 + 游泳 → 我会游泳。(나는 수영할 수 있어요.)", "heading": "我会(wǒ huì) + 하는 일"}, {"paras": ["아직 못 하면 会 앞에 不를 붙여 不会(bú huì, 부 후이)라고 해요. 我不会游泳。는 '나는 수영을 못 해요.'예요.", "不는 원래 bù인데, 会(huì)처럼 4성 앞에서는 bú(부)로 올려 읽어요. 是 앞에서 不是(bú shì)로 읽은 것과 같은 규칙이에요."], "figure": "자전거 옆에 서 있는 아이와 물가에서 망설이는 아이", "example": "我会骑自行车，我不会游泳。(나는 자전거는 탈 수 있지만 수영은 못 해요.)", "heading": "못 할 때는 不会(bú huì)"}, {"paras": ["'~할 수 있니?'는 你会 ~ 吗？로 물어요. 你会弹钢琴吗？(nǐ huì tán gāngqín ma, 니 후이 탄 깡친 마)는 '너 피아노 칠 줄 알아?'예요.", "대답은 짧게 会！(할 수 있어!) 또는 不会。(못 해.)라고 하면 돼요.", "'너는 무엇을 할 수 있어?'는 你会做什么？(nǐ huì zuò shénme, 니 후이 쭤 선머)예요. 做는 '하다'예요."], "figure": "피아노 건반 위에 올려진 아이의 두 손", "example": "A: 你会弹钢琴吗？  B: 会！我会弹钢琴。", "heading": "묻고 대답하기"}, {"paras": ["说(shuō, 숴)는 '말하다', 汉语(Hànyǔ, 한위)는 '중국어'예요. 你会说汉语吗？는 '너 중국어 할 줄 알아?'예요.", "조금 할 수 있다면 我会说一点儿汉语。(wǒ huì shuō yìdiǎnr Hànyǔ, 워 후이 숴 이디얼 한위), '나는 중국어를 조금 할 줄 알아요.'라고 해요. 一点儿은 '조금'이에요.", "英语(Yīngyǔ, 잉위)는 영어, 韩语(Hányǔ, 한위)는 한국어예요. 汉语(Hànyǔ, 4성)와 韩语(Hányǔ, 2성)는 한글로 적으면 똑같이 '한위'지만 성조가 달라요. 汉은 뚝 떨어지고, 韩은 위로 올려 읽어요."], "figure": "세계 지도 앞에서 친구와 이야기하는 두 아이", "example": "A: 你会说汉语吗？  B: 我会说一点儿汉语。", "heading": "'중국어 할 줄 알아요?' — 언어 말하기"}], "parent_tip": "会는 '배워서 할 줄 아는 능력'에 쓰는 말이라 수영·자전거·악기·외국어 같은 표현과 잘 어울립니다. 아이가 喜欢(좋아하다)과 会(할 수 있다)를 섞어 쓰기 쉬우니 '좋아하는 것'과 '할 수 있는 것'을 나눠 말해 보게 해 주세요. 가족이 돌아가며 '你会○○吗？'로 묻고 '会/不会'로 답하는 놀이를 추천합니다.", "expressions": [{"en": "我会游泳。", "ko": "나는 수영할 수 있어요.", "note": "wǒ huì yóuyǒng (워 후이 여우융)"}, {"en": "我不会游泳。", "ko": "나는 수영을 못 해요.", "note": "wǒ bú huì yóuyǒng (워 부 후이 여우융)"}, {"en": "你会说汉语吗？", "ko": "너 중국어 할 줄 알아?", "note": "nǐ huì shuō Hànyǔ ma (니 후이 숴 한위 마)"}, {"en": "我会说一点儿汉语。", "ko": "나는 중국어를 조금 할 줄 알아요.", "note": "wǒ huì shuō yìdiǎnr Hànyǔ (워 후이 숴 이디얼 한위)"}, {"en": "你会做什么？", "ko": "너는 무엇을 할 수 있어?", "note": "nǐ huì zuò shénme (니 후이 쭤 선머)"}, {"en": "我会弹钢琴。", "ko": "나는 피아노를 칠 수 있어요.", "note": "wǒ huì tán gāngqín (워 후이 탄 깡친)"}, {"en": "我会骑自行车。", "ko": "나는 자전거를 탈 수 있어요.", "note": "wǒ huì qí zìxíngchē (워 후이 치 쯔싱처)"}, {"en": "我会踢足球。", "ko": "나는 축구를 할 수 있어요.", "note": "wǒ huì tī zúqiú (워 후이 티 쭈치우)"}, {"en": "我会画画儿。", "ko": "나는 그림을 그릴 수 있어요.", "note": "wǒ huì huà huàr (워 후이 화 활)"}, {"en": "我会说英语。", "ko": "나는 영어를 할 줄 알아요.", "note": "wǒ huì shuō Yīngyǔ (워 후이 숴 잉위)"}]}$j$::jsonb where slug='c5-09';
update public.lessons set title=$j$N부터 Z까지, 알파벳 끝까지 가 볼까?$j$, content=$j${"narr": {"kw": "assets/audio/n/e1-02_kw.mp3", "q0": "assets/audio/n/e1-02_q0.mp3", "q1": "assets/audio/n/e1-02_q1.mp3", "q2": "assets/audio/n/e1-02_q2.mp3", "q3": "assets/audio/n/e1-02_q3.mp3", "q4": "assets/audio/n/e1-02_q4.mp3", "s0": "assets/audio/n/e1-02_s0.mp3", "s1": "assets/audio/n/e1-02_s1.mp3", "s2": "assets/audio/n/e1-02_s2.mp3", "s3": "assets/audio/n/e1-02_s3.mp3", "sum": "assets/audio/n/e1-02_sum.mp3", "cover": "assets/audio/n/e1-02_cover.mp3"}, "quiz": [{"q": "🐷 pig는 어떤 글자로 시작할까요?", "answer": 2, "choices": ["B", "D", "P", "Q"], "explain": "pig는 P(피)로 시작해요."}, {"q": "Z 바로 앞 글자는?", "answer": 0, "choices": ["Y", "X", "W", "V"], "explain": "X, Y, Z 차례예요. Z 바로 앞은 Y예요."}, {"q": "'더블유'라고 부르는 글자는?", "answer": 3, "choices": ["V", "M", "N", "W"], "explain": "W의 이름은 '더블유'예요."}, {"q": "N 다음에 오는 글자는?", "answer": 1, "choices": ["M", "O", "P", "Q"], "explain": "M, N, O 차례예요. N 다음은 O예요."}, {"q": "알파벳 맨 마지막 글자는?", "answer": 2, "choices": ["A", "X", "Z", "Y"], "explain": "알파벳은 A로 시작해서 Z로 끝나요."}], "intro": "지난번에 A부터 M까지 배웠어요. 🔤 오늘은 나머지 13개를 만나요.", "summary": ["N부터 Z까지 13개 글자를 배웠어요.", "R은 '알', W는 '더블유'라고 불러요.", "Z가 알파벳 맨 마지막 글자예요."], "keywords": [{"word": "알파벳", "meaning": "영어를 쓰는 글자 26개"}, {"word": "마지막 글자", "meaning": "알파벳 맨 끝 글자 Z"}, {"word": "알파벳 노래", "meaning": "26개 글자를 차례대로 부르는 노래"}], "sections": [{"paras": ["M 다음은 N이에요.", "N부터 Z까지 13개예요.", "Z가 맨 마지막 글자예요."], "figure": "책상 위에 N부터 Z까지 차례로 놓인 나무 알파벳 블록", "example": "N O P Q R S T U V W X Y Z", "heading": "알파벳 뒷부분이에요"}, {"paras": ["R은 '알'이라고 불러요.", "🐷 pig는 P로 시작해요.", "☀️ sun은 S로 시작해요."], "figure": "돼지 인형과 호랑이 인형이 놓인 아이 책상", "example": "N 엔 · O 오 · P 피 · Q 큐 · R 알 · S 에스 · T 티", "heading": "N부터 T까지 이름을 불러요"}, {"paras": ["W는 '더블유'예요. 이름이 길어요.", "🦓 zebra는 Z로 시작해요.", "X는 🦊 fox 끝에 있어요."], "figure": "우산, 요요, 얼룩말 인형이 나란히 놓인 모습", "example": "U 유 · V 브이 · W 더블유 · X 엑스 · Y 와이 · Z 지", "heading": "U부터 Z까지 이름을 불러요"}, {"paras": ["알파벳 노래를 끝까지 불러요. 🎵", "LMNOP는 빨리 지나가요.", "천천히 한 글자씩 짚어요."], "figure": "아이가 바닥에 26개 알파벳 카드를 한 줄로 늘어놓은 모습", "example": "Q R S, T U V, W X, Y and Z", "heading": "A부터 Z까지 이어 불러요"}], "parent_tip": "알파벳 노래에서 L-M-N-O-P를 한 덩어리 'elemeno'처럼 부르는 아이가 많으니 천천히 짚으며 불러 주세요. Z는 미국식 '지', 영국식 '제드'로 부르며 둘 다 맞습니다. A~M 카드와 합쳐 26장을 차례대로 늘어놓는 놀이를 해 보세요.", "expressions": [{"en": "N", "ko": "엔", "note": "👃 nose 의 첫 글자"}, {"en": "O", "ko": "오", "note": "🐙 octopus 의 첫 글자"}, {"en": "P", "ko": "피", "note": "🐷 pig 의 첫 글자"}, {"en": "Q", "ko": "큐", "note": "👸 queen 의 첫 글자"}, {"en": "R", "ko": "알", "note": "🐰 rabbit 의 첫 글자"}, {"en": "S", "ko": "에스", "note": "☀️ sun 의 첫 글자"}, {"en": "T", "ko": "티", "note": "🐯 tiger 의 첫 글자"}, {"en": "U", "ko": "유", "note": "☂️ umbrella 의 첫 글자"}, {"en": "V", "ko": "브이", "note": "🎻 violin 의 첫 글자"}, {"en": "W", "ko": "더블유", "note": "⌚ watch 의 첫 글자"}, {"en": "X", "ko": "엑스", "note": "🦊 fox 의 끝 글자"}, {"en": "Y, Z", "ko": "와이, 지", "note": "🪀 yo-yo, 🦓 zebra 의 첫 글자. Z '지'는 G '지'와 달리 벌 소리 '즈'처럼 시작해요"}]}$j$::jsonb where slug='e1-02';
update public.lessons set title=$j$글자는 어떤 소리를 낼까? a부터 m까지$j$, content=$j${"narr": {"kw": "assets/audio/n/e1-04_kw.mp3", "q0": "assets/audio/n/e1-04_q0.mp3", "q1": "assets/audio/n/e1-04_q1.mp3", "q2": "assets/audio/n/e1-04_q2.mp3", "q3": "assets/audio/n/e1-04_q3.mp3", "q4": "assets/audio/n/e1-04_q4.mp3", "s0": "assets/audio/n/e1-04_s0.mp3", "s1": "assets/audio/n/e1-04_s1.mp3", "s2": "assets/audio/n/e1-04_s2.mp3", "s3": "assets/audio/n/e1-04_s3.mp3", "sum": "assets/audio/n/e1-04_sum.mp3", "cover": "assets/audio/n/e1-04_cover.mp3"}, "quiz": [{"q": "🍎 apple의 첫소리를 내는 글자는?", "answer": 1, "choices": ["e", "a", "i", "o"], "explain": "apple은 a로 시작해요. '애' 소리가 나요."}, {"q": "🐶 dog은 어떤 글자 소리로 시작할까요?", "answer": 3, "choices": ["g", "b", "h", "d"], "explain": "dog은 '드' 소리, d로 시작해요."}, {"q": "🌙 moon과 첫소리가 같은 낱말은?", "answer": 2, "choices": ["🦁 lion", "🎩 hat", "🐵 monkey", "🥚 egg"], "explain": "moon과 monkey는 둘 다 m '음' 소리로 시작해요."}, {"q": "🐱 cat과 첫소리가 같은 낱말은?", "answer": 0, "choices": ["🪁 kite", "🐟 fish", "🍇 grapes", "🧃 juice"], "explain": "cat의 c와 kite의 k는 둘 다 '크' 소리예요."}, {"q": "글자 a에 대해 맞는 말은?", "answer": 1, "choices": ["이름과 소리가 늘 같아요", "이름은 '에이', apple에서는 '애' 소리예요", "a는 소리가 없어요", "a는 '음' 소리가 나요"], "explain": "글자 이름과 낱말 속 소리는 다를 수 있어요."}], "intro": "글자에는 이름도 있고 소리도 있어요. 👂 오늘은 a부터 m까지 소리를 들어 봐요.", "summary": ["글자에는 이름과 소리가 있어요.", "a부터 m까지 낱말 첫소리를 들어 봤어요.", "c와 k는 둘 다 '크' 소리가 나요."], "keywords": [{"word": "글자 소리", "meaning": "낱말 속에서 글자가 내는 소리 (apple의 a는 '애')"}, {"word": "첫소리", "meaning": "낱말을 말할 때 맨 처음 나는 소리"}, {"word": "파닉스", "meaning": "글자와 소리를 짝지어 배우는 방법"}], "sections": [{"paras": ["a의 이름은 '에이'예요.", "🍎 apple에서는 '애' 소리가 나요.", "이걸 글자 소리라고 해요."], "figure": "책상 위의 빨간 사과와 곰 인형", "example": "a - apple · b - bear", "heading": "이름과 소리는 달라요"}, {"paras": ["낱말 첫소리를 잘 들어요.", "🐱 cat은 '크' 소리로 시작해요.", "🐟 fish는 윗니로 아랫입술을 살짝 물어요."], "figure": "사과, 곰 인형, 달걀, 물고기 장난감이 한 줄로 놓인 모습", "example": "a - apple · b - bear · c - cat · d - dog · e - egg · f - fish", "heading": "a부터 f까지 소리"}, {"paras": ["🎩 hat은 숨을 '흐' 내쉬어요.", "🦁 lion은 혀끝을 윗니 뒤에 대요.", "🌙 moon은 입을 다물고 '음' 해요."], "figure": "포도, 모자, 주스 팩, 연이 놓인 아이 방 바닥", "example": "g - grapes · h - hat · i - insect · j - juice · k - kite · l - lion · m - moon", "heading": "g부터 m까지 소리"}, {"paras": ["🐱 cat과 🪁 kite는 둘 다 '크' 소리예요.", "글자는 달라도 소리가 같아요."], "figure": "고양이 인형 옆에 놓인 작은 연", "example": "c - cat · k - kite", "heading": "cat의 c와 kite의 k는 같은 소리"}], "parent_tip": "한글로 적은 소리('크', '브')는 어디까지나 비슷한 소리이니 듣기 버튼으로 실제 소리를 꼭 들려주세요. 특히 '브', '드'처럼 뒤에 '으'를 길게 붙이지 않고 짧게 끊어 내는 것이 중요합니다. 집 안 물건을 가리키며 '이건 무슨 소리로 시작할까?' 하고 물어보세요.", "expressions": [{"en": "a - apple", "ko": "🍎 사과", "note": "'애' 소리로 시작"}, {"en": "b - bear", "ko": "🐻 곰", "note": "입술을 붙였다 떼며 '브'"}, {"en": "c - cat", "ko": "🐱 고양이", "note": "'크' 소리"}, {"en": "d - dog", "ko": "🐶 개", "note": "'드' 소리"}, {"en": "e - egg", "ko": "🥚 달걀", "note": "'에' 소리"}, {"en": "f - fish", "ko": "🐟 물고기", "note": "윗니로 아랫입술을 물고 '프'"}, {"en": "g - grapes", "ko": "🍇 포도", "note": "목에서 '그'"}, {"en": "h - hat", "ko": "🎩 모자", "note": "숨을 내쉬며 '흐'"}, {"en": "i - insect", "ko": "🐛 곤충", "note": "짧게 '이'"}, {"en": "j - juice", "ko": "🧃 주스", "note": "'즈' 소리"}, {"en": "k - kite", "ko": "🪁 연", "note": "'크' 소리 (c와 같아요)"}, {"en": "l - lion, m - moon", "ko": "🦁 사자, 🌙 달", "note": "l은 혀끝을 윗니 뒤에, m은 입을 다물고 '음'"}]}$j$::jsonb where slug='e1-04';
update public.lessons set title=$j$n부터 z까지, 글자 소리를 들어 볼까?$j$, content=$j${"narr": {"kw": "assets/audio/n/e1-05_kw.mp3", "q0": "assets/audio/n/e1-05_q0.mp3", "q1": "assets/audio/n/e1-05_q1.mp3", "q2": "assets/audio/n/e1-05_q2.mp3", "q3": "assets/audio/n/e1-05_q3.mp3", "q4": "assets/audio/n/e1-05_q4.mp3", "s0": "assets/audio/n/e1-05_s0.mp3", "s1": "assets/audio/n/e1-05_s1.mp3", "s2": "assets/audio/n/e1-05_s2.mp3", "s3": "assets/audio/n/e1-05_s3.mp3", "sum": "assets/audio/n/e1-05_sum.mp3", "cover": "assets/audio/n/e1-05_cover.mp3"}, "quiz": [{"q": "🐷 pig의 첫소리 글자는?", "answer": 1, "choices": ["b", "p", "q", "d"], "explain": "pig는 입술을 터뜨리는 '프' 소리, p로 시작해요."}, {"q": "☀️ sun과 첫소리가 같은 낱말은?", "answer": 0, "choices": ["🐍 snake", "🦓 zebra", "🐯 tiger", "🐙 octopus"], "explain": "sun과 snake는 둘 다 s '스' 소리로 시작해요."}, {"q": "🦊 fox에서 x 소리는 어디에 있을까요?", "answer": 2, "choices": ["맨 앞", "가운데", "맨 끝", "없어요"], "explain": "fox는 f-o-x예요. x는 맨 끝에서 '크스' 소리가 나요."}, {"q": "윗니로 아랫입술을 살짝 물고 내는 소리는?", "answer": 3, "choices": ["🐷 pig의 p", "🐰 rabbit의 r", "🐯 tiger의 t", "🎻 violin의 v"], "explain": "v는 윗니가 아랫입술에 닿아요."}, {"q": "☂️ umbrella의 첫 글자는?", "answer": 2, "choices": ["a", "o", "u", "e"], "explain": "umbrella는 짧은 '어' 소리, u로 시작해요."}], "intro": "지난번에 a부터 m까지 소리를 배웠어요. 👂 오늘은 n부터 z까지 소리를 들어 봐요.", "summary": ["n부터 z까지 낱말 첫소리를 들어 봤어요.", "x는 fox처럼 낱말 끝에서 자주 소리 나요.", "v와 b, s와 z는 입 모양으로 구별해요."], "keywords": [{"word": "첫소리", "meaning": "낱말을 말할 때 맨 처음 나는 소리"}, {"word": "끝소리", "meaning": "낱말 맨 끝에서 나는 소리 (fox의 x)"}, {"word": "입 모양", "meaning": "소리를 낼 때 입술·이·혀의 모양"}], "sections": [{"paras": ["👃 nose는 콧소리 '은'으로 시작해요.", "🐷 pig는 입술을 붙였다 '프' 터뜨려요.", "q는 늘 u와 함께 다녀요. 👸 queen!"], "figure": "돼지 인형과 토끼 인형이 나란히 앉은 책상", "example": "n - nose · o - octopus · p - pig · q - queen · r - rabbit", "heading": "n부터 r까지 소리"}, {"paras": ["☀️ sun은 뱀 소리 '스'로 시작해요. 🐍", "☂️ umbrella는 짧게 '어' 해요.", "🎻 violin은 윗니로 아랫입술을 물어요."], "figure": "노란 우산과 장난감 바이올린이 놓인 아이 방", "example": "s - sun · t - tiger · u - umbrella · v - violin", "heading": "s부터 v까지 소리"}, {"paras": ["⌚ watch는 입술을 동그랗게 '우' 해요.", "x는 🦊 fox처럼 끝에서 '크스' 소리가 나요.", "🦓 zebra는 벌 소리 '즈'로 시작해요. 🐝"], "figure": "요요와 얼룩말 인형, 여우 인형이 놓인 책상", "example": "w - watch · x - fox · y - yo-yo · z - zebra", "heading": "w부터 z까지 소리"}, {"paras": ["v와 b는 달라요.", "v는 윗니가 입술에 닿고, b는 두 입술이 붙어요.", "s는 바람 소리, z는 벌 소리예요."], "figure": "아이가 거울 앞에서 입 모양을 보는 모습", "example": "v - violin · b - bear · s - sun · z - zebra", "heading": "헷갈리는 소리 짝"}], "parent_tip": "r과 l, v와 b, f와 p는 우리말에 없는 구별이라 아이들이 어려워합니다. 거울 앞에서 입 모양(윗니가 입술에 닿는지)을 함께 보며 연습하면 좋습니다. 한글로 적은 소리는 참고용이니 듣기 버튼으로 실제 소리를 꼭 들려주세요.", "expressions": [{"en": "n - nose", "ko": "👃 코", "note": "콧소리 '은'"}, {"en": "o - octopus", "ko": "🐙 문어", "note": "입을 크게 벌려 '아'"}, {"en": "p - pig", "ko": "🐷 돼지", "note": "입술을 붙였다 '프' 터뜨려요"}, {"en": "q - queen", "ko": "👸 여왕", "note": "qu는 '크우' 소리"}, {"en": "r - rabbit", "ko": "🐰 토끼", "note": "입술을 동그랗게 '루'"}, {"en": "s - sun", "ko": "☀️ 해", "note": "뱀 소리 '스'"}, {"en": "t - tiger", "ko": "🐯 호랑이", "note": "'트' 소리"}, {"en": "u - umbrella", "ko": "☂️ 우산", "note": "짧게 '어'"}, {"en": "v - violin", "ko": "🎻 바이올린", "note": "윗니로 아랫입술을 물고 '브'"}, {"en": "w - watch", "ko": "⌚ 손목시계", "note": "입술을 동그랗게 '우'"}, {"en": "x - fox", "ko": "🦊 여우", "note": "x는 끝에서 '크스'"}, {"en": "y - yo-yo, z - zebra", "ko": "🪀 요요, 🦓 얼룩말", "note": "y는 '이' 하고 짧게 미끄러지듯(yo-yo의 '요'), z는 벌 소리 '즈'"}]}$j$::jsonb where slug='e1-05';
update public.lessons set title=$j$영어로 하나, 둘, 셋 어떻게 셀까?$j$, content=$j${"narr": {"kw": "assets/audio/n/e1-08_kw.mp3", "q0": "assets/audio/n/e1-08_q0.mp3", "q1": "assets/audio/n/e1-08_q1.mp3", "q2": "assets/audio/n/e1-08_q2.mp3", "q3": "assets/audio/n/e1-08_q3.mp3", "q4": "assets/audio/n/e1-08_q4.mp3", "s0": "assets/audio/n/e1-08_s0.mp3", "s1": "assets/audio/n/e1-08_s1.mp3", "s2": "assets/audio/n/e1-08_s2.mp3", "s3": "assets/audio/n/e1-08_s3.mp3", "sum": "assets/audio/n/e1-08_sum.mp3", "cover": "assets/audio/n/e1-08_cover.mp3"}, "quiz": [{"q": "🍎🍎🍎 사과는 몇 개? 영어로 고르세요.", "answer": 1, "choices": ["two", "three", "four", "five"], "explain": "사과가 3개예요. 3은 three예요."}, {"q": "ten은 몇일까요?", "answer": 3, "choices": ["1", "6", "8", "10"], "explain": "ten은 10이에요."}, {"q": "5를 영어로 하면?", "answer": 2, "choices": ["four", "nine", "five", "six"], "explain": "5는 five예요."}, {"q": "\"몇 개예요?\"를 영어로 하면?", "answer": 0, "choices": ["How many?", "Hello!", "Thank you.", "Goodbye."], "explain": "개수를 물을 때 How many?라고 해요."}, {"q": "seven 다음 숫자는?", "answer": 3, "choices": ["six", "nine", "ten", "eight"], "explain": "7 다음은 8, eight예요."}], "intro": "🍎 사과가 몇 개 있을까요? 오늘은 영어로 1부터 10까지 세어 봐요.", "summary": ["1~5는 one, two, three, four, five예요.", "6~10은 six, seven, eight, nine, ten이에요.", "How many?는 \"몇 개예요?\"라는 뜻이에요."], "keywords": [{"word": "one ~ ten", "meaning": "영어로 1부터 10까지의 숫자"}, {"word": "How many?", "meaning": "몇 개예요? 하고 묻는 말"}, {"word": "세기", "meaning": "하나씩 짚으며 몇 개인지 알아보는 것"}], "sections": [{"paras": ["1은 one, 2는 two예요.", "3은 three, 4는 four, 5는 five예요.", "손가락을 하나씩 펴며 말해 봐요. ✋"], "figure": "아이 손가락 다섯 개를 하나씩 펴는 모습", "example": "🍎 one, 🍎🍎 two, 🍎🍎🍎 three, 🍎🍎🍎🍎 four, 🍎🍎🍎🍎🍎 five", "heading": "1부터 5까지 세어요"}, {"paras": ["6은 six, 7은 seven이에요.", "8은 eight, 9는 nine이에요.", "10은 ten이에요. 손가락이 모두 펴졌어요! 🙌"], "figure": "두 손을 활짝 편 아이의 손", "example": "⭐ six, seven, eight, nine, ten!", "heading": "6부터 10까지 세어요"}, {"paras": ["two는 w 소리가 안 나요. [투]라고 읽어요.", "eight도 gh 소리가 안 나요. [에잇]이라고 읽어요."], "figure": "책상 위에 놓인 숫자 블록 장난감", "example": "two [투], eight [에잇]", "heading": "숫자 글자를 살펴봐요"}, {"paras": ["How many?는 \"몇 개예요?\"라는 뜻이에요.", "세어 보고 숫자로 대답해요."], "figure": "강아지 인형 세 개를 손가락으로 세는 아이", "example": "How many? 🐶🐶🐶 → Three!", "heading": "How many? 몇 개예요?"}], "parent_tip": "two와 eight처럼 글자와 소리가 다른 숫자를 아이가 가장 많이 헷갈립니다. 계단을 오르거나 간식을 나눌 때 영어로 함께 세어 보세요. \"How many cookies?\"라고 묻고 숫자로 대답하게 하면 자연스럽게 익힙니다.", "expressions": [{"en": "one", "ko": "1, 하나", "note": "[원]"}, {"en": "two", "ko": "2, 둘", "note": "[투] w는 소리가 안 나요"}, {"en": "three", "ko": "3, 셋", "note": "[쓰리] 혀를 이 사이에 살짝"}, {"en": "four", "ko": "4, 넷", "note": "[포]"}, {"en": "five", "ko": "5, 다섯", "note": "[파이브]"}, {"en": "six", "ko": "6, 여섯", "note": "[식스]"}, {"en": "seven", "ko": "7, 일곱", "note": "[세븐]"}, {"en": "eight", "ko": "8, 여덟", "note": "[에잇] gh는 소리가 안 나요"}, {"en": "nine", "ko": "9, 아홉", "note": "[나인]"}, {"en": "ten", "ko": "10, 열", "note": "[텐]"}, {"en": "How many?", "ko": "몇 개예요?", "note": "개수를 물을 때"}]}$j$::jsonb where slug='e1-08';
update public.lessons set title=$j$좋아하는 것을 영어로 어떻게 말할까?$j$, content=$j${"narr": {"kw": "assets/audio/n/e1-12_kw.mp3", "q0": "assets/audio/n/e1-12_q0.mp3", "q1": "assets/audio/n/e1-12_q1.mp3", "q2": "assets/audio/n/e1-12_q2.mp3", "q3": "assets/audio/n/e1-12_q3.mp3", "q4": "assets/audio/n/e1-12_q4.mp3", "s0": "assets/audio/n/e1-12_s0.mp3", "s1": "assets/audio/n/e1-12_s1.mp3", "s2": "assets/audio/n/e1-12_s2.mp3", "s3": "assets/audio/n/e1-12_s3.mp3", "sum": "assets/audio/n/e1-12_sum.mp3", "cover": "assets/audio/n/e1-12_cover.mp3"}, "quiz": [{"q": "\"나는 고양이를 좋아해.\"를 영어로 하면? 🐱", "answer": 1, "choices": ["I like dogs.", "I like cats.", "I don't like cats.", "Do you like cats?"], "explain": "고양이는 cats. I like cats.예요."}, {"q": "I don't like milk.의 뜻은?", "answer": 2, "choices": ["나는 우유를 좋아해.", "너는 우유를 좋아하니?", "나는 우유를 좋아하지 않아.", "우유 주세요."], "explain": "don't가 있으면 \"좋아하지 않아\"예요."}, {"q": "Do you like pizza? 피자를 좋아하면 뭐라고 대답할까요? 🍕", "answer": 0, "choices": ["Yes, I do.", "No, I don't.", "Goodbye!", "This is pizza."], "explain": "좋아하면 Yes, I do.라고 대답해요."}, {"q": "like의 뜻은?", "answer": 3, "choices": ["싫어하다", "먹다", "보다", "좋아하다"], "explain": "like는 좋아한다는 뜻이에요."}, {"q": "\"너는 개를 좋아하니?\"를 영어로 하면? 🐶", "answer": 2, "choices": ["I like dogs.", "No, I don't.", "Do you like dogs?", "This is my dog."], "explain": "물어볼 때는 Do you like ~?를 써요."}], "intro": "🍕 피자를 좋아하나요? 오늘은 좋아하는 것을 영어로 말해 봐요.", "summary": ["I like ~. = 나는 ~을 좋아해.", "I don't like ~. = 나는 ~을 좋아하지 않아.", "Do you like ~?에는 Yes, I do. / No, I don't.로 대답해요."], "keywords": [{"word": "like", "meaning": "좋아하다"}, {"word": "I like ~.", "meaning": "나는 ~을 좋아해."}, {"word": "I don't like ~.", "meaning": "나는 ~을 좋아하지 않아."}, {"word": "Do you like ~?", "meaning": "너는 ~을 좋아하니?"}], "sections": [{"paras": ["I는 \"나는\", like는 \"좋아해\"예요.", "I like 다음에 좋아하는 것을 말해요."], "figure": "사과를 들고 웃는 아이의 손", "example": "🍎 I like apples. (나는 사과를 좋아해.)", "heading": "I like ~는 \"나는 ~을 좋아해\""}, {"paras": ["동물도, 음식도, 색깔도 말할 수 있어요.", "🐶 I like dogs. 🍕 I like pizza.", "💙 I like blue."], "figure": "강아지 인형과 우유 컵이 놓인 책상", "example": "I like cats. I like milk.", "heading": "여러 가지를 좋아해요"}, {"paras": ["싫으면 I don't like ~라고 해요.", "don't는 \"~하지 않아\"라는 뜻이에요."], "figure": "접시 위 당근을 밀어내는 아이 손", "example": "🥕 I don't like carrots. (나는 당근을 안 좋아해.)", "heading": "좋아하지 않을 때"}, {"paras": ["Do you like ~?는 \"너는 ~을 좋아하니?\"예요.", "좋으면 Yes, I do. 싫으면 No, I don't."], "figure": "마주 앉아 이야기하는 두 아이", "example": "Do you like dogs? → Yes, I do! 🐶", "heading": "친구에게 물어봐요"}], "parent_tip": "영어에서는 동물이나 과일처럼 셀 수 있는 것을 좋아한다고 할 때 dogs, apples처럼 끝에 s를 붙입니다. 1~2학년 단계에서는 문법 설명보다 통째로 따라 말하게 해 주세요. 식사 시간에 \"Do you like carrots?\" 하고 묻고 Yes, I do. / No, I don't.로 답하는 놀이가 효과적입니다.", "expressions": [{"en": "I like apples.", "ko": "나는 사과를 좋아해."}, {"en": "I like dogs.", "ko": "나는 개를 좋아해."}, {"en": "I like cats.", "ko": "나는 고양이를 좋아해."}, {"en": "I like pizza.", "ko": "나는 피자를 좋아해."}, {"en": "I like blue.", "ko": "나는 파란색을 좋아해."}, {"en": "I don't like carrots.", "ko": "나는 당근을 좋아하지 않아.", "note": "싫을 때"}, {"en": "Do you like dogs?", "ko": "너는 개를 좋아하니?", "note": "물어볼 때"}, {"en": "Yes, I do.", "ko": "응, 좋아해.", "note": "좋아할 때 대답"}, {"en": "No, I don't.", "ko": "아니, 안 좋아해.", "note": "싫을 때 대답"}, {"en": "like", "ko": "좋아하다", "note": "[라이크]"}]}$j$::jsonb where slug='e1-12';
update public.lessons set title=$j$알파벳 26글자로 어떻게 낱말을 만들까?$j$, content=$j${"quiz": [{"q": "알파벳은 모두 몇 글자일까요?", "answer": 2, "choices": ["24글자", "25글자", "26글자", "28글자"], "explain": "영어 알파벳은 A부터 Z까지 모두 26글자예요."}, {"q": "대문자 G와 짝이 되는 소문자는?", "answer": 1, "choices": ["q", "g", "j", "p"], "explain": "G의 소문자는 g예요. q, j, p와 모양이 비슷하니 꼬리 방향을 잘 봐요."}, {"q": "'공'을 뜻하는 낱말은 무엇일까요?", "answer": 0, "choices": ["ball", "bag", "egg", "dog"], "explain": "ball은 공이에요. b 소리 '브'로 시작해요."}, {"q": "cat의 첫 글자를 h로 바꾸면 무슨 낱말이 될까요?", "answer": 3, "choices": ["hot", "hen", "hit", "hat"], "explain": "h+a+t는 hat(모자)이에요. 글자 하나로 뜻이 달라져요."}, {"q": "사과 그림을 보고 \"What's this?\"라고 물으면 알맞은 대답은?", "answer": 1, "choices": ["It's an egg.", "It's an apple.", "It's a dog.", "I'm fine."], "explain": "사과는 apple이니까 It's an apple.이라고 대답해요. apple처럼 모음 소리(애)로 시작하는 낱말 앞에는 a 대신 an을 써요."}], "intro": "간판이나 과자 봉지에서 A, B, C 같은 글자를 본 적 있죠? 이 글자들이 모여서 영어 낱말이 돼요.", "summary": ["영어 알파벳은 A부터 Z까지 26글자이고 대문자와 소문자가 있어요.", "알파벳은 이름과 낱말 속 소리가 달라요(b는 '브' 소리).", "글자의 소리를 차례로 이어 읽으면 낱말이 되고, 한 글자만 바꿔도 다른 낱말이 돼요."], "keywords": [{"word": "알파벳", "meaning": "영어를 쓰는 글자. A부터 Z까지 26개"}, {"word": "대문자", "meaning": "A, B, C처럼 크게 쓰는 글자"}, {"word": "소문자", "meaning": "a, b, c처럼 작게 쓰는 글자"}, {"word": "낱말", "meaning": "뜻을 가진 말 한 덩어리. 예: cat, dog"}], "sections": [{"paras": ["영어 글자를 알파벳이라고 해요. A부터 Z까지 모두 26글자가 있어요.", "알파벳 노래를 부르면 순서를 쉽게 외울 수 있어요. A, B, C, D, E, F, G~ 하고 따라 불러 봐요."], "figure": "A부터 Z까지 알파벳 26글자가 무지개색 블록에 하나씩 적힌 그림", "example": "A B C D E F G … X Y Z (모두 26개)", "heading": "알파벳은 모두 26글자예요"}, {"paras": ["알파벳은 큰 글자(대문자)와 작은 글자(소문자)가 짝을 이뤄요. A와 a, B와 b는 같은 글자예요.", "문장의 첫 글자나 사람 이름의 첫 글자는 대문자로 써요. 나머지는 보통 소문자로 써요."], "figure": "대문자 엄마 글자와 소문자 아기 글자가 손을 잡고 있는 그림", "example": "A-a, B-b, G-g, Q-q / 이름: Tom, Mina", "heading": "대문자와 소문자가 있어요"}, {"paras": ["알파벳은 이름과 소리가 달라요. b의 이름은 '비'지만, 낱말 속에서는 '브' 소리를 내요.", "첫소리를 알면 낱말을 읽기 쉬워요. apple은 a(애), ball은 b(브), cat은 c(크) 소리로 시작해요."], "figure": "apple, ball, cat, dog 그림 카드 아래 첫 글자가 크게 강조된 모습", "example": "a-apple(사과), b-ball(공), c-cat(고양이), d-dog(개)", "heading": "글자마다 소리가 있어요"}, {"paras": ["c, a, t 세 글자를 차례로 붙이면 cat(고양이)이 돼요. 소리를 하나씩 이어 읽으면 '크-애-트, 캣!'이 돼요.", "글자 하나만 바꿔도 다른 낱말이 돼요. cat의 c를 h로 바꾸면 hat(모자)이 돼요."], "figure": "글자 블록 c, a, t를 이어 붙여 고양이 그림이 나타나는 장면", "example": "c+a+t = cat → h+a+t = hat", "heading": "글자를 모으면 낱말이 돼요"}], "parent_tip": "부모님께: 아이들은 b와 d, p와 q처럼 좌우가 뒤집힌 소문자를 자주 헷갈립니다. 집 안 물건을 가리키며 \"이건 무슨 소리로 시작할까?\"라고 첫소리 놀이를 해 보세요. 알파벳의 이름(비)과 소리(브)를 구분해 주면 읽기가 훨씬 수월해집니다.", "expressions": [{"en": "apple", "ko": "사과", "note": "a로 시작해요"}, {"en": "ball", "ko": "공", "note": "b로 시작해요"}, {"en": "cat", "ko": "고양이", "note": "c로 시작해요"}, {"en": "dog", "ko": "개", "note": "d로 시작해요"}, {"en": "egg", "ko": "달걀", "note": "e로 시작해요"}, {"en": "What's this?", "ko": "이것은 뭐예요?", "note": "물건 이름을 물을 때"}, {"en": "It's a cat.", "ko": "그것은 고양이예요.", "note": "물건 이름을 알려 줄 때"}]}$j$::jsonb where slug='e3-01';
update public.lessons set title=$j$오늘 날씨는 영어로 어떻게 말할까?$j$, content=$j${"quiz": [{"q": "날씨를 물을 때 쓰는 말은?", "answer": 1, "choices": ["How old are you?", "How's the weather?", "How much is it?", "What's this?"], "explain": "weather는 날씨예요. How's the weather?로 날씨를 물어요."}, {"q": "비가 내리는 그림에 알맞은 말은?", "answer": 2, "choices": ["It's sunny.", "It's snowy.", "It's rainy.", "It's hot."], "explain": "비가 오는 날씨는 rainy예요."}, {"q": "\"It's windy.\"의 뜻은?", "answer": 0, "choices": ["바람이 불어.", "눈이 와.", "더워.", "맑아."], "explain": "windy는 바람이 부는 날씨예요."}, {"q": "눈사람을 만드는 날의 날씨로 알맞은 것은?", "answer": 3, "choices": ["It's hot.", "It's sunny and hot.", "It's rainy.", "It's snowy and cold."], "explain": "눈사람은 눈이 오고 추운 날 만들어요. snowy and cold가 알맞아요."}, {"q": "\"It's rainy.\"라고 들었을 때 이어서 할 말로 알맞은 것은?", "answer": 0, "choices": ["Take your umbrella.", "Wear your sunglasses.", "Let's make a snowman.", "Nice to meet you."], "explain": "비가 오니 우산(umbrella)을 챙기라고 말해요."}], "intro": "아침에 창밖을 보며 \"오늘은 비가 오네!\" 하고 말하죠? 영어로도 날씨를 묻고 답할 수 있어요.", "summary": ["날씨는 How's the weather?로 물어요.", "대답은 It's 뒤에 sunny, rainy, cloudy, snowy, windy를 붙여요.", "더우면 It's hot., 추우면 It's cold.라고 해요."], "keywords": [{"word": "weather", "meaning": "날씨"}, {"word": "sunny", "meaning": "해가 쨍쨍한, 맑은"}, {"word": "rainy", "meaning": "비가 오는"}, {"word": "cloudy", "meaning": "구름이 낀, 흐린"}, {"word": "snowy", "meaning": "눈이 오는"}, {"word": "windy", "meaning": "바람이 부는"}], "sections": [{"paras": ["날씨가 궁금할 때는 \"How's the weather?(날씨가 어때?)\"라고 물어요.", "How's는 How is를 줄인 말이고, weather는 '날씨'라는 뜻이에요."], "figure": "창문 밖을 바라보며 날씨를 궁금해하는 아이 그림", "example": "How's the weather today? (오늘 날씨 어때?)", "heading": "날씨를 묻는 말"}, {"paras": ["대답할 때는 It's 뒤에 날씨를 나타내는 말을 붙여요. 이때 It은 '그것'이라는 뜻이 아니라 날씨를 말할 때 쓰는 말이에요.", "맑으면 sunny, 비가 오면 rainy, 흐리면 cloudy, 눈이 오면 snowy, 바람이 불면 windy예요."], "figure": "해, 비구름, 회색 구름, 눈송이, 바람 그림 아래 sunny, rainy, cloudy, snowy, windy 낱말 카드", "example": "It's sunny. / It's rainy. / It's snowy.", "heading": "It's + 날씨로 대답해요"}, {"paras": ["기온을 말할 때도 It's를 써요. 더우면 hot, 추우면 cold, 따뜻하면 warm이에요.", "날씨에 맞게 \"Take your umbrella.(우산 가져가.)\"처럼 챙길 물건을 말해 줄 수도 있어요."], "figure": "추운 날 외투와 목도리를 한 아이와 더운 날 반팔 입은 아이를 나란히 그린 그림", "example": "It's cold. Wear your coat. (추워. 외투 입어.)", "heading": "덥고 추운 것도 말해요"}], "parent_tip": "부모님께: 아이들은 rain(비)과 rainy(비가 오는)처럼 -y가 붙는 차이를 자주 헷갈립니다. \"비·눈·해·구름·바람(rain, snow, sun, cloud, wind)으로 날씨를 말할 땐 It's 다음에 y가 붙은 말(rainy, snowy...)을 써요. hot, cold, warm은 그대로 써요.\"라고 짚어 주세요. 매일 아침 창밖을 보며 \"How's the weather?\"라고 묻는 습관을 들이면 가장 자연스럽게 익힐 수 있습니다.", "expressions": [{"en": "How's the weather?", "ko": "날씨가 어때?", "note": "날씨를 물을 때"}, {"en": "It's sunny.", "ko": "날씨가 맑아."}, {"en": "It's rainy.", "ko": "비가 와."}, {"en": "It's cloudy.", "ko": "흐려."}, {"en": "It's snowy.", "ko": "눈이 와."}, {"en": "It's hot.", "ko": "더워."}, {"en": "It's cold.", "ko": "추워."}, {"en": "Take your umbrella.", "ko": "우산 가져가.", "note": "비 오는 날 챙겨 줄 때"}]}$j$::jsonb where slug='e3-04';
update public.lessons set title=$j$영어 문장은 어떤 순서로 만들까?$j$, content=$j${"quiz": [{"q": "'나는 사과를 먹는다.'를 바른 순서로 쓴 것은?", "answer": 1, "choices": ["I an apple eat.", "I eat an apple.", "Eat I an apple.", "An apple I eat."], "explain": "영어는 누가(I) + 한다(eat) + 무엇을(an apple) 순서예요."}, {"q": "빈칸에 알맞은 말은? They ___ students.", "answer": 3, "choices": ["am", "is", "be", "are"], "explain": "they와 짝이 되는 be동사는 are예요."}, {"q": "바르게 쓴 문장은?", "answer": 2, "choices": ["my sister is kind.", "My sister is kind", "My sister is kind.", "my Sister is kind."], "explain": "첫 글자는 대문자, 끝에는 마침표를 찍어요."}, {"q": "\"He is happy.\"를 묻는 문장으로 바꾸면?", "answer": 0, "choices": ["Is he happy?", "He is happy?", "Does he happy?", "Happy is he?"], "explain": "be동사 is를 맨 앞으로 보내고 물음표를 붙여요."}, {"q": "'나는 우유를 좋아하지 않아.'를 영어로 하면?", "answer": 1, "choices": ["I not like milk.", "I don't like milk.", "I am not like milk.", "Don't I like milk."], "explain": "일반 동사(like) 앞에는 don't를 넣어 부정해요."}], "intro": "우리말은 \"나는 사과를 먹어\"라고 하지만 영어는 \"I eat an apple\"이라고 해요. 순서가 다르죠? 영어 문장을 만드는 규칙을 알아봐요.", "summary": ["영어 문장은 '누가 + 한다 + 무엇을' 순서로 만들어요.", "첫 글자는 대문자, 끝에는 마침표나 물음표를 붙이고, I는 항상 대문자예요.", "I-am, he/she/it-is, you/we/they-are로 짝을 맞추고, 부정은 not을 넣어요."], "keywords": [{"word": "주어", "meaning": "문장에서 '누가'에 해당하는 말. 예: I, She"}, {"word": "동사", "meaning": "문장에서 '한다'에 해당하는 말. 예: eat, play"}, {"word": "am / is / are", "meaning": "'~이다', '(어떤 상태)이다'를 나타내는 말(be동사)"}, {"word": "마침표", "meaning": "문장 끝에 찍는 점(.)"}, {"word": "물음표", "meaning": "묻는 문장 끝에 붙이는 표시(?)"}], "sections": [{"paras": ["영어 문장은 보통 '누가(주어) + 한다(동사) + 무엇을' 순서로 만들어요.", "우리말은 '무엇을'이 동사 앞에 오지만, 영어는 동사가 먼저 와요. I(나는) + eat(먹는다) + an apple(사과를)이에요."], "figure": "'누가 → 한다 → 무엇을' 블록 세 개가 기차처럼 이어진 그림", "example": "I + play + soccer. (나는 축구를 한다.)", "heading": "영어 문장의 기본 순서"}, {"paras": ["문장의 첫 글자는 대문자로 쓰고, 문장이 끝나면 마침표(.)를 찍어요.", "'나'를 뜻하는 I는 문장 어디에 있어도 항상 대문자로 써요. 낱말과 낱말 사이는 한 칸 띄어 써요."], "figure": "틀린 문장에 빨간 펜으로 대문자와 마침표를 고친 공책", "example": "my dog is cute → My dog is cute.", "heading": "문장을 쓰는 규칙"}, {"paras": ["'~이다', '(키가 큰, 기쁜 같은) 상태이다'를 말할 때는 am, is, are를 써요. I와는 am, he·she·it와는 is, you·we·they와는 are가 짝이에요.", "\"She is tall.(그녀는 키가 커.)\", \"We are friends.(우리는 친구야.)\"처럼 써요."], "figure": "I-am, he/she/it-is, you/we/they-are 짝꿍 카드 그림", "example": "I am happy. / He is my brother. / They are students.", "heading": "be동사로 상태 말하기"}, {"paras": ["묻는 문장은 끝에 물음표(?)를 붙여요. \"Are you hungry?\"처럼 be동사를 앞으로 보내거나, \"Do you like music?\"처럼 Do를 앞에 붙여요.", "'~하지 않다'는 not을 넣어요. \"I am not sad.\", \"I don't play the piano.\"처럼 써요."], "figure": "물음표와 마침표가 문장 끝에서 손을 흔드는 그림", "example": "You are tall. → Are you tall? / I like milk. → I don't like milk.", "heading": "묻는 문장과 부정하는 문장"}], "parent_tip": "부모님께: 아이들은 우리말 순서대로 \"I apple eat\"처럼 쓰는 실수를 자주 합니다. 낱말 카드를 섞어 주고 바른 순서로 늘어놓는 놀이를 해 보세요. \"I am not\"과 \"I don't\"를 섞어 쓰는 경우도 많으니 be동사 문장과 일반 동사 문장을 구분해 짚어 주시면 좋습니다.", "expressions": [{"en": "I play soccer.", "ko": "나는 축구를 해.", "note": "누가 + 한다 + 무엇을"}, {"en": "She is tall.", "ko": "그녀는 키가 커."}, {"en": "We are friends.", "ko": "우리는 친구야."}, {"en": "Are you hungry?", "ko": "너 배고프니?", "note": "be동사를 앞으로 보내 묻기"}, {"en": "Do you like music?", "ko": "너는 음악을 좋아하니?", "note": "Do를 앞에 붙여 묻기"}, {"en": "I don't play the piano.", "ko": "나는 피아노를 치지 않아."}]}$j$::jsonb where slug='e5-03';
update public.lessons set title=$j$일본 친구를 만나면 어떻게 인사할까?$j$, content=$j${"quiz": [{"q": "🌙 저녁에 만난 사람에게 하는 인사는 무엇일까요?", "answer": 2, "choices": ["おはようございます", "こんにちは", "こんばんは", "おやすみなさい"], "explain": "저녁 인사는 こんばんは(콤방와)예요. おやすみなさい는 잘 때 하는 인사예요."}, {"q": "こんにちは는 어떻게 읽을까요?", "answer": 1, "choices": ["콘니치하", "콘니치와", "곤니치히", "콘니치호"], "explain": "끝의 は는 '와'로 읽어서 '콘니치와'예요."}, {"q": "친구가 선물을 줬을 때 할 말은 무엇일까요?", "answer": 0, "choices": ["ありがとう", "すみません", "さようなら", "いただきます"], "explain": "고마울 때는 ありがとう(아리가토-)라고 해요."}, {"q": "🍚 밥을 다 먹은 뒤에 하는 인사는 무엇일까요?", "answer": 3, "choices": ["いただきます", "はじめまして", "またね", "ごちそうさまでした"], "explain": "다 먹은 뒤에는 ごちそうさまでした(고치소-사마데시타), 먹기 전에는 いただきます라고 해요."}, {"q": "처음 만난 친구에게 하는 인사는 무엇일까요?", "answer": 1, "choices": ["おやすみなさい", "はじめまして", "どういたしまして", "ごちそうさまでした"], "explain": "처음 만났을 때는 はじめまして(하지메마시테)라고 해요."}], "intro": "우리말에 '안녕하세요', '고마워요', '잘 자'가 있듯이 일본어에도 때에 맞는 인사말이 있어요. 히라가나로 인사말을 읽고, 소리 내어 따라 해 봐요.", "summary": ["아침 おはようございます, 낮 こんにちは, 저녁 こんばんは로 때에 맞게 인사해요.", "こんにちは, こんばんは의 끝 は는 '와'로 읽고, おはよう의 よう는 '요-'로 길게 읽어요.", "ありがとう(고마워), すみません(미안해요), いただきます(잘 먹겠습니다)도 함께 익혀요."], "keywords": [{"word": "인사말", "meaning": "만나고 헤어질 때, 고마울 때 주고받는 말."}, {"word": "긴소리", "meaning": "앞 소리를 길게 늘여 읽는 소리. おはよう의 よう는 '요-'로 길게 읽어요."}, {"word": "오지기", "meaning": "일본에서 인사할 때 고개와 허리를 숙이는 몸짓."}], "sections": [{"paras": ["일본어는 시간에 따라 인사말이 달라요. 아침에는 おはようございます(오하요- 고자이마스), 낮에는 こんにちは(콘니치와), 저녁에는 こんばんは(콤방와)라고 해요.", "친구나 가족에게 아침 인사를 할 때는 짧게 おはよう(오하요-)라고만 해도 돼요.", "こんにちは와 こんばんは의 끝 글자 は는 '하'가 아니라 '와'로 읽어요. 꼭 기억해 두세요!"], "figure": "아침 해, 한낮의 해, 저녁 달이 그려진 세 장의 그림 카드가 나란히 놓인 모습", "example": "🌅 아침: おはようございます(ohayou gozaimasu, 오하요- 고자이마스) / ☀️ 낮: こんにちは(konnichiwa, 콘니치와) / 🌙 저녁: こんばんは(konbanwa, 콤방와)", "heading": "아침, 낮, 저녁 인사가 달라요"}, {"paras": ["おはよう는 '오하요우'라고 또박또박 읽지 않고 '오하요-' 하고 よ를 길게 늘여 읽어요. 이렇게 う가 앞 소리를 길게 만드는 경우가 많아요.", "ありがとう(아리가토-), さようなら(사요-나라)도 마찬가지예요. 이 책에서는 길게 읽는 곳을 '-'로 표시했어요."], "figure": "고무줄을 길게 늘이는 아이 손 그림 옆에 '요-' 소리를 길게 늘이는 모습을 표현한 그림", "example": "おはよう → 오하요- / ありがとう → 아리가토- / さようなら → 사요-나라", "heading": "う는 앞 소리를 길게 늘여요"}, {"paras": ["헤어질 때는 さようなら(사요-나라)라고 해요. 친구끼리는 またね(마타네, 또 만나)를 더 자주 써요.", "밤에 잠자리에 들 때는 おやすみなさい(오야스미나사이, 안녕히 주무세요)라고 해요."], "figure": "학교 앞에서 손을 흔들며 헤어지는 두 아이의 뒷모습", "example": "👋 またね(matane, 마타네) 또 봐 / 😴 おやすみなさい(oyasuminasai, 오야스미나사이) 잘 자요", "heading": "헤어질 때, 잘 때"}, {"paras": ["고마울 때는 ありがとう(아리가토-), 더 공손하게는 ありがとうございます(아리가토- 고자이마스)라고 해요. 가볍게 どうも(도-모)라고도 하는데, 주로 어른들이 쓰는 말이에요. 대답으로는 どういたしまして(도-이타시마시테, 천만에요)라고 해요.", "미안할 때나 '저기요' 하고 부를 때는 すみません(스미마셍)이라고 해요.", "처음 만난 사람에게는 はじめまして(하지메마시테, 처음 뵙겠습니다)라고 해요. 밥 먹기 전에는 いただきます(이타다키마스), 다 먹은 뒤에는 ごちそうさまでした(고치소-사마데시타)라고 해요. 일본 사람들은 인사할 때 고개를 숙이는 '오지기'를 함께 해요."], "figure": "식탁 앞에서 두 손을 모으고 고개를 살짝 숙이는 아이", "example": "🙏 ありがとう(arigatou, 아리가토-) 고마워 / 🍚 いただきます(itadakimasu, 이타다키마스) 잘 먹겠습니다", "heading": "고마워요, 미안해요, 잘 먹겠습니다"}], "parent_tip": "부모님께: 인사말은 외우기보다 생활에서 써 보는 것이 가장 좋습니다. 오늘 하루는 아침에 'おはよう', 식사 때 'いただきます', 잘 때 'おやすみなさい'를 가족이 함께 일본어로 말해 보세요. 아이가 こんにちは를 '콘니치하'로 읽으면 끝의 は는 '와'로 읽는다는 점을 다시 짚어 주세요.", "expressions": [{"en": "おはようございます", "ko": "안녕하세요 (아침 인사)", "note": "ohayou gozaimasu (오하요- 고자이마스)"}, {"en": "こんにちは", "ko": "안녕하세요 (낮 인사)", "note": "konnichiwa (콘니치와) — 끝의 は는 '와'"}, {"en": "こんばんは", "ko": "안녕하세요 (저녁 인사)", "note": "konbanwa (콤방와) — 끝의 は는 '와'"}, {"en": "さようなら", "ko": "안녕히 가세요", "note": "sayounara (사요-나라)"}, {"en": "またね", "ko": "또 봐 (친구끼리)", "note": "matane (마타네)"}, {"en": "おやすみなさい", "ko": "안녕히 주무세요, 잘 자요", "note": "oyasuminasai (오야스미나사이)"}, {"en": "ありがとう", "ko": "고마워", "note": "arigatou (아리가토-)"}, {"en": "どういたしまして", "ko": "천만에요", "note": "douitashimashite (도-이타시마시테)"}, {"en": "すみません", "ko": "미안해요 / 저기요", "note": "sumimasen (스미마셍)"}, {"en": "はじめまして", "ko": "처음 뵙겠습니다", "note": "hajimemashite (하지메마시테)"}, {"en": "いただきます", "ko": "잘 먹겠습니다", "note": "itadakimasu (이타다키마스)"}, {"en": "ごちそうさまでした", "ko": "잘 먹었습니다", "note": "gochisousama deshita (고치소-사마데시타)"}]}$j$::jsonb where slug='j3-07';
update public.lessons set title=$j$일본어로 내 이름을 어떻게 소개할까?$j$, content=$j${"quiz": [{"q": "처음 만난 사람에게 하는 인사는 무엇일까요?", "answer": 0, "choices": ["はじめまして", "おやすみ", "ありがとう", "さようなら"], "explain": "はじめまして(하지메마시테)는 '처음 뵙겠습니다'라는 뜻이에요."}, {"q": "わたしは ジュンです。 에서 は는 어떻게 읽을까요?", "answer": 1, "choices": ["하(ha)", "와(wa)", "아(a)", "바(ba)"], "explain": "'~은/는'이라는 뜻으로 쓰인 は는 '와(wa)'로 읽어요."}, {"q": "'한국 사람이에요.'를 일본어로 바르게 말한 것은?", "answer": 2, "choices": ["にほんじんです。", "しょうがくせいです。", "かんこくじんです。", "よろしくおねがいします。"], "explain": "かんこく(한국) + じん(사람) + です = かんこくじんです예요."}, {"q": "자기소개를 마치며 '잘 부탁합니다'라고 할 때 쓰는 말은?", "answer": 3, "choices": ["こんにちは", "はじめまして", "わたしは", "よろしくおねがいします"], "explain": "よろしくおねがいします(요로시쿠 오네가이시마스)는 '잘 부탁합니다'예요."}, {"q": "さん을 붙이면 __어색한__ 것은 무엇일까요?", "answer": 2, "choices": ["친구 이름 ミナ", "반 친구 이름 ハルト", "내 이름", "새로 만난 사람 이름"], "explain": "さん은 다른 사람을 높여 부르는 말이라 내 이름에는 붙이지 않아요."}], "intro": "일본 친구를 처음 만났어요. 웃으면서 \"안녕, 나는 ○○야!\"라고 일본어로 말할 수 있다면 정말 멋지겠죠? 오늘은 일본어를 하나도 몰라도 바로 쓸 수 있는 자기소개를 배워요.", "summary": ["처음 만나면 はじめまして(하지메마시테)라고 인사해요.", "わたしは ○○です(와타시와 ○○데스)로 이름을 말해요. 이때 は는 '와'로 읽어요.", "마지막에는 よろしくおねがいします(요로시쿠 오네가이시마스)로 마무리해요."], "keywords": [{"word": "히라가나", "meaning": "일본어의 기본 글자. あ, い, う 같은 글자"}, {"word": "가타카나", "meaning": "외국에서 온 말이나 외국 사람 이름을 쓰는 글자. ア, イ, ウ 같은 글자"}, {"word": "わたし", "meaning": "나, 저 (watashi, 와타시)"}, {"word": "です", "meaning": "~예요, ~이에요 (desu, 데스)"}, {"word": "は(와)", "meaning": "'~은/는'이라는 뜻일 때는 '와(wa)'로 읽어요"}], "sections": [{"paras": ["일본어에는 히라가나, 가타카나, 한자 세 가지 글자가 있어요. 히라가나는 일본어의 기본 글자이고, 가타카나는 외국에서 온 말이나 외국 사람 이름을 쓸 때 주로 써요.", "처음에는 글자를 다 외우지 않아도 괜찮아요. 이 단원에서는 일본어 옆에 로마자와 한글 소리를 함께 적어 두었으니, 소리를 듣고 따라 말해 보세요."], "figure": "히라가나 あいうえお 와 가타카나 アイウエオ 를 나란히 적은 글자 카드", "example": "히라가나: あ(a, 아) い(i, 이) う(u, 우) え(e, 에) お(o, 오) / 가타카나: ア イ ウ エ オ (소리는 똑같아요)", "heading": "일본어 글자는 세 가지예요"}, {"paras": ["처음 만난 사람에게는 はじめまして(hajimemashite, 하지메마시테)라고 인사해요. '처음 뵙겠습니다'라는 뜻이에요.", "낮에 만나면 こんにちは(konnichiwa, 콘니치와)도 함께 쓸 수 있어요. こんにちは의 마지막 글자 は는 이 인사말에서 '와'로 읽어요."], "figure": "두 아이가 손을 흔들며 처음 인사하는 모습", "example": "はじめまして。(hajimemashite, 하지메마시테) → 처음 뵙겠습니다.", "heading": "처음 만나면 はじめまして"}, {"paras": ["'저는 ○○예요'는 わたしは ○○です(watashi wa ○○ desu, 와타시와 ○○데스)라고 해요. わたし는 '나, 저', です는 '~예요/이에요'라는 뜻이에요.", "여기서 は는 글자 이름은 '하'지만, '~은/는'이라는 뜻으로 쓸 때는 '와(wa)'라고 읽어요. 아주 중요한 규칙이에요!", "です의 す는 아주 약하게 소리 나서 '데스'처럼 들려요. 한국 이름은 보통 가타카나로 써요. 예를 들어 '미나'는 ミナ(mina, 미나)예요."], "figure": "가슴에 손을 얹고 자기 이름을 말하는 아이", "example": "わたしは ミナです。(watashi wa mina desu, 와타시와 미나데스) → 저는 미나예요.", "heading": "わたしは ~です 로 이름을 말해요"}, {"paras": ["나라 이름 뒤에 じん(jin, 진)을 붙이면 '○○ 사람'이 돼요. 한국 사람은 かんこくじん(kankokujin, 캉코쿠진), 일본 사람은 にほんじん(nihonjin, 니혼진)이에요.", "초등학생은 しょうがくせい(shougakusei, 쇼-가쿠세이)라고 해요. 앞에서 배운 です를 붙이면 바로 문장이 돼요."], "figure": "한국과 일본 국기를 든 두 아이", "example": "かんこくじんです。(kankokujin desu, 캉코쿠진데스) → 한국 사람이에요.", "heading": "어느 나라 사람인지, 몇 학년인지도 말해요"}, {"paras": ["자기소개가 끝나면 よろしくおねがいします(yoroshiku onegaishimasu, 요로시쿠 오네가이시마스)라고 말하고 고개를 살짝 숙여요. '잘 부탁합니다'라는 뜻이에요.", "친구 이름을 부를 때는 이름 뒤에 さん(san, 상)을 붙여요. 'ミナさん'처럼요. 하지만 내 이름에는 さん을 붙이지 않아요."], "figure": "고개를 살짝 숙여 인사하는 아이", "example": "はじめまして。わたしは ミナです。かんこくじんです。よろしくおねがいします。", "heading": "마지막은 よろしくおねがいします"}], "parent_tip": "부모님께: 아이들이 가장 많이 헷갈리는 것은 '~은/는'으로 쓰인 は를 '와'로 읽는 규칙입니다. 듣기 버튼으로 소리를 먼저 들려준 뒤, 부모님이 일본 친구 역할을 맡아 \"おなまえは？\"라고 묻고 아이가 세 문장으로 자기소개를 하게 해 보세요. 글자를 외우는 것보다 소리 내어 말해 보는 경험이 먼저입니다.", "expressions": [{"en": "はじめまして", "ko": "처음 뵙겠습니다", "note": "hajimemashite (하지메마시테)"}, {"en": "こんにちは", "ko": "안녕하세요 (낮 인사)", "note": "konnichiwa (콘니치와)"}, {"en": "わたし", "ko": "나, 저", "note": "watashi (와타시)"}, {"en": "わたしは ミナです。", "ko": "저는 미나예요.", "note": "watashi wa mina desu (와타시와 미나데스)"}, {"en": "おなまえは？", "ko": "이름이 뭐예요?", "note": "onamae wa? (오나마에와?)"}, {"en": "かんこくじんです。", "ko": "한국 사람이에요.", "note": "kankokujin desu (캉코쿠진데스)"}, {"en": "にほんじん", "ko": "일본 사람", "note": "nihonjin (니혼진)"}, {"en": "しょうがくせいです。", "ko": "초등학생이에요.", "note": "shougakusei desu (쇼-가쿠세이데스)"}, {"en": "よろしくおねがいします。", "ko": "잘 부탁합니다.", "note": "yoroshiku onegaishimasu (요로시쿠 오네가이시마스)"}, {"en": "ミナさん", "ko": "미나 씨 (다른 사람 이름 뒤에 붙여요)", "note": "mina san (미나상)"}]}$j$::jsonb where slug='j5-01';
update public.lessons set title=$j$일본어로 몇 살인지 어떻게 묻고 답할까?$j$, content=$j${"quiz": [{"q": "일본어 숫자 ご(go, 고)는 얼마일까요?", "answer": 0, "choices": ["5", "2", "9", "7"], "explain": "いち・に・さん・よん・ご, 다섯 번째인 ご가 5예요."}, {"q": "なんさいですか。는 무엇을 묻는 말일까요?", "answer": 1, "choices": ["이름", "나이", "학년", "사는 곳"], "explain": "さい는 '~살'이에요. なんさい는 '몇 살'이에요."}, {"q": "'11살이에요.'를 일본어로 바르게 말한 것은?", "answer": 2, "choices": ["じゅういちさいです。", "いちじゅうさいです。", "じゅういっさいです。", "じゅうさいです。"], "explain": "11살은 소리가 바뀌어 じゅういっさい(주-잇사이)예요."}, {"q": "'6학년이에요.'를 일본어로 바르게 말한 것은?", "answer": 3, "choices": ["ろくさいです。", "ごねんせいです。", "なんねんせいですか。", "ろくねんせいです。"], "explain": "학년은 숫자 + ねんせい예요. 6은 ろく니까 ろくねんせいです예요."}, {"q": "8살은 일본어로 어떻게 말할까요?", "answer": 2, "choices": ["はちじ", "はちねんせい", "はっさい", "はっぴゃく"], "explain": "8살은 작은 っ가 들어가 はっさい(핫사이)예요. はちじ는 8시, はちねんせい는 8학년이에요."}], "intro": "새로 사귄 일본 친구가 나와 동갑인지 궁금해요. \"몇 살이야?\"라고 일본어로 물어볼 수 있다면 금방 더 친해질 수 있겠죠? 오늘은 숫자와 함께 나이를 묻고 답하는 법을 배워요.", "summary": ["일본어 숫자: いち・に・さん・よん・ご・ろく・なな・はち・きゅう・じゅう", "나이는 숫자 + さい, 묻는 말은 なんさいですか(난사이데스카)예요.", "1살 いっさい, 8살 はっさい, 10살 じゅっさい, 11살 じゅういっさい처럼 작은 っ가 들어가는 나이를 조심해요."], "keywords": [{"word": "さい", "meaning": "나이를 셀 때 숫자 뒤에 붙이는 말 (sai, 사이) — '~살'"}, {"word": "なんさい", "meaning": "몇 살 (nansai, 난사이)"}, {"word": "작은 っ", "meaning": "잠깐 멈추는 소리. いっさい(잇사이)처럼 읽어요"}, {"word": "ねんせい", "meaning": "~학년 (nensei, 넨세이)"}], "sections": [{"paras": ["일본어 숫자는 いち(ichi, 이치) 1, に(ni, 니) 2, さん(san, 상) 3, よん(yon, 욘) 4, ご(go, 고) 5예요.", "이어서 ろく(roku, 로쿠) 6, なな(nana, 나나) 7, はち(hachi, 하치) 8, きゅう(kyuu, 큐-) 9, じゅう(juu, 주-) 10이에요. 4는 し, 7은 しち라고도 하지만 오늘은 よん과 なな를 써요.", "11은 じゅういち(10+1), 12는 じゅうに(10+2)처럼 10 뒤에 숫자를 붙이면 돼요."], "figure": "손가락으로 1부터 10까지 세는 두 손", "example": "1 いち · 2 に · 3 さん · 4 よん · 5 ご · 6 ろく · 7 なな · 8 はち · 9 きゅう · 10 じゅう", "heading": "1부터 10까지 세어 봐요"}, {"paras": ["나이를 셀 때는 숫자 뒤에 さい(sai, 사이)를 붙여요. '몇 살'은 なんさい(nansai, 난사이)예요.", "'몇 살이에요?'는 なんさいですか(nansai desu ka, 난사이데스카)라고 물어요. 친구 이름을 넣어 ユナさんは なんさいですか。라고 물을 수도 있어요."], "figure": "생일 케이크 앞에서 촛불을 세는 아이", "example": "なんさいですか。(nansai desu ka, 난사이데스카) → 몇 살이에요?", "heading": "なんさいですか? 몇 살이에요?"}, {"paras": ["몇몇 나이는 소리가 조금 바뀌어요. 1살은 いっさい(issai, 잇사이), 8살은 はっさい(hassai, 핫사이), 10살은 じゅっさい(jussai, 줏사이)예요.", "작게 쓴 っ는 '잠깐 멈추는 소리'예요. 한국어 받침 'ㅅ'처럼 짧게 끊었다가 다음 글자를 읽어요.", "그래서 11살은 じゅういっさい(juuissai, 주-잇사이), 12살은 じゅうにさい(juunisai, 주-니사이)예요."], "figure": "", "example": "11さい じゅういっさい(주-잇사이) / 12さい じゅうにさい(주-니사이)", "heading": "작은 っ 가 들어가는 나이"}, {"paras": ["대답은 나이 뒤에 です를 붙이면 돼요. 11살이면 じゅういっさいです(주-잇사이데스), 12살이면 じゅうにさいです(주-니사이데스)예요.", "학년을 말하고 싶으면 숫자 뒤에 ねんせい(nensei, 넨세이)를 붙여요. 5학년은 ごねんせい(gonensei, 고넨세이), 6학년은 ろくねんせい(rokunensei, 로쿠넨세이)예요."], "figure": "가방을 멘 초등학생 두 명이 이야기하는 모습", "example": "A: なんさいですか。 B: じゅうにさいです。ろくねんせいです。 (12살이에요. 6학년이에요.)", "heading": "じゅういっさいです 로 대답해요"}], "parent_tip": "부모님께: 숫자 자체보다 1・8・10살처럼 작은 っ(촉음)가 생기는 소리 변화를 아이가 어려워합니다. 가족의 나이를 하나씩 일본어로 말해 보는 놀이가 좋습니다. 다만 어른 나이(예: 40살 よんじゅっさい)는 숫자가 길어지니, 아이 또래 나이와 학년 중심으로 연습해 주세요.", "expressions": [{"en": "なんさいですか。", "ko": "몇 살이에요?", "note": "nansai desu ka (난사이데스카)"}, {"en": "じゅういっさいです。", "ko": "11살이에요.", "note": "juuissai desu (주-잇사이데스)"}, {"en": "じゅうにさいです。", "ko": "12살이에요.", "note": "juunisai desu (주-니사이데스)"}, {"en": "いっさい", "ko": "1살", "note": "issai (잇사이)"}, {"en": "はっさい", "ko": "8살", "note": "hassai (핫사이)"}, {"en": "じゅっさい", "ko": "10살", "note": "jussai (줏사이)"}, {"en": "ごねんせいです。", "ko": "5학년이에요.", "note": "gonensei desu (고넨세이데스)"}, {"en": "ろくねんせいです。", "ko": "6학년이에요.", "note": "rokunensei desu (로쿠넨세이데스)"}, {"en": "いち、に、さん、よん、ご", "ko": "1, 2, 3, 4, 5", "note": "ichi, ni, san, yon, go (이치, 니, 상, 욘, 고)"}, {"en": "ろく、なな、はち、きゅう、じゅう", "ko": "6, 7, 8, 9, 10", "note": "roku, nana, hachi, kyuu, juu (로쿠, 나나, 하치, 큐-, 주-)"}]}$j$::jsonb where slug='j5-03';
update public.lessons set title=$j$지금 몇 시? 오늘은 무슨 요일? 일본어로 말해 볼까?$j$, content=$j${"quiz": [{"q": "いま なんじですか。의 뜻은?", "answer": 0, "choices": ["지금 몇 시예요?", "오늘은 무슨 요일이에요?", "몇 살이에요?", "지금 어디예요?"], "explain": "いま는 '지금', なんじ는 '몇 시'예요."}, {"q": "'4시'를 일본어로 바르게 말한 것은?", "answer": 1, "choices": ["よんじ", "よじ", "しじ", "よっじ"], "explain": "4시는 특별하게 よじ(요지)라고 해요."}, {"q": "すいようび는 무슨 요일일까요?", "answer": 2, "choices": ["월요일", "화요일", "수요일", "목요일"], "explain": "水(すい)는 '물 수' 자, すいようび는 수요일이에요."}, {"q": "'7시 반'을 일본어로 바르게 말한 것은?", "answer": 3, "choices": ["はちじはん", "しちじ", "はんしちじ", "しちじはん"], "explain": "7시는 しちじ, 반은 はん이에요. 그래서 しちじはん이에요."}, {"q": "오늘이 금요일이면, あした(내일)는 무슨 요일일까요?", "answer": 1, "choices": ["にちようび", "どようび", "もくようび", "げつようび"], "explain": "금요일 다음 날은 토요일, どようび예요."}], "intro": "일본 친구와 놀기로 약속했어요. \"몇 시에 만날까?\", \"토요일 어때?\" 시간과 요일을 말할 수 있어야 약속을 잡을 수 있겠죠? 오늘은 일본어로 시간과 요일을 말하는 법을 배워요.", "summary": ["시간은 숫자 + じ. 4시 よじ, 7시 しちじ, 9시 くじ는 특별해요. 30분은 はん이에요.", "요일은 月(げつ)・火(か)・水(すい)・木(もく)・金(きん)・土(ど)・日(にち) + ようび, 한국어와 순서가 같아요.", "いま なんじですか(몇 시?), きょうは なんようびですか(무슨 요일?)로 물어요."], "keywords": [{"word": "じ", "meaning": "~시 (ji, 지)"}, {"word": "はん", "meaning": "반, 30분 (han, 한)"}, {"word": "ようび", "meaning": "요일 (youbi, 요-비)"}, {"word": "いま", "meaning": "지금 (ima, 이마)"}, {"word": "きょう・あした・きのう", "meaning": "오늘・내일・어제"}], "sections": [{"paras": ["시간을 말할 때는 숫자 뒤에 じ(ji, 지)를 붙여요. 1시는 いちじ(ichiji, 이치지), 3시는 さんじ(sanji, 산지)예요.", "'지금 몇 시예요?'는 いま なんじですか(ima nanji desu ka, 이마 난지데스카)예요. いま는 '지금', なんじ는 '몇 시'예요."], "figure": "벽시계가 3시를 가리키는 거실", "example": "A: いま なんじですか。 B: さんじです。 (지금 몇 시예요? / 3시예요.)", "heading": "いま なんじですか? 지금 몇 시예요?"}, {"paras": ["대부분은 숫자 + じ지만, 세 개는 특별해요. 4시는 よじ(yoji, 요지), 7시는 しちじ(shichiji, 시치지), 9시는 くじ(kuji, 쿠지)예요.", "'반', 즉 30분은 はん(han, 한)이에요. 3시 반은 さんじはん(sanjihan, 산지한)이에요."], "figure": "아침 7시 반을 가리키는 알람시계", "example": "4시 よじ · 7시 しちじ · 9시 くじ / 7시 반 しちじはん", "heading": "조심해야 할 시간 세 개"}, {"paras": ["일본어 요일 이름은 한국어처럼 '월・화・수・목・금・토・일'을 뜻하는 한자를 써요. 뒤에 ようび(youbi, 요-비)를 붙이면 '요일'이에요.", "月(げつ) 월요일 げつようび(getsuyoubi, 게츠요-비), 火(か) 화요일 かようび(kayoubi, 카요-비), 水(すい) 수요일 すいようび(suiyoubi, 스이요-비), 木(もく) 목요일 もくようび(mokuyoubi, 모쿠요-비)", "金(きん) 금요일 きんようび(kin'youbi, 킨요-비), 土(ど) 토요일 どようび(doyoubi, 도요-비), 日(にち) 일요일 にちようび(nichiyoubi, 니치요-비)예요."], "figure": "월요일부터 일요일까지 칸이 있는 달력 한 줄", "example": "月(げつ)・火(か)・水(すい)・木(もく)・金(きん)・土(ど)・日(にち) + ようび", "heading": "요일은 한국어와 똑같은 순서!"}, {"paras": ["きょう(kyou, 쿄-)는 '오늘', あした(ashita, 아시타)는 '내일', きのう(kinou, 키노-)는 '어제'예요.", "'무슨 요일'은 なんようび(nan'youbi, 난요-비)예요. 대답은 요일 뒤에 です를 붙이면 돼요."], "figure": "금요일에 동그라미를 친 달력", "example": "A: きょうは なんようびですか。 B: きんようびです。 (오늘은 무슨 요일이에요? / 금요일이에요.)", "heading": "きょうは なんようびですか? 오늘은 무슨 요일이에요?"}], "parent_tip": "부모님께: 요일은 한자 뜻이 한국어와 같아 아이들이 금방 익힙니다. 반대로 4시(よじ)・7시(しちじ)・9시(くじ)는 숫자 읽기와 달라 자주 틀리니, 집 시계를 보며 하루에 한두 번 \"いま なんじですか。\"라고 물어봐 주세요. 이 단원에서는 '몇 분'은 다루지 않고 정각과 반(はん)만 연습합니다.", "expressions": [{"en": "いま なんじですか。", "ko": "지금 몇 시예요?", "note": "ima nanji desu ka (이마 난지데스카)"}, {"en": "さんじです。", "ko": "3시예요.", "note": "sanji desu (산지데스)"}, {"en": "よじ", "ko": "4시", "note": "yoji (요지)"}, {"en": "しちじはん", "ko": "7시 반", "note": "shichijihan (시치지한)"}, {"en": "くじ", "ko": "9시", "note": "kuji (쿠지)"}, {"en": "きょうは なんようびですか。", "ko": "오늘은 무슨 요일이에요?", "note": "kyou wa nan'youbi desu ka (쿄-와 난요-비데스카)"}, {"en": "げつようび", "ko": "월요일", "note": "getsuyoubi (게츠요-비)"}, {"en": "すいようび", "ko": "수요일", "note": "suiyoubi (스이요-비)"}, {"en": "きんようび", "ko": "금요일", "note": "kin'youbi (킨요-비)"}, {"en": "どようび", "ko": "토요일", "note": "doyoubi (도요-비)"}, {"en": "にちようび", "ko": "일요일", "note": "nichiyoubi (니치요-비)"}, {"en": "あした", "ko": "내일", "note": "ashita (아시타)"}]}$j$::jsonb where slug='j5-05';
update public.lessons set title=$j$그림일기는 어떻게 쓸까?$j$, content=$j${"narr": {"kw": "assets/audio/n/k1-16_kw.mp3", "q0": "assets/audio/n/k1-16_q0.mp3", "q1": "assets/audio/n/k1-16_q1.mp3", "q2": "assets/audio/n/k1-16_q2.mp3", "q3": "assets/audio/n/k1-16_q3.mp3", "q4": "assets/audio/n/k1-16_q4.mp3", "s0": "assets/audio/n/k1-16_s0.mp3", "s1": "assets/audio/n/k1-16_s1.mp3", "s2": "assets/audio/n/k1-16_s2.mp3", "s3": "assets/audio/n/k1-16_s3.mp3", "sum": "assets/audio/n/k1-16_sum.mp3", "cover": "assets/audio/n/k1-16_cover.mp3"}, "quiz": [{"q": "그림일기 맨 위에 쓰는 것은?", "answer": 0, "choices": ["날짜와 날씨", "친구 이름", "좋아하는 색", "내 키"], "explain": "그림일기 맨 위에는 날짜, 요일, 날씨를 써요."}, {"q": "☁️ 그림에 맞는 날씨 말은?", "answer": 1, "choices": ["맑음", "흐림", "눈", "비"], "explain": "구름이 많은 날씨는 '흐림'이에요."}, {"q": "그림일기에 쓰기 알맞은 일은?", "answer": 2, "choices": ["내년에 할 일", "동화책 줄거리", "오늘 기억에 남는 일", "친구의 비밀"], "explain": "그림일기에는 오늘 겪은 일 가운데 기억에 남는 일을 써요."}, {"q": "느낌을 쓴 문장은?", "answer": 3, "choices": ["공원에 갔다.", "그네를 탔다.", "동생과 갔다.", "정말 재미있었다."], "explain": "'재미있었다'는 마음, 곧 느낌을 나타내요."}, {"q": "❄️ 그림에 맞는 날씨 말은?", "answer": 2, "choices": ["비", "맑음", "눈", "바람"], "explain": "하얀 ❄️가 내리는 날씨는 '눈'이에요."}], "intro": "오늘 있었던 일을 그림과 글로 남겨요. 그림일기를 함께 써 봐요.", "summary": ["그림일기 맨 위에는 날짜, 요일, 날씨를 써요.", "기억에 남는 일 하나를 골라 그림으로 그려요.", "한 일을 차례대로 쓰고, 마지막에 느낌을 써요."], "keywords": [{"word": "일기", "meaning": "날마다 겪은 일과 생각을 적는 글"}, {"word": "그림일기", "meaning": "그림과 짧은 글로 쓰는 일기"}, {"word": "날씨", "meaning": "맑음, 흐림, 비, 눈처럼 하늘의 모습"}, {"word": "느낌", "meaning": "일을 겪고 든 마음(재미있었다, 슬펐다)"}], "sections": [{"paras": ["맨 위에 날짜와 요일을 써요.", "날씨도 써요. ☀️ 맑음, 🌧️ 비처럼요."], "figure": "그림일기 공책 윗부분의 날짜 칸을 가리키는 손가락", "example": "10월 13일 화요일, 날씨: ☀️ 맑음", "heading": "날짜와 날씨를 써요"}, {"paras": ["오늘 한 일 가운데 하나를 골라요.", "가장 기억에 남는 일이 좋아요."], "figure": "공원 그네를 타는 아이", "example": "🎈 동생과 공원에서 그네를 탄 일", "heading": "기억에 남는 일을 골라요"}, {"paras": ["고른 장면을 그림으로 그려요.", "누가, 어디에서, 무엇을 했는지 보이게 그려요."], "figure": "크레파스로 그림을 그리는 아이 손", "example": "🖍️ 그네를 타는 나와 웃는 동생", "heading": "그림을 그려요"}, {"paras": ["한 일을 차례대로 써요.", "마지막에 생각이나 느낌을 써요."], "figure": "그림 아래 줄 칸에 연필로 글을 쓰는 아이", "example": "동생과 공원에 갔다. 그네를 탔다. 정말 재미있었다.", "heading": "글을 써요"}], "parent_tip": "부모님께: 아이가 '아침에 일어났다. 밥을 먹었다…'처럼 하루를 다 나열하면 '오늘 가장 기억나는 일 하나만 골라 볼까?'라고 도와주세요. 글을 쓰기 전에 '누구랑, 어디서, 무엇을 했어? 기분은 어땠어?'를 말로 먼저 해 보게 하면 쓰기가 훨씬 쉬워집니다. 맞춤법보다 자기 생각을 쓴 것을 먼저 칭찬해 주세요.", "expressions": [{"en": "그림일기", "ko": "그림과 글로 쓰는 일기"}, {"en": "날씨", "ko": "하늘의 모습"}, {"en": "맑음", "ko": "☀️ 해가 쨍쨍한 날씨", "note": "[말금]"}, {"en": "흐림", "ko": "☁️ 구름이 많은 날씨"}, {"en": "비", "ko": "🌧️ 비가 오는 날씨"}, {"en": "눈", "ko": "❄️ 눈이 오는 날씨"}, {"en": "월요일", "ko": "일요일 다음 날", "note": "[워료일]"}, {"en": "오늘은 동생과 공원에 갔다.", "ko": "🎈 한 일: 누구와, 어디에", "note": "[오느른 동생과 공워네 갇따]"}, {"en": "그네를 탔다.", "ko": "한 일: 무엇을", "note": "[그네를 탇따]"}, {"en": "정말 재미있었다.", "ko": "😄 느낌", "note": "[정말 재미이썯따]"}]}$j$::jsonb where slug='k1-16';
update public.lessons set title=$j$이야기는 어떤 차례로 펼쳐질까?$j$, content=$j${"narr": {"kw": "assets/audio/n/k1-17_kw.mp3", "q0": "assets/audio/n/k1-17_q0.mp3", "q1": "assets/audio/n/k1-17_q1.mp3", "q2": "assets/audio/n/k1-17_q2.mp3", "q3": "assets/audio/n/k1-17_q3.mp3", "q4": "assets/audio/n/k1-17_q4.mp3", "s0": "assets/audio/n/k1-17_s0.mp3", "s1": "assets/audio/n/k1-17_s1.mp3", "s2": "assets/audio/n/k1-17_s2.mp3", "s3": "assets/audio/n/k1-17_s3.mp3", "sum": "assets/audio/n/k1-17_sum.mp3", "cover": "assets/audio/n/k1-17_cover.mp3"}, "quiz": [{"q": "🌱 → 🌿 → ? 다음에 올 것은?", "answer": 0, "choices": ["🌻 꽃이 피어요", "🌰 씨앗을 심어요", "🌱 싹이 나요", "🪨 돌이 굴러요"], "explain": "🌱 싹이 나고 🌿 잎이 자란 다음에는 🌻 꽃이 피어요."}, {"q": "차례를 알려 주는 말이 아닌 것은?", "answer": 3, "choices": ["먼저", "그다음에", "마지막으로", "빨간"], "explain": "'빨간'은 색깔을 꾸며 주는 말이에요."}, {"q": "'토끼와 거북'에서 토끼는 경주 중에 무엇을 했나요?", "answer": 1, "choices": ["노래를 불렀어요", "낮잠을 잤어요", "물을 마셨어요", "집에 갔어요"], "explain": "토끼는 거북을 얕보고 낮잠을 잤어요."}, {"q": "하루의 차례로 맞는 것은?", "answer": 2, "choices": ["저녁 → 아침 → 점심", "점심 → 저녁 → 아침", "아침 → 점심 → 저녁", "저녁 → 점심 → 아침"], "explain": "하루는 아침, 점심, 저녁 차례로 지나가요."}, {"q": "이야기가 마무리되는 부분은?", "answer": 2, "choices": ["처음", "가운데", "끝", "제목"], "explain": "이야기는 끝부분에서 마무리돼요."}], "intro": "이야기에는 처음, 가운데, 끝이 있어요. 차례를 알면 이야기가 쉬워져요.", "summary": ["이야기는 처음, 가운데, 끝으로 이어져요.", "'먼저, 그다음에, 마지막으로'는 차례를 알려 줘요.", "일이 일어난 차례대로 정리하면 이야기를 잘 이해할 수 있어요."], "keywords": [{"word": "차례", "meaning": "먼저와 나중을 따라 늘어놓은 순서"}, {"word": "처음·가운데·끝", "meaning": "이야기가 시작하고, 일이 생기고, 마무리되는 부분"}, {"word": "차례를 나타내는 말", "meaning": "먼저, 그다음에, 마지막으로처럼 순서를 알려 주는 말"}], "sections": [{"paras": ["이야기는 처음에 시작해요.", "가운데에서 일이 생겨요.", "끝에서 이야기가 마무리돼요."], "figure": "화분 세 개에 씨앗, 싹, 꽃이 차례로 있는 모습", "example": "🌰 씨앗을 심었어요. → 🌱 싹이 났어요. → 🌻 꽃이 피었어요.", "heading": "처음, 가운데, 끝"}, {"paras": ["'먼저', '그다음에', '마지막으로'를 써요.", "이 말을 보면 차례를 알 수 있어요."], "figure": "세면대에서 손을 씻는 아이", "example": "먼저 손을 씻어요. 그다음에 밥을 먹어요. 마지막으로 이를 닦아요.", "heading": "차례를 알려 주는 말"}, {"paras": ["'아침', '점심', '저녁'도 차례를 알려 줘요.", "시간 차례대로 일이 일어나요."], "figure": "해가 뜨는 아침과 달이 뜬 밤 그림", "example": "☀️ 아침에 일어나요. 🍱 점심을 먹어요. 🌙 저녁에 자요.", "heading": "시간을 알려 주는 말"}, {"paras": ["일이 일어난 차례대로 정리해요.", "'토끼와 거북'으로 해 봐요."], "figure": "결승선을 지나는 거북 인형", "example": "🐇🐢 경주를 해요. → 🐇 토끼가 낮잠을 자요. → 🐢 거북이 이겨요.", "heading": "이야기 차례 정리하기"}], "parent_tip": "부모님께: 그림책을 읽은 뒤 '처음에 무슨 일이 있었지? 그다음엔? 마지막엔?' 하고 세 번만 물어보세요. 아이가 이야기를 차례대로 말하는 연습이 됩니다. 요리, 양치처럼 생활 속 일도 '먼저, 그다음에'로 말해 보게 하면 좋습니다.", "expressions": [{"en": "처음", "ko": "이야기가 시작하는 부분"}, {"en": "가운데", "ko": "일이 생기는 부분"}, {"en": "끝", "ko": "이야기가 마무리되는 부분", "note": "[끋]"}, {"en": "먼저", "ko": "가장 앞에 하는 일"}, {"en": "그다음에", "ko": "먼저 한 일 바로 뒤에", "note": "[그다으메]"}, {"en": "마지막으로", "ko": "맨 끝에", "note": "[마지마그로]"}, {"en": "아침에", "ko": "☀️ 하루가 시작될 때", "note": "[아치메]"}, {"en": "저녁에", "ko": "🌙 해가 진 뒤", "note": "[저녀게]"}, {"en": "먼저 손을 씻어요.", "ko": "🧼 차례를 알려 주는 문장", "note": "[먼저 소늘 씨서요]"}, {"en": "토끼가 낮잠을 잤어요.", "ko": "🐇 이야기 가운데 부분", "note": "[토끼가 낟짜믈 자써요]"}, {"en": "거북이 경주에서 이겼어요.", "ko": "🐢 이야기 끝부분", "note": "[거부기 경주에서 이겨써요]"}]}$j$::jsonb where slug='k1-17';
update public.lessons set title=$j$감기가 ‘낫다’일까, ‘낳다’일까?$j$, content=$j${"quiz": [{"q": "바르게 쓴 문장은?", "answer": 1, "choices": ["상처가 다 낳았어요.", "상처가 다 나았어요.", "상처가 다 낮았어요.", "상처가 다 낫았어요."], "explain": "병이나 상처가 없어지는 것은 ‘낫다’예요. ‘나았어요’로 써요."}, {"q": "“손가락으로 북쪽을 ( ).” 빈칸에 알맞은 말은?", "answer": 1, "choices": ["가르쳤어요", "가리켰어요", "가르켰어요", "가리쳤어요"], "explain": "방향을 집어 보이는 것은 ‘가리키다’예요."}, {"q": "‘안’과 ‘않’을 바르게 쓴 문장은?", "answer": 2, "choices": ["오늘은 학교에 가지 안았어요.", "나는 우유를 않 마셔요.", "숙제를 아직 안 했어요.", "동생이 울지 안는다."], "explain": "‘안 했어요’는 ‘아니 했어요’의 줄임이라 바르게 썼어요. ‘-지’ 뒤에는 ‘않’을 써요."}, {"q": "바르게 쓴 낱말은?", "answer": 3, "choices": ["몇일", "금새", "설겆이", "며칠"], "explain": "‘며칠’, ‘금세’, ‘설거지’가 바른 말이에요."}, {"q": "“퀴즈의 정답을 ( ).” 빈칸에 알맞은 말은?", "answer": 0, "choices": ["맞혔어요", "맞췄어요", "마쳤어요", "맡혔어요"], "explain": "정답을 골라내는 것은 ‘맞히다’예요. ‘맞추다’는 퍼즐처럼 제자리에 끼우거나 서로 대어 볼 때 써요."}], "intro": "“감기가 빨리 낳았으면 좋겠어.” 어디가 틀렸는지 보이나요? 소리는 비슷한데 뜻과 모양이 다른 말, 자주 틀리는 말을 바르게 쓰는 방법을 알아보아요.", "summary": ["소리가 같거나 비슷해도 뜻에 따라 낫다·낳다·낮다처럼 다르게 써요.", "가르치다·가리키다, 잃어버리다·잊어버리다, 맞히다·맞추다는 뜻을 생각해 골라 써요.", "‘안’은 빼도 말이 되고, ‘않’은 ‘-지’ 뒤에 써요. 며칠·금세·설거지처럼 바른 모양을 익혀요."], "keywords": [{"word": "맞춤법", "meaning": "말을 글자로 바르게 적는 규칙"}, {"word": "낫다", "meaning": "병이나 상처가 없어져 본래대로 되다"}, {"word": "가리키다", "meaning": "손가락 등으로 방향이나 대상을 집어 보이다"}, {"word": "가르치다", "meaning": "지식이나 기술 등을 알려 주다"}, {"word": "잊어버리다", "meaning": "알았던 것을 기억하지 못하게 되다"}], "sections": [{"paras": ["‘낫다’와 ‘낮다’는 둘 다 [낟따]처럼 소리 나고, ‘낳다’[나타]도 소리가 비슷해서 헷갈리기 쉬워요. 이런 말은 문장의 뜻을 생각해서 알맞은 낱말을 골라야 해요.", "‘낫다’는 병이나 상처가 없어진다는 뜻, ‘낳다’는 아기나 알을 몸 밖으로 내놓는다는 뜻, ‘낮다’는 높지 않다는 뜻이에요."], "figure": "책상 위에 놓인 달걀 바구니, 반창고, 낮은 블록 탑", "example": "감기가 다 나았어요. / 닭이 알을 낳았어요. / 담장이 낮아요.\n편지를 부쳐요(보내요). / 우표를 붙여요(달라붙게 해요).\n반드시(꼭) 지킬게요. / 반듯이(바르게) 앉아요.", "heading": "소리는 같은데 뜻이 다른 말"}, {"paras": ["‘가르치다’는 지식이나 기술을 알려 준다는 뜻이고, ‘가리키다’는 손가락 등으로 방향이나 대상을 집어 보인다는 뜻이에요.", "‘잃어버리다’는 물건이 없어진 것이고, ‘잊어버리다’는 기억하지 못하는 것이에요. ‘맞히다’는 정답을 골라낸다는 뜻이고, ‘맞추다’는 서로 대어 보거나 제자리에 끼운다는 뜻이에요."], "figure": "손가락으로 창밖을 가리키는 아이와 칠판 앞에서 설명하는 손", "example": "선생님께서 수학을 가르치세요. / 손가락으로 산을 가리켜요.\n지갑을 잃어버렸어요. / 숙제를 잊어버렸어요.\n퀴즈 정답을 맞혔어요. / 퍼즐 조각을 맞췄어요.", "heading": "뜻이 헷갈리는 말"}, {"paras": ["‘안’은 ‘아니’를 줄인 말로, 움직임을 나타내는 말 앞에 써요. ‘않’은 ‘아니하’를 줄인 말로, ‘-지’ 뒤에 써요.", "헷갈릴 때는 그 낱말을 빼 보세요. ‘안’은 빼도 문장이 되지만 ‘않’은 빼면 문장이 어색해져요."], "figure": "공책에 ‘안’과 ‘않’을 두 칸으로 나누어 정리한 모습", "example": "밥을 안 먹었어요. (아니 먹었어요) / 밥을 먹지 않았어요. (먹지 아니하였어요)", "heading": "‘안’과 ‘않’ 구별하기"}, {"paras": ["소리 나는 대로 쓰다가 자주 틀리는 말들이 있어요. 바른 모양을 눈에 익혀 두면 틀리지 않아요.", "‘되’와 ‘돼’가 헷갈리면 ‘하’와 ‘해’를 넣어 보세요. ‘하’가 어울리면 ‘되’, ‘해’가 어울리면 ‘돼’예요."], "figure": "빨간 색연필로 틀린 낱말을 고친 받아쓰기 공책", "example": "몇일 ✕ → 며칠 ○ / 금새 ✕ → 금세 ○ / 설겆이 ✕ → 설거지 ○ / 어떻해 ✕ → 어떻게, 어떡해 ○\n그러면 안 돼요(안 해요 ○). / 의사가 되고 싶어요(하고 ○).", "heading": "자주 틀리는 말, 이렇게 써요"}], "parent_tip": "맞춤법은 규칙을 외우기보다 문장 속에서 자주 보고 써 보는 것이 효과적입니다. 아이의 일기나 문자 메시지에서 헷갈리는 말이 나오면 바로 고쳐 주기보다 “이 말은 무슨 뜻으로 쓴 거야?”라고 물어 스스로 고르게 해 주세요. ‘안/않’, ‘되/돼’는 빼 보기와 하/해 넣어 보기 방법을 함께 연습하면 오래 기억합니다.", "expressions": []}$j$::jsonb where slug='k3-05';
update public.lessons set title=$j$긴 글을 짧게 정리하는 비법은 무엇일까?$j$, content=$j${"quiz": [{"q": "'반면에', '이와 달리' 같은 말이 자주 나오는 글의 구조는?", "answer": 1, "choices": ["순서", "비교와 대조", "나열", "문제와 해결"], "explain": "두 대상의 다른 점을 말할 때 '반면에', '이와 달리'를 써요."}, {"q": "'그래서', '그 결과'가 자주 나오는 구조에 알맞은 정리 틀은?", "answer": 1, "choices": ["벤 다이어그램", "원인 → 결과 화살표 틀", "두 칸 비교표", "마인드맵의 가지 하나"], "explain": "'그래서', '그 결과'는 원인과 결과 구조에 쓰이므로 원인 → 결과 틀이 알맞아요."}, {"q": "요약하는 방법으로 알맞지 __않은__ 것은?", "answer": 2, "choices": ["자세한 예는 지운다.", "비슷한 내용은 더 큰 말로 묶는다.", "내 생각을 덧붙여 더 재미있게 쓴다.", "문단의 중심 문장을 고른다."], "explain": "요약문에는 원래 글의 내용만 간추려 쓰고 내 생각은 덧붙이지 않아요."}, {"q": "'연필, 지우개, 자, 공책'을 하나로 묶을 때 가장 알맞은 말은?", "answer": 0, "choices": ["학용품", "장난감", "음식", "옷"], "explain": "모두 공부할 때 쓰는 물건이므로 '학용품'으로 묶을 수 있어요."}, {"q": "'먼저 – 다음으로 – 마지막으로'가 나오는 글은 어떤 구조일까요?", "answer": 3, "choices": ["비교와 대조", "원인과 결과", "문제와 해결", "순서(시간)"], "explain": "일이나 과정의 차례를 나타내는 말이므로 순서 구조예요."}], "intro": "설명하는 글을 다 읽었는데 친구가 \"무슨 내용이야?\" 하고 물으면 말문이 막힐 때가 있지요. 글이 어떤 짜임(구조)으로 쓰였는지 알면 긴 글도 몇 문장으로 쏙쏙 정리할 수 있어요.", "summary": ["설명하는 글의 구조에는 나열, 순서, 비교와 대조, 원인과 결과, 문제와 해결이 있어요.", "구조를 알려 주는 말을 찾고, 구조에 알맞은 틀에 내용을 정리해요.", "요약은 중요하지 않은 내용은 지우고, 비슷한 것은 묶고, 중심 내용을 골라 짧게 쓰는 것이에요."], "keywords": [{"word": "글의 구조", "meaning": "글쓴이가 내용을 짜 놓은 방법이나 뼈대"}, {"word": "나열", "meaning": "여러 가지 내용을 하나씩 늘어놓는 구조"}, {"word": "비교와 대조", "meaning": "두 대상의 같은 점(비교)과 다른 점(대조)을 밝히는 구조"}, {"word": "원인과 결과", "meaning": "어떤 일이 일어난 까닭과 그로 인해 생긴 일을 밝히는 구조"}, {"word": "요약", "meaning": "글의 중요한 내용을 간추려 짧게 정리하는 것"}, {"word": "중심 문장", "meaning": "한 문단에서 가장 중요한 내용을 담은 문장"}], "sections": [{"paras": ["글의 구조는 글쓴이가 내용을 어떤 순서와 방법으로 짜 놓았는지를 말해요. 집에 뼈대가 있듯이 글에도 뼈대가 있어요.", "설명하는 글에서 자주 쓰는 구조에는 '나열', '순서(시간)', '비교와 대조', '원인과 결과', '문제와 해결'이 있어요.", "글의 구조를 알면 중요한 내용이 어디에 있는지 쉽게 찾을 수 있어서 요약하기가 훨씬 편해져요."], "figure": "집의 뼈대(기둥과 보) 그림 옆에 글의 문단들이 뼈대처럼 이어져 있는 도식", "example": "글의 구조 다섯 가지: 나열(여러 가지를 늘어놓음) / 순서(시간이나 과정의 차례) / 비교와 대조(같은 점과 다른 점) / 원인과 결과(까닭과 그로 인한 일) / 문제와 해결(문제 상황과 해결 방법)", "heading": "글의 구조란 무엇일까요?"}, {"paras": ["나열 구조는 여러 가지 내용을 하나씩 늘어놓아요. '첫째, 둘째', '또한', '그리고' 같은 말이 자주 나와요.", "순서 구조는 시간이나 과정의 차례대로 써요. '먼저', '다음으로', '마지막으로', '처음에는' 같은 말이 나와요.", "비교와 대조 구조는 두 대상의 같은 점(비교)과 다른 점(대조)을 써요. '둘 다', '마찬가지로', '이와 달리', '반면에' 같은 말이 나와요.", "원인과 결과 구조는 어떤 일이 일어난 까닭과 그 결과를 써요. '왜냐하면', '그래서', '그 결과', '때문에' 같은 말이 나와요. 문제와 해결 구조는 문제 상황을 밝히고 해결 방법을 제시해요."], "figure": "다섯 가지 글 구조(나열, 순서, 비교·대조, 원인·결과, 문제·해결)를 각각 간단한 도형 틀로 나타낸 표", "example": "비교와 대조의 예: 고양이와 개는 둘 다 사람과 함께 사는 반려동물이다. 반면에 고양이는 혼자 있는 시간을 즐기고, 개는 주인과 함께 움직이기를 좋아한다.", "heading": "구조마다 자주 나오는 말이 있어요"}, {"paras": ["글의 구조를 파악했으면 그 구조에 어울리는 틀(그림 틀)에 내용을 옮겨 적어 보세요.", "비교와 대조는 두 원이 겹친 벤 다이어그램이나 두 칸 표, 순서는 화살표로 이어진 칸, 원인과 결과는 '원인 → 결과' 화살표 틀이 알맞아요.", "틀에 정리하면 중요한 내용과 덜 중요한 내용이 한눈에 구분돼요."], "figure": "갯벌 사진 아래 '원인 → 결과' 화살표 틀이 그려진 공책", "example": "〈글〉 갯벌에는 많은 생물이 산다. 그런데 갯벌을 메워 땅을 만드는 일이 늘어났다. 그 결과 갯벌에 사는 게와 조개가 살 곳을 잃었고, 이들을 먹고 사는 철새도 줄어들었다.\n〈틀〉 원인: 갯벌을 메워 땅을 만듦 → 결과: 게·조개가 살 곳을 잃음 → 철새도 줄어듦", "heading": "구조에 알맞은 틀로 정리해요"}, {"paras": ["요약은 글의 중요한 내용을 간추려 짧게 정리하는 것이에요. 요약할 때는 다음 방법을 써요.", "① 중요하지 않은 내용(자세한 예, 되풀이되는 말)은 지워요. ② 비슷한 내용은 더 큰 말로 묶어요. 예를 들어 '사과, 배, 감'은 '과일'로 묶을 수 있어요. ③ 문단마다 중심 문장을 골라요. 중심 문장이 없으면 중심 내용을 직접 만들어요.", "마지막으로 글의 구조가 드러나도록 문단의 중심 내용을 이어서 한두 문장으로 써요."], "figure": "글에 연필로 줄을 긋고 동그라미를 친 공책 페이지", "example": "〈원래 문장〉 운동장에는 축구공, 농구공, 배구공, 줄넘기가 흩어져 있었다.\n〈묶어서 요약〉 운동장에 운동 기구가 흩어져 있었다.", "heading": "요약하는 방법: 지우고, 묶고, 고르기"}, {"paras": ["아래 글은 순서 구조로 쓰였어요. '먼저, 다음으로, 마지막으로'를 찾아 과정을 정리한 다음 요약해 보세요.", "요약문에는 글쓴이의 생각을 바꾸거나 내 생각을 덧붙이지 않아요. 원래 글의 뜻을 그대로 짧게 나타내야 해요."], "figure": "헌 종이 → 종이 죽 → 거르기 → 펴서 누르기 → 말리기 과정을 화살표로 이은 그림", "example": "〈글〉 종이를 다시 쓸 수 있게 만드는 과정은 다음과 같다. 먼저 모은 헌 종이를 물에 불려 죽처럼 만든다. 다음으로 종이 죽에서 잉크와 이물질을 걸러 낸다. 그다음 깨끗해진 종이 죽을 얇게 펴서 눌러 물기를 뺀다. 마지막으로 뜨거운 열로 말리면 새 종이가 된다.\n〈요약〉 헌 종이는 물에 불려 종이 죽으로 만들고, 잉크와 이물질을 걸러 낸 뒤, 얇게 펴서 물기를 빼고 말리면 새 종이가 된다.", "heading": "직접 요약해 봐요"}], "parent_tip": "아이들은 요약을 '앞부분만 옮겨 적기'나 '마음에 드는 문장 고르기'로 오해하기 쉽습니다. 신문 기사나 책의 한 단락을 함께 읽고 \"이 글은 무엇과 무엇을 비교했니?\", \"세 문장으로 줄이면 어떻게 될까?\"라고 물어보세요. 구조를 알려 주는 말(반면에, 그 결과, 먼저 등)에 동그라미를 치는 습관을 들이면 좋습니다.", "expressions": []}$j$::jsonb where slug='k5-02';
update public.lessons set title=$j$생각이 다를 때, 싸우지 않고 결정하는 방법은?$j$, content=$j${"quiz": [{"q": "토론 논제로 가장 알맞은 것은?", "answer": 1, "choices": ["가을 운동회를 어디에서 할까?", "학교에서 실내화를 신어야 한다.", "운동회는 재미있다.", "쓸데없는 학원은 줄이고 놀이 시간은 늘려야 한다."], "explain": "찬반이 나뉘는 한 가지 주장을 '~해야 한다.'로 썼어요. 4번은 두 가지 내용이 섞였고 '쓸데없는'이라는 편드는 말이 있어요."}, {"q": "초등학교 토론 절차의 차례로 알맞은 것은?", "answer": 2, "choices": ["반론하기 → 주장 펼치기 → 판정하기 → 주장 다지기", "주장 다지기 → 주장 펼치기 → 반론하기 → 판정하기", "주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기", "판정하기 → 반론하기 → 주장 펼치기 → 주장 다지기"], "explain": "먼저 주장을 펼치고, 반론하고, 주장을 다진 뒤 판정해요."}, {"q": "토론과 토의의 차이로 알맞은 것은?", "answer": 0, "choices": ["토론은 찬성과 반대로 나뉘어 어느 주장이 타당한지 따진다.", "토론은 여러 사람이 의견을 모아 함께 방법을 찾는다.", "토의는 반드시 판정단이 있어야 한다.", "토론에는 근거가 필요 없다."], "explain": "토론은 찬반으로 나뉘고, 토의는 의견을 모아 해결 방법을 찾아요."}, {"q": "토론할 때의 태도로 알맞지 __않은__ 것은?", "answer": 3, "choices": ["상대가 말할 때 메모하며 듣는다.", "사회자의 안내에 따라 말한다.", "근거의 문제점을 따져 반론한다.", "상대가 틀렸다고 생각되면 바로 끼어들어 말한다."], "explain": "상대의 말이 끝날 때까지 기다렸다가 자기 차례에 말해야 해요."}], "intro": "\"교실에서 반려 식물을 키워야 할까?\" 반 친구들 생각이 둘로 나뉘었어요. 목소리 큰 사람이 이기는 게 아니라, 근거를 들어 차례대로 말하고 듣는 방법이 있어요. 바로 '토론'이에요.", "summary": ["토론은 찬성편과 반대편이 근거를 들어 상대를 설득하는 말하기예요.", "논제는 찬반이 나뉘는 한 가지 주장을 '~해야 한다.' 꼴로 써요.", "토론은 주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기 차례로 하고, 상대를 존중하며 차례를 지켜요."], "keywords": [{"word": "토론", "meaning": "어떤 문제에 대해 찬성과 반대로 나뉘어 근거를 들어 상대를 설득하는 말하기"}, {"word": "논제", "meaning": "토론에서 다룰 주제로, 찬반이 나뉘는 한 가지 주장"}, {"word": "반론", "meaning": "상대편 주장이나 근거의 문제점을 짚어 반박하는 것"}, {"word": "사회자", "meaning": "토론의 차례와 시간을 안내하며 토론을 이끄는 사람"}, {"word": "판정단", "meaning": "토론을 듣고 어느 편이 더 설득력 있었는지 판단하는 사람들"}, {"word": "출처", "meaning": "자료나 정보가 나온 곳"}], "sections": [{"paras": ["토론은 어떤 문제에 대해 찬성편과 반대편이 각각 근거를 들어 자기 주장이 옳다고 말하며 상대를 설득하는 말하기예요.", "여러 사람이 생각을 모아 좋은 방법을 찾는 '토의'와 달리, 토론은 찬성과 반대 가운데 어느 주장이 더 타당한지 따져 보는 것이에요.", "토론을 하면 한 가지 문제를 여러 쪽에서 생각해 볼 수 있고, 근거를 들어 말하는 힘이 길러져요."], "figure": "교실 책상이 양쪽으로 마주 보게 놓이고 가운데에 사회자 자리가 있는 토론 모습", "example": "토의: \"학급 문고를 어떻게 꾸밀까?\"(여러 의견을 모음) / 토론: \"학급 문고에 만화책을 두어야 한다.\"(찬성과 반대로 나뉨)", "heading": "토론은 찬성과 반대로 나뉘어 말하는 것이에요"}, {"paras": ["토론에서 이야기할 주제를 '논제'라고 해요. 논제는 찬성과 반대로 의견이 뚜렷하게 나뉘어야 해요.", "논제는 한 가지 내용만 담아 '~해야 한다.' 꼴의 긍정문으로 써요. 누구나 알 수 있는 쉬운 말로 쓰고, 어느 한쪽 편을 드는 말은 넣지 않아요.", "\"우리 반은 몇 명일까?\"처럼 사실을 묻거나, \"점심 메뉴는 무엇이 좋을까?\"처럼 답이 여러 개인 것은 토론 논제로 알맞지 않아요."], "figure": "칠판에 '~해야 한다.'로 끝나는 논제가 적혀 있고 그 아래 찬성·반대 칸이 나뉜 모습", "example": "알맞은 논제: 초등학생도 학교에서 휴대 전화를 쓸 수 있어야 한다.\n알맞지 않은 논제: 나쁜 게임은 금지하고 숙제는 줄여야 한다.(두 가지 내용이 섞이고 '나쁜'이라는 편드는 말이 들어감)", "heading": "논제는 찬반이 나뉘는 한 가지 주장으로"}, {"paras": ["토론은 정해진 차례에 따라 진행해요. 초등학교에서는 보통 '주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기'의 차례로 해요.", "① 주장 펼치기: 찬성편과 반대편이 차례로 자기 주장과 근거를 말해요. ② 반론하기: 상대편 근거의 문제점을 짚고 질문하거나 반박해요. ③ 주장 다지기: 반론을 듣고 자기편 주장을 한 번 더 정리해 강조해요. ④ 판정하기: 판정단이 어느 편이 더 설득력 있었는지 정해요.", "토론에는 토론을 이끄는 사회자, 주장을 펴는 토론자(찬성편·반대편), 결과를 판단하는 판정단이 있어요."], "figure": "주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기를 네 칸 화살표로 나타낸 도식", "example": "사회자: \"지금부터 '교실에서 반려 식물을 키워야 한다.'를 논제로 토론을 시작하겠습니다. 먼저 찬성편 주장을 들어 보겠습니다.\"", "heading": "토론의 절차를 알아봐요"}, {"paras": ["토론에서 이기려면 주장보다 근거가 더 중요해요. 근거는 주장과 관련이 있고, 사실이며, 믿을 만한 자료여야 해요.", "조사 결과, 전문가의 말, 책이나 신문의 내용, 실제 경험 등을 근거 자료로 쓸 수 있어요. 자료를 쓸 때는 어디에서 가져왔는지(출처)를 밝혀요.", "반론할 때는 상대의 근거가 사실인지, 주장과 관련이 있는지, 자료가 믿을 만한지를 따져요."], "figure": "교실 창가에 놓인 작은 화분들과 물뿌리개", "example": "찬성편 근거: 식물을 기르면 교실 공기가 맑아지고, 학생들이 생명을 돌보며 책임감을 기를 수 있습니다.\n반대편 반론: 방학 동안에는 아무도 물을 주지 못해 식물이 죽을 수 있습니다. 이것은 오히려 생명을 소중히 여기지 않는 일이 아닐까요?", "heading": "근거는 믿을 만한 자료로"}, {"paras": ["토론은 다투는 것이 아니라 생각을 나누는 것이에요. 상대편 친구를 존중하는 태도가 꼭 필요해요.", "사회자의 안내에 따라 정해진 시간과 차례를 지켜 말해요. 상대가 말할 때는 끼어들지 말고 끝까지 들으며 메모해요.", "상대의 의견을 반박할 때도 사람을 탓하지 않고 근거만 따져요. 바른 말과 알맞은 목소리로 말해요."], "figure": "손을 들고 차례를 기다리는 아이와 메모하며 듣는 아이들", "example": "좋은 반론: \"찬성편에서 공기가 맑아진다고 하셨는데, 화분 몇 개로 교실 공기가 얼마나 달라지는지 자료가 있나요?\"\n나쁜 반론: \"그건 말도 안 돼! 너는 아무것도 모르잖아.\"", "heading": "토론할 때 지킬 예절"}], "parent_tip": "아이들은 반론을 '상대를 이기는 말'로 생각해 감정적으로 말하기 쉽습니다. 집에서 \"주말에 게임 시간을 늘려야 한다\" 같은 가벼운 논제로 가족 토론을 해 보고, 아이에게 일부러 자기 생각과 반대편을 맡겨 보세요. 반대 입장의 근거를 찾아보는 경험이 생각을 넓혀 줍니다.", "expressions": []}$j$::jsonb where slug='k5-04';
update public.lessons set title=$j$여행의 추억을 글로 오래 간직하려면?$j$, content=$j${"quiz": [{"q": "기행문의 세 요소가 __아닌__ 것은?", "answer": 3, "choices": ["여정", "견문", "감상", "주장"], "explain": "기행문의 세 요소는 여정, 견문, 감상이에요. 주장은 논설문의 요소예요."}, {"q": "\"오후 두 시쯤 배를 타고 섬에 도착했다.\"는 기행문의 어떤 요소일까요?", "answer": 0, "choices": ["여정", "견문", "감상", "다짐"], "explain": "언제, 어디로 이동했는지를 나타내므로 여정이에요."}, {"q": "\"등대 아래에서 바라본 바다는 하늘과 맞닿아 끝이 보이지 않았다.\"는 어떤 요소일까요?", "answer": 1, "choices": ["여정", "견문", "감상", "까닭"], "explain": "여행하며 본 모습을 나타내므로 견문이에요."}, {"q": "기행문의 '끝' 부분에 들어갈 내용으로 알맞은 것은?", "answer": 3, "choices": ["여행을 떠나게 된 까닭", "출발할 때의 설레는 마음", "첫 번째 장소에서 본 것", "여행을 마치며 든 전체적인 생각과 느낌"], "explain": "끝부분에는 여행 전체에 대한 생각과 느낌, 다짐을 써요."}], "intro": "가족과 다녀온 여행, 시간이 지나면 어디에 갔는지, 무엇을 느꼈는지 조금씩 잊혀요. 여행하며 겪은 일을 글로 남기면 언제든 그날로 돌아갈 수 있어요. 이런 글을 '기행문'이라고 해요.", "summary": ["기행문은 여행하며 보고 듣고 겪은 일과 생각·느낌을 쓴 글이에요.", "기행문에는 여정(여행 차례), 견문(보고 들은 것), 감상(생각과 느낌)이 골고루 들어가요.", "처음 – 가운데 – 끝 짜임으로, 여정의 차례에 따라 문단을 나누어 써요."], "keywords": [{"word": "기행문", "meaning": "여행하면서 보고 듣고 겪은 일과 생각·느낌을 쓴 글"}, {"word": "여정", "meaning": "여행한 차례나 과정"}, {"word": "견문", "meaning": "여행하면서 보거나 들은 것"}, {"word": "감상", "meaning": "보고 들은 것에 대한 생각이나 느낌"}, {"word": "해설사", "meaning": "관광지나 문화재에서 그곳에 대해 설명해 주는 사람"}], "sections": [{"paras": ["기행문은 여행하면서 보고, 듣고, 겪은 일과 그때의 생각이나 느낌을 쓴 글이에요.", "일기와 비슷하지만, 기행문은 장소를 옮겨 다니는 여행을 중심으로 쓴다는 점이 달라요.", "기행문을 쓰면 여행의 추억을 오래 간직할 수 있고, 읽는 사람에게 그 장소에 대한 정보와 느낌을 함께 전할 수 있어요."], "figure": "여행 가방 옆에 기차표, 지도, 작은 공책이 놓여 있는 모습", "example": "일기: 하루 동안 있었던 일 가운데 기억에 남는 일을 씀 / 기행문: 여행하며 장소를 옮겨 다닌 차례에 따라 보고 듣고 느낀 것을 씀", "heading": "기행문은 여행의 기록이에요"}, {"paras": ["여정은 여행한 차례나 과정이에요. 언제, 어디에서 어디로 갔는지를 나타내요.", "견문은 여행하면서 보거나 들은 것이에요. 그곳의 모습, 안내판이나 해설사에게 들은 설명 등이 해당해요.", "감상은 보거나 들은 것에 대한 생각이나 느낌이에요. 기행문에는 이 세 가지가 골고루 들어가야 해요."], "figure": "여정·견문·감상을 발자국·눈과 귀·하트 그림으로 나타낸 세 칸 도식", "example": "여정: 아침 일찍 기차를 타고 경주역에 도착했다.\n견문: 첨성대는 돌을 둥글게 쌓아 올린 모양이었다. 해설사께서 신라 사람들이 하늘을 관찰하던 곳으로 알려져 있다고 하셨다.\n감상: 오래전 사람들이 별을 보려고 이렇게 정성껏 돌을 쌓았다니 놀라웠다.", "heading": "기행문의 세 요소: 여정, 견문, 감상"}, {"paras": ["처음 부분에는 여행을 떠나게 된 까닭, 떠날 때의 마음, 출발하는 모습을 써요.", "가운데 부분에는 여정에 따라 장소를 옮겨 가며 견문과 감상을 자세히 써요. 장소가 바뀔 때마다 문단을 나누면 읽기 쉬워요.", "끝부분에는 여행을 마치며 든 전체적인 생각과 느낌, 다짐 등을 써요."], "figure": "처음·가운데·끝을 출발역·여러 정류장·도착역이 있는 기찻길로 나타낸 그림", "example": "처음: 사회 시간에 배운 신라의 문화재를 직접 보고 싶어서 가족과 경주로 떠났다.\n가운데: 첨성대 → 불국사 → 박물관 차례로 본 것과 느낀 점\n끝: 책으로만 보던 문화재를 직접 보니 우리 조상들의 솜씨가 더 자랑스럽게 느껴졌다.", "heading": "기행문의 짜임: 처음 – 가운데 – 끝"}, {"paras": ["아래 글을 읽고 여정, 견문, 감상을 찾아보세요. 여정은 '~에 도착했다, ~로 이동했다', 견문은 '~이 보였다, ~라고 하셨다', 감상은 '~라고 느꼈다, ~ 신기했다' 같은 말에서 찾을 수 있어요."], "figure": "절 마당에 서로 다른 모양의 두 석탑이 마주 서 있는 모습", "example": "점심을 먹고 버스를 타고 불국사로 향했다.(여정) 절 안으로 들어가니 대웅전 앞마당에 탑 두 개가 마주 서 있었다. 하나는 화려하게 장식된 다보탑이고, 다른 하나는 단정하고 반듯한 석가탑이었다.(견문) 같은 마당에 있는데도 두 탑의 모습이 이렇게 다르다는 것이 참 신기했다. 나는 꾸밈이 적은 석가탑이 더 마음에 들었다.(감상)", "heading": "기행문 한 문단 읽어 보기"}, {"paras": ["여행하면서 짧게라도 메모하고 사진을 찍어 두면 나중에 글을 쓸 때 큰 도움이 돼요. 안내판이나 안내 책자의 내용도 기록해 두세요.", "견문은 눈에 보이는 모습뿐 아니라 소리, 냄새, 맛까지 자세히 쓰면 생생해져요. 감상은 '좋았다, 재미있었다'로 끝내지 말고 왜 그렇게 느꼈는지 함께 써요.", "글을 다 쓰면 여정·견문·감상이 골고루 들어갔는지, 여정의 차례가 바른지 확인하며 고쳐 써요."], "figure": "바닷가 바위에 앉아 수첩에 메모하는 아이의 손과 파도", "example": "밋밋한 감상: 바다가 좋았다.\n생생한 감상: 철썩이는 파도 소리를 들으며 짭짤한 바닷바람을 맞으니 가슴속까지 시원해지는 것 같았다.", "heading": "생생한 기행문을 쓰는 방법"}], "parent_tip": "아이들은 기행문을 \"어디 가서 뭐 했다\"는 여정 위주로만 쓰기 쉽습니다. 여행 중에 \"여기서 무슨 소리가 들려?\", \"이걸 보니 어떤 생각이 들어?\"처럼 견문과 감상을 끌어내는 질문을 해 주세요. 사진을 찍을 때 아이에게 한 줄 메모를 함께 남기게 하면 글쓰기가 훨씬 쉬워집니다. 먼 여행이 아니어도 동네 시장이나 공원 나들이로 충분히 연습할 수 있습니다.", "expressions": []}$j$::jsonb where slug='k5-09';
update public.lessons set title=$j$누가 더 길고, 무겁고, 넓을까?$j$, content=$j${"narr": {"kw": "assets/audio/n/m1-04_kw.mp3", "q0": "assets/audio/n/m1-04_q0.mp3", "q1": "assets/audio/n/m1-04_q1.mp3", "q2": "assets/audio/n/m1-04_q2.mp3", "q3": "assets/audio/n/m1-04_q3.mp3", "s0": "assets/audio/n/m1-04_s0.mp3", "s1": "assets/audio/n/m1-04_s1.mp3", "s2": "assets/audio/n/m1-04_s2.mp3", "s3": "assets/audio/n/m1-04_s3.mp3", "sum": "assets/audio/n/m1-04_sum.mp3", "cover": "assets/audio/n/m1-04_cover.mp3"}, "quiz": [{"q": "길이를 비교할 때 먼저 할 일은?", "answer": 0, "choices": ["한쪽 끝을 맞춰요", "색을 비교해요", "무게를 들어 봐요", "눈을 감아요"], "explain": "한쪽 끝을 맞춰야 다른 쪽 끝을 보고 비교할 수 있어요."}, {"q": "시소에서 🐻 곰 쪽이 아래로 내려갔어요. 더 무거운 쪽은?", "answer": 1, "choices": ["🐰 토끼", "🐻 곰", "똑같아요", "알 수 없어요"], "explain": "아래로 내려간 쪽이 더 무거워요."}, {"q": "🚪 문과 📒 공책을 겹쳤을 때 문이 남았어요. 더 넓은 것은?", "answer": 3, "choices": ["📒 공책", "똑같아요", "알 수 없어요", "🚪 문"], "explain": "겹쳤을 때 남는 쪽이 더 넓어요."}, {"q": "줄 가는 클립 4개, 줄 나는 클립 7개 길이예요. 더 긴 줄은?", "answer": 2, "choices": ["줄 가", "똑같아요", "줄 나", "알 수 없어요"], "explain": "클립이 더 많이 필요한 줄 나가 더 길어요."}], "intro": "✏️ 연필과 🖍️ 크레파스, 어느 것이 더 길까요? 🍉 수박과 🍎 사과는 어느 것이 더 무거울까요? 오늘은 비교하는 방법을 배워요.", "summary": ["길이는 한쪽 끝을 맞춰 비교해요.", "무게는 들어 보거나 저울에서 내려간 쪽이 더 무거워요.", "넓이는 겹쳐서 남는 쪽이 더 넓어요."], "keywords": [{"word": "길다·짧다", "meaning": "길이를 비교할 때 쓰는 말"}, {"word": "무겁다·가볍다", "meaning": "무게를 비교할 때 쓰는 말"}, {"word": "넓다·좁다", "meaning": "넓이를 비교할 때 쓰는 말"}, {"word": "가장", "meaning": "여러 개 중에서 제일이라는 뜻(가장 길다, 가장 무겁다)"}], "sections": [{"paras": ["길이를 비교할 때는 한쪽 끝을 맞춰요.", "다른 쪽 끝이 더 나온 것이 더 길어요.", "키는 발끝을 맞추고 서서 비교해요."], "figure": "책상 위에 연필과 크레파스를 왼쪽 끝을 맞춰 나란히 놓은 모습", "example": "✏️ 연필과 🖍️ 크레파스의 왼쪽 끝을 맞추면 연필이 더 나와요 → 연필이 더 길어요.", "heading": "길이 비교: 끝을 맞춰요"}, {"paras": ["두 손에 하나씩 들어 보면 무게를 느낄 수 있어요.", "시소나 양팔 저울에서는 아래로 내려간 쪽이 더 무거워요."], "figure": "장난감 양팔 저울에 큰 과일과 작은 과일이 올라가 한쪽이 기울어진 모습", "example": "🍉 수박과 🍎 사과를 양팔 저울에 올리면 수박 쪽이 내려가요 → 수박이 더 무거워요.", "heading": "무게 비교: 들어 보고 달아 봐요"}, {"paras": ["넓이는 겹쳐 보면 알 수 있어요.", "겹쳤을 때 남는 부분이 있는 쪽이 더 넓어요.", "다른 쪽에 모두 가려져서 남는 부분이 없는 쪽이 더 좁아요. 둘 다 남지 않으면 넓이가 같아요."], "figure": "공책 위에 작은 메모지를 겹쳐 놓은 모습", "example": "📒 공책 위에 우표를 올리면 공책이 많이 남아요 → 공책이 더 넓어요.", "heading": "넓이 비교: 겹쳐 봐요"}, {"paras": ["끝을 맞추기 어려우면 같은 물건으로 재어요.", "클립 몇 개만큼인지 세어 봐요.", "클립 수가 많을수록 더 길어요."], "figure": "끈 두 줄 옆에 종이 클립을 줄지어 놓아 길이를 잰 모습", "example": "① 줄 가: 클립 5개, 줄 나: 클립 8개 ② 8이 5보다 커요. ③ 줄 나가 더 길어요. 8 − 5 = 3이니 클립 3개만큼 더 길어요.", "heading": "이렇게 풀어요: 클립으로 재어 비교하기"}], "parent_tip": "아이들은 '크다'라는 말을 길이·무게·넓이 모두에 쓰는 경우가 많습니다. '길다/무겁다/넓다'처럼 정확한 말로 바꿔 말하게 해 주세요. 큰 것이 늘 무겁지는 않다(풍선과 돌)는 것도 직접 들어 보며 느끼게 하면 좋습니다.", "expressions": []}$j$::jsonb where slug='m1-04';
update public.lessons set title=$j$두 자리 수, 어떻게 더하고 뺄까?$j$, content=$j${"narr": {"kw": "assets/audio/n/m1-06_kw.mp3", "q0": "assets/audio/n/m1-06_q0.mp3", "q1": "assets/audio/n/m1-06_q1.mp3", "q2": "assets/audio/n/m1-06_q2.mp3", "q3": "assets/audio/n/m1-06_q3.mp3", "s0": "assets/audio/n/m1-06_s0.mp3", "s1": "assets/audio/n/m1-06_s1.mp3", "s2": "assets/audio/n/m1-06_s2.mp3", "s3": "assets/audio/n/m1-06_s3.mp3", "sum": "assets/audio/n/m1-06_sum.mp3", "cover": "assets/audio/n/m1-06_cover.mp3"}, "quiz": [{"q": "44 + 23은 얼마일까요?", "answer": 0, "choices": ["67", "21", "77", "66"], "explain": "일의 자리 4 + 3 = 7, 십의 자리 4 + 2 = 6 → 67이에요."}, {"q": "65 − 21은 얼마일까요?", "answer": 2, "choices": ["86", "34", "44", "43"], "explain": "일의 자리 5 − 1 = 4, 십의 자리 6 − 2 = 4 → 44예요."}, {"q": "29 + 16에서 일의 자리 9 + 6 = 15예요. 다음에 할 일은?", "answer": 1, "choices": ["15를 그대로 써요", "5를 쓰고 1을 십의 자리로 올려요", "9를 빼요", "그만 계산해요"], "explain": "10을 십의 자리로 올리고 일의 자리에 5를 써요. 답은 45예요."}, {"q": "🍓 딸기 50개 중 24개를 먹었어요. 남은 딸기는?", "answer": 3, "choices": ["74", "36", "34", "26"], "explain": "0에서 4를 뺄 수 없어 10을 빌려 와요. 10 − 4 = 6, 4 − 2 = 2 → 26이에요."}], "intro": "🚌 버스에 32명이 타고 있는데 15명이 더 탔어요. 모두 몇 명일까요? 두 자리 수도 차근차근 더하고 뺄 수 있어요.", "summary": ["같은 자리끼리 계산해요.", "일의 자리 합이 10과 같거나 10보다 크면 십의 자리로 받아올려요.", "일의 자리에서 뺄 수 없으면 십의 자리에서 10을 받아내려요."], "keywords": [{"word": "십의 자리", "meaning": "두 자리 수에서 10개씩 묶음 수를 나타내는 앞자리"}, {"word": "일의 자리", "meaning": "두 자리 수에서 낱개 수를 나타내는 뒷자리"}, {"word": "받아올림", "meaning": "일의 자리 합이 10과 같거나 10보다 클 때 10을 십의 자리로 올리는 것"}, {"word": "받아내림", "meaning": "일의 자리에서 뺄 수 없을 때 십의 자리에서 10을 빌려 오는 것"}], "sections": [{"paras": ["두 자리 수는 십의 자리와 일의 자리가 있어요.", "일의 자리는 일의 자리끼리, 십의 자리는 십의 자리끼리 계산해요."], "figure": "10개씩 묶은 빨대 묶음과 낱개 빨대를 두 줄로 나란히 놓은 모습", "example": "32 + 15 → 일의 자리 2 + 5 = 7, 십의 자리 3 + 1 = 4 → 47", "heading": "같은 자리끼리 계산해요"}, {"paras": ["일의 자리 합이 10과 같거나 10보다 크면 10을 십의 자리로 올려요.", "올린 1을 십의 자리 계산에 꼭 더해요."], "figure": "공책에 세로셈을 쓰고 십의 자리 위에 작은 1을 적은 모습", "example": "38 + 25 ① 일의 자리 8 + 5 = 13 → 3을 쓰고 1을 올려요 ② 십의 자리 1 + 3 + 2 = 6 ③ 답 63", "heading": "이렇게 풀어요: 받아올림이 있는 덧셈"}, {"paras": ["일의 자리에서 뺄 수 없으면 십의 자리에서 10을 빌려 와요.", "빌려 준 십의 자리는 1 작아져요."], "figure": "빨대 묶음 하나를 풀어 낱개 10개로 만드는 아이 손", "example": "52 − 27 ① 2에서 7을 뺄 수 없어요 ② 십의 자리에서 10을 빌려 12 − 7 = 5 ③ 십의 자리 4 − 2 = 2 ④ 답 25", "heading": "이렇게 풀어요: 받아내림이 있는 뺄셈"}, {"paras": ["덧셈식으로 뺄셈식을 만들 수 있어요.", "뺄셈을 하고 나서 덧셈으로 맞는지 확인해요."], "figure": "수 카드 25, 27, 52가 세모 모양으로 놓인 모습", "example": "25 + 27 = 52 ↔ 52 − 27 = 25, 52 − 25 = 27", "heading": "덧셈과 뺄셈은 짝꿍이에요"}], "parent_tip": "가장 흔한 실수는 받아올린 1을 더하지 않거나, 뺄셈에서 큰 수에서 작은 수를 거꾸로 빼는 것(52 − 27에서 7 − 2)입니다. 세로셈을 쓸 때 자리를 맞춰 쓰게 하고, 뺄셈 뒤에는 덧셈으로 검산하는 습관을 들여 주세요.", "expressions": []}$j$::jsonb where slug='m1-06';
update public.lessons set title=$j$큰 수의 곱셈은 어떻게 할까?$j$, content=$j${"quiz": [{"q": "213 × 3은 얼마일까요?", "answer": 0, "choices": ["639", "636", "609", "693"], "explain": "3 × 3 = 9, 1 × 3 = 3, 2 × 3 = 6이라서 639예요."}, {"q": "47 × 6은 얼마일까요?", "answer": 2, "choices": ["242", "272", "282", "286"], "explain": "7 × 6 = 42에서 4를 올리고, 4 × 6 = 24에 4를 더해 28이라 282예요."}, {"q": "25 × 14는 얼마일까요?", "answer": 1, "choices": ["300", "350", "325", "375"], "explain": "25 × 4 = 100, 25 × 10 = 250, 둘을 더하면 350이에요."}, {"q": "귤이 한 상자에 32개씩 15상자 있어요. 귤은 모두 몇 개일까요?", "answer": 2, "choices": ["450개", "470개", "480개", "490개"], "explain": "32 × 15 = 32 × 5 + 32 × 10 = 160 + 320 = 480이에요."}, {"q": "40 × 30은 얼마일까요?", "answer": 1, "choices": ["120", "1200", "12000", "700"], "explain": "4 × 3 = 12에 0을 두 개 붙이면 1200이에요."}], "intro": "한 상자에 달걀이 30개씩 들어 있는데 40상자가 있다면 달걀은 모두 몇 개일까요? 하나하나 세지 않아도 곱셈으로 빠르게 알 수 있어요.", "summary": ["곱셈은 같은 수를 여러 번 더한 것을 간단히 나타내요.", "일의 자리부터 곱하고, 10과 같거나 10보다 크면 윗자리로 올림해요.", "두 자리 수를 곱할 때는 일의 자리와 십의 자리로 나누어 곱한 뒤 더해요."], "keywords": [{"word": "곱셈", "meaning": "같은 수를 여러 번 더한 것을 간단히 나타내는 계산"}, {"word": "곱", "meaning": "곱셈을 해서 나온 값"}, {"word": "올림", "meaning": "한 자리의 곱이 10과 같거나 10보다 클 때 윗자리로 올려 주는 것"}, {"word": "어림", "meaning": "대강 짐작해서 셈하는 것"}], "sections": [{"paras": ["4 + 4 + 4처럼 같은 수를 여러 번 더할 때 곱셈식 4 × 3으로 간단하게 쓸 수 있어요.", "곱셈은 자리를 바꿔도 결과가 같아요. 4 × 3과 3 × 4는 둘 다 12예요."], "figure": "사과 4개씩 담긴 접시 3개가 나란히 놓인 그림", "example": "4 + 4 + 4 = 4 × 3 = 12", "heading": "곱셈은 같은 수를 여러 번 더한 것"}, {"paras": ["일의 자리부터 차례로 곱하고, 곱이 10과 같거나 10보다 크면 윗자리로 올려 줘요. 이것을 올림이라고 해요.", "156 × 4는 일의 자리 6 × 4 = 24에서 4를 쓰고 2를 올려요. 십의 자리 5 × 4 = 20에 올린 2를 더해 22, 2를 쓰고 2를 올려요. 백의 자리 1 × 4 = 4에 2를 더해 6이에요."], "figure": "156 × 4 세로셈에서 올림한 숫자를 작게 위에 적은 그림", "example": "213 × 3 = 639, 156 × 4 = 624", "heading": "(세 자리 수) × (한 자리 수)"}, {"paras": ["24 × 13을 풀어 볼까요? ① 24 × 3 = 72를 먼저 구해요. ② 24 × 10 = 240을 구해요(13의 1은 십의 자리라서 10이에요).", "③ 두 곱을 더하면 72 + 240 = 312예요. 곱하는 수를 일의 자리와 십의 자리로 나누어 곱한 뒤 더하는 거예요."], "figure": "가로 24칸, 세로 13칸 모눈을 3줄과 10줄로 나누어 색을 다르게 칠한 그림", "example": "24 × 13 = 24 × 3 + 24 × 10 = 72 + 240 = 312", "heading": "이렇게 풀어요: (두 자리 수) × (두 자리 수)"}, {"paras": ["30 × 40은 3 × 4 = 12를 구한 뒤, 두 수의 끝에 있는 0의 개수(2개)만큼 0을 붙이면 1200이에요.", "답이 맞는지 어림해 보는 습관도 좋아요. 198 × 3은 약 200 × 3 = 600쯤 되겠다고 미리 생각해 볼 수 있어요."], "figure": "달걀 30개 상자 40개가 쌓여 있는 창고 그림", "example": "30 × 40 = 1200 (3 × 4 = 12에 0 두 개)", "heading": "0이 있는 곱셈과 어림"}], "parent_tip": "(두 자리)×(두 자리)에서 십의 자리를 곱할 때 0을 빠뜨리고 자리를 잘못 맞추는 실수가 가장 많습니다. \"13의 1은 진짜로 얼마야?\"라고 물어 10이라는 것을 스스로 말하게 해 주세요. 장보기 영수증으로 \"이게 3개면 얼마일까?\"를 어림해 보는 것도 좋습니다.", "expressions": []}$j$::jsonb where slug='m3-02';
update public.lessons set title=$j$받아올림과 받아내림, 왜 필요할까?$j$, content=$j${"quiz": [{"q": "368 + 457은 얼마일까요?", "answer": 2, "choices": ["715", "815", "825", "725"], "explain": "8 + 7 = 15, 6 + 5 + 1 = 12, 3 + 4 + 1 = 8이라서 825예요."}, {"q": "702 − 358은 얼마일까요?", "answer": 0, "choices": ["344", "354", "456", "444"], "explain": "백의 자리에서 받아내려 계산하면 344예요. 344 + 358 = 702로 검산할 수 있어요."}, {"q": "512 − 289 = 223을 검산하는 식으로 알맞은 것은?", "answer": 0, "choices": ["223 + 289 = 512", "512 + 289 = 801", "289 − 223 = 66", "512 − 223 = 279"], "explain": "뺄셈의 답과 빼는 수를 더하면 처음 수가 나와요."}, {"q": "어제 줄넘기를 245번, 오늘 186번 했어요. 모두 몇 번 했을까요?", "answer": 1, "choices": ["421번", "431번", "331번", "441번"], "explain": "245 + 186 = 431번이에요."}, {"q": "색종이 600장 중 247장을 썼어요. 남은 색종이는 몇 장일까요?", "answer": 0, "choices": ["353장", "363장", "453장", "347장"], "explain": "600 − 247 = 353장이에요."}], "intro": "도서관에 동화책 456권과 과학책 278권이 있어요. 모두 몇 권일까요? 세 자리 수끼리 더하고 빼는 방법을 알아봐요.", "summary": ["자리를 맞추어 쓰고 일의 자리부터 계산해요.", "덧셈에서 10 이상이면 받아올림, 뺄셈에서 뺄 수 없으면 받아내림을 해요.", "어림으로 답을 짐작하고, 뺄셈은 덧셈으로 검산해요."], "keywords": [{"word": "받아올림", "meaning": "같은 자리의 합이 10 이상일 때 윗자리로 1을 올리는 것"}, {"word": "받아내림", "meaning": "뺄 수 없을 때 윗자리에서 10을 빌려 오는 것"}, {"word": "어림", "meaning": "대강 짐작해서 셈하는 것"}, {"word": "검산", "meaning": "계산이 맞는지 다시 확인하는 것"}], "sections": [{"paras": ["세 자리 수를 계산할 때는 백, 십, 일의 자리를 세로로 맞추어 쓰고 일의 자리부터 계산해요.", "같은 자리끼리 계산해야 하는 이유는 같은 숫자라도 자리에 따라 나타내는 값이 다르기 때문이에요. 324에서 3은 300, 2는 20, 4는 4예요."], "figure": "백·십·일 자리 칸에 숫자를 맞추어 쓴 세로셈 그림", "example": "324 + 152 = 476 (일 4+2=6, 십 2+5=7, 백 3+1=4)", "heading": "자리를 맞추어 일의 자리부터"}, {"paras": ["456 + 278을 풀어 볼까요? ① 일의 자리 6 + 8 = 14, 4를 쓰고 10은 십의 자리로 1을 올려요.", "② 십의 자리 5 + 7 + 1 = 13, 3을 쓰고 백의 자리로 1을 올려요. ③ 백의 자리 4 + 2 + 1 = 7이에요. 답은 734예요."], "figure": "456 + 278 세로셈에서 받아올린 1을 작게 위에 적은 그림", "example": "456 + 278 = 734", "heading": "이렇게 풀어요: 받아올림이 있는 덧셈"}, {"paras": ["503 − 267을 풀어 볼까요? 일의 자리 3에서 7을 뺄 수 없어요. 십의 자리가 0이라서 백의 자리에서 먼저 받아내려요.", "백의 자리 5는 4가 되고 십의 자리는 10이 돼요. 다시 십의 자리에서 10을 일의 자리로 받아내리면 십은 9, 일은 13이에요. 13 − 7 = 6, 9 − 6 = 3, 4 − 2 = 2라서 236이에요."], "figure": "503 − 267 세로셈에서 받아내린 숫자를 고쳐 쓴 그림", "example": "503 − 267 = 236", "heading": "이렇게 풀어요: 받아내림이 있는 뺄셈"}, {"paras": ["계산하기 전에 어림하면 답이 맞는지 짐작할 수 있어요. 312 + 289는 약 300 + 300 = 600쯤이고, 실제로는 601이에요.", "뺄셈은 덧셈으로 검산할 수 있어요. 503 − 267 = 236이 맞는지 236 + 267을 계산하면 503이 나와요."], "figure": "뺄셈식과 검산 덧셈식을 화살표로 이은 그림", "example": "검산: 236 + 267 = 503 → 503 − 267 = 236이 맞아요", "heading": "어림하고 검산해요"}], "parent_tip": "703 − 268처럼 십의 자리가 0인 뺄셈에서 받아내림을 두 번 해야 하는 경우를 가장 어려워합니다. 동전(100원, 10원, 1원)으로 실제로 바꿔 주며 계산해 보면 이해가 빠릅니다. 답을 낸 뒤 \"덧셈으로 확인해 볼까?\"라고 검산 습관을 길러 주세요.", "expressions": []}$j$::jsonb where slug='m3-04';
update public.lessons set title=$j$mm, km, 초는 언제 쓸까?$j$, content=$j${"quiz": [{"q": "7cm 4mm는 몇 mm일까요?", "answer": 0, "choices": ["74mm", "704mm", "11mm", "47mm"], "explain": "7cm = 70mm이므로 70 + 4 = 74mm예요."}, {"q": "3050m는 몇 km 몇 m일까요?", "answer": 1, "choices": ["3km 5m", "3km 50m", "3km 500m", "30km 50m"], "explain": "3000m = 3km이고 50m가 남아 3km 50m예요."}, {"q": "2분 15초는 몇 초일까요?", "answer": 2, "choices": ["35초", "125초", "135초", "215초"], "explain": "2분 = 120초이므로 120 + 15 = 135초예요."}, {"q": "2시 50분에서 25분이 지나면 몇 시 몇 분일까요?", "answer": 2, "choices": ["2시 75분", "3시 5분", "3시 15분", "3시 25분"], "explain": "50 + 25 = 75분 = 1시간 15분이라서 3시 15분이에요."}, {"q": "5시 10분에서 2시간 30분 전은 몇 시 몇 분일까요?", "answer": 0, "choices": ["2시 40분", "3시 20분", "2시 20분", "3시 40분"], "explain": "5시 10분을 4시 70분으로 바꾸면 70 − 30 = 40분, 4 − 2 = 2시라서 2시 40분이에요."}], "intro": "개미의 몸길이와 학교까지의 거리를 같은 단위로 재면 불편하겠죠? 길이와 시간에는 상황에 맞는 여러 단위가 있어요.", "summary": ["1cm = 10mm, 1km = 1000m예요.", "1분 = 60초, 1시간 = 60분이에요.", "시간 계산에서는 60분이 되면 1시간으로 올리고, 모자라면 1시간을 60분으로 바꿔요."], "keywords": [{"word": "mm(밀리미터)", "meaning": "1cm를 10칸으로 똑같이 나눈 한 칸의 길이"}, {"word": "km(킬로미터)", "meaning": "1000m를 나타내는 길이 단위"}, {"word": "초", "meaning": "1분을 60으로 나눈 짧은 시간"}, {"word": "시간", "meaning": "어떤 시각부터 어떤 시각까지의 동안"}], "sections": [{"paras": ["자의 1cm 사이에는 작은 눈금 10칸이 있어요. 작은 눈금 한 칸의 길이를 1mm(1밀리미터)라고 해요.", "그래서 1cm = 10mm예요. 3cm보다 5mm 더 긴 길이는 3cm 5mm라고 쓰고, 35mm와 같아요."], "figure": "자를 크게 확대해 1cm 안의 작은 눈금 10칸을 보여 주는 그림", "example": "3cm 5mm = 30mm + 5mm = 35mm", "heading": "1cm보다 작은 단위 mm"}, {"paras": ["먼 거리를 나타낼 때는 km(킬로미터)를 써요. 1000m = 1km예요.", "2km보다 300m 더 먼 거리는 2km 300m이고, 2300m와 같아요."], "figure": "집에서 학교, 도서관까지의 거리를 km와 m로 표시한 지도 그림", "example": "2km 300m = 2000m + 300m = 2300m", "heading": "1000m보다 긴 단위 km"}, {"paras": ["초바늘이 작은 눈금 한 칸을 가는 시간이 1초예요. 초바늘이 시계를 한 바퀴 돌면 60초이고, 이것이 1분이에요.", "그래서 1분 = 60초, 1시간 = 60분이에요. 2분 10초는 120초 + 10초 = 130초예요."], "figure": "초바늘이 있는 시계에서 초바늘이 한 바퀴 도는 모습을 화살표로 나타낸 그림", "example": "1분 = 60초, 2분 10초 = 130초", "heading": "1분보다 짧은 단위 초"}, {"paras": ["1시간 40분 + 35분: ① 분끼리 더하면 40 + 35 = 75분. ② 60분은 1시간이므로 75분 = 1시간 15분. ③ 1시간 + 1시간 15분 = 2시간 15분이에요.", "4시 20분 − 1시 45분: 20분에서 45분을 뺄 수 없으니 1시간을 60분으로 바꿔 3시 80분으로 생각해요. 80 − 45 = 35분, 3 − 1 = 2시간이라서 2시간 35분이에요."], "figure": "시간 받아올림과 받아내림을 세로셈으로 보여 주는 그림", "example": "1시간 40분 + 35분 = 2시간 15분, 4시 20분 − 1시 45분 = 2시간 35분", "heading": "이렇게 풀어요: 시간의 덧셈과 뺄셈"}], "parent_tip": "시간 계산에서 아이들은 100을 기준으로 받아내림하는 실수(예: 80분이 아니라 120분으로 계산)를 자주 합니다. 아날로그 시계를 함께 보며 \"60분이 되면 바늘이 어디로 가지?\"라고 확인해 주세요. 외출 시 \"도착까지 몇 분 남았을까?\"를 계산해 보게 하면 좋습니다.", "expressions": []}$j$::jsonb where slug='m3-06';
update public.lessons set title=$j$선과 각으로 어떤 도형을 만들까?$j$, content=$j${"quiz": [{"q": "양쪽으로 끝없이 늘인 곧은 선의 이름은?", "answer": 2, "choices": ["선분", "반직선", "직선", "곡선"], "explain": "양쪽으로 끝없이 늘어나면 직선이에요."}, {"q": "직사각형에는 직각이 몇 개 있을까요?", "answer": 3, "choices": ["1개", "2개", "3개", "4개"], "explain": "직사각형은 네 각이 모두 직각이에요."}, {"q": "정사각형에 대한 설명으로 알맞은 것은?", "answer": 1, "choices": ["직각이 1개 있다", "네 각이 직각이고 네 변의 길이가 같다", "세 변으로 이루어져 있다", "곧은 선이 하나도 없다"], "explain": "정사각형은 네 각이 모두 직각이고 네 변의 길이가 모두 같아요."}, {"q": "시계가 3시 정각을 가리킬 때 긴바늘과 짧은바늘이 이루는 각은?", "answer": 0, "choices": ["직각", "직각보다 작은 각", "직각보다 큰 각", "각이 생기지 않는다"], "explain": "3시 정각에는 두 바늘이 직각을 이뤄요."}, {"q": "한 점에서 시작해 한쪽으로만 끝없이 늘인 곧은 선은?", "answer": 1, "choices": ["직선", "반직선", "선분", "꼭짓점"], "explain": "한쪽으로만 끝없이 늘어나면 반직선이에요."}], "intro": "공책, 창문, 책상 모서리를 잘 보면 반듯한 선과 꼭 맞는 각이 숨어 있어요. 평면도형의 이름과 특징을 알아봐요.", "summary": ["선분은 두 점을 이은 선, 반직선은 한쪽으로, 직선은 양쪽으로 끝없이 늘인 선이에요.", "종이를 반듯하게 두 번 접은 각이 직각이에요.", "직각삼각형은 직각 1개, 직사각형은 직각 4개, 정사각형은 직각 4개에 네 변이 모두 같아요."], "keywords": [{"word": "선분", "meaning": "두 점을 곧게 이은 선"}, {"word": "반직선", "meaning": "한 점에서 한쪽으로 끝없이 늘인 곧은 선"}, {"word": "직선", "meaning": "양쪽으로 끝없이 늘인 곧은 선"}, {"word": "각", "meaning": "한 점에서 그은 두 반직선으로 이루어진 도형"}, {"word": "직각", "meaning": "종이를 반듯하게 두 번 접었을 때 생기는 각"}, {"word": "정사각형", "meaning": "네 각이 직각이고 네 변의 길이가 같은 사각형"}], "sections": [{"paras": ["두 점을 곧게 이은 선을 선분이라고 해요. 선분 ㄱㄴ처럼 두 점의 이름으로 불러요.", "한 점에서 시작해 한쪽으로 끝없이 늘인 곧은 선은 반직선, 양쪽으로 끝없이 늘인 곧은 선은 직선이에요."], "figure": "선분, 반직선, 직선을 나란히 그리고 끝없이 늘어나는 쪽에 화살표를 표시한 그림", "example": "점 3개를 두 개씩 모두 이으면 선분이 3개 생겨요", "heading": "선분, 반직선, 직선"}, {"paras": ["한 점에서 그은 두 반직선으로 이루어진 도형을 각이라고 해요. 각을 이루는 점을 꼭짓점, 두 반직선을 변이라고 해요.", "종이를 반듯하게 두 번 접었을 때 생기는 각을 직각이라고 해요. 시계가 3시를 가리킬 때 두 바늘이 이루는 각도 직각이에요."], "figure": "종이를 두 번 접어 만든 직각과 3시를 가리키는 시계 그림", "example": "3시 정각의 시곗바늘 → 직각", "heading": "각과 직각"}, {"paras": ["① 삼각자의 직각인 부분이나 접어 만든 직각 종이를 준비해요. ② 각의 꼭짓점에 직각 부분의 꼭짓점을 맞춰요.", "③ 한 변을 겹친 뒤 다른 한 변도 꼭 겹치면 직각이에요. 직각은 꼭짓점에 작은 꺾쇠(∟) 표시를 해서 나타내요."], "figure": "삼각자의 직각을 도형의 각에 대 보는 손 그림", "example": "직사각형의 네 각에 삼각자를 대 보면 모두 꼭 맞아요 → 직각 4개", "heading": "이렇게 찾아요: 직각 확인하기"}, {"paras": ["한 각이 직각인 삼각형은 직각삼각형이에요. 네 각이 모두 직각인 사각형은 직사각형이에요.", "네 각이 모두 직각이고 네 변의 길이도 모두 같은 사각형은 정사각형이에요. 그래서 정사각형은 직사각형이라고도 할 수 있지만, 모든 직사각형이 정사각형은 아니에요."], "figure": "직각삼각형, 직사각형, 정사각형을 나란히 그리고 직각 표시를 한 그림", "example": "직각삼각형: 직각 1개, 직사각형: 직각 4개, 정사각형: 직각 4개 + 네 변의 길이가 같음", "heading": "직각삼각형, 직사각형, 정사각형"}], "parent_tip": "반직선 ㄱㄴ과 반직선 ㄴㄱ이 서로 다르다는 것(시작점이 다름)을 많이 헷갈립니다. 집 안에서 직각을 찾는 '직각 사냥'을 하며 \"정사각형은 직사각형일까? 반대도 맞을까?\"라고 물어봐 주세요.", "expressions": []}$j$::jsonb where slug='m3-08';
update public.lessons set title=$j$상자 모양에는 어떤 비밀이 있을까?$j$, content=$j${"quiz": [{"q": "직육면체의 꼭짓점은 몇 개일까요?", "answer": 1, "choices": ["6개", "8개", "12개", "4개"], "explain": "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요."}, {"q": "직육면체의 겨냥도에서 점선으로 그리는 모서리는 몇 개일까요?", "answer": 2, "choices": ["1개", "2개", "3개", "9개"], "explain": "보이지 않는 모서리 3개를 점선으로 그려요."}, {"q": "직육면체에서 한 면과 수직인 면은 몇 개일까요?", "answer": 2, "choices": ["1개", "2개", "4개", "5개"], "explain": "마주 보는 면 1개를 뺀 나머지 4개의 면이 수직이에요."}, {"q": "한 모서리가 7cm인 정육면체의 모든 모서리 길이의 합은?", "answer": 2, "choices": ["42cm", "56cm", "84cm", "49cm"], "explain": "정육면체 모서리 12개의 길이가 모두 같아서 7 × 12 = 84cm예요."}, {"q": "직육면체에서 서로 평행한 면은 모두 몇 쌍일까요?", "answer": 1, "choices": ["2쌍", "3쌍", "4쌍", "6쌍"], "explain": "마주 보는 면끼리 평행하고 3쌍이 있어요."}], "intro": "과자 상자, 주사위, 벽돌은 모두 비슷한 모양이에요. 면과 모서리, 꼭짓점을 세어 보며 이 입체도형의 특징을 알아봐요.", "summary": ["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있어요.", "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.", "겨냥도는 보이지 않는 모서리 3개를 점선으로, 전개도는 펼친 모양으로 나타내요."], "keywords": [{"word": "직육면체", "meaning": "직사각형 6개로 둘러싸인 도형"}, {"word": "정육면체", "meaning": "정사각형 6개로 둘러싸인 도형"}, {"word": "모서리", "meaning": "면과 면이 만나는 선분"}, {"word": "꼭짓점", "meaning": "모서리와 모서리가 만나는 점"}, {"word": "겨냥도", "meaning": "입체도형의 모양을 알 수 있게 그린 그림"}, {"word": "전개도", "meaning": "입체도형의 모서리를 잘라 평면에 펼친 그림"}], "sections": [{"paras": ["직사각형 6개로 둘러싸인 도형을 직육면체라고 해요. 정사각형 6개로 둘러싸인 도형은 정육면체예요.", "정사각형은 직사각형이기도 하니까 정육면체도 직육면체라고 할 수 있어요. 하지만 모든 직육면체가 정육면체는 아니에요."], "figure": "과자 상자 모양 직육면체와 주사위 모양 정육면체를 나란히 놓은 그림", "example": "과자 상자 → 직육면체, 주사위 → 정육면체", "heading": "직육면체와 정육면체"}, {"paras": ["선분으로 둘러싸인 부분을 면, 면과 면이 만나는 선분을 모서리, 모서리와 모서리가 만나는 점을 꼭짓점이라고 해요.", "직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요. 마주 보는 두 면은 서로 평행하고 이런 면이 3쌍 있어요. 한 면과 만나는 4개의 면은 그 면과 수직이에요."], "figure": "직육면체에서 면, 모서리, 꼭짓점에 이름표를 붙인 그림", "example": "직육면체: 면 6개, 모서리 12개, 꼭짓점 8개, 평행한 면 3쌍", "heading": "면, 모서리, 꼭짓점"}, {"paras": ["직육면체 모양을 잘 알 수 있게 그린 그림을 겨냥도라고 해요. 보이는 모서리 9개는 실선으로, 보이지 않는 모서리 3개는 점선으로 그려요.", "직육면체의 모서리를 잘라 평면 위에 펼친 그림은 전개도예요. 전개도를 접었을 때 겹치는 면이 없고 마주 보는 면 3쌍이 모양과 크기가 같아야 해요."], "figure": "직육면체 겨냥도(실선과 점선)와 펼친 전개도를 함께 그린 그림", "example": "겨냥도: 실선 9개 + 점선 3개 = 모서리 12개", "heading": "겨냥도와 전개도"}, {"paras": ["가로 4cm, 세로 3cm, 높이 2cm인 직육면체의 모든 모서리 길이의 합을 구해 볼까요? ① 길이가 같은 모서리가 4개씩 3묶음 있어요.", "② 가로, 세로, 높이를 하나씩 더하면 4 + 3 + 2 = 9cm. ③ 길이가 같은 모서리가 4개씩 있으니 9 × 4 = 36cm예요. 정육면체는 모서리 12개의 길이가 모두 같아서 한 모서리가 5cm면 5 × 12 = 60cm예요."], "figure": "같은 길이의 모서리 4개씩을 같은 색으로 칠한 직육면체 그림", "example": "(4 + 3 + 2) × 4 = 36cm, 정육면체 한 모서리 5cm → 5 × 12 = 60cm", "heading": "이렇게 풀어요: 모든 모서리 길이의 합"}], "parent_tip": "겨냥도에서 보이지 않는 모서리를 빠뜨리거나 전개도에서 겹치는 면을 찾지 못하는 경우가 많습니다. 빈 과자 상자를 모서리를 따라 직접 잘라 펼쳐 보면 효과적입니다. \"이 면과 마주 보는 면은 어디일까?\"라고 물어봐 주세요.", "expressions": []}$j$::jsonb where slug='m5-01';
update public.lessons set title=$j$상자 안의 공간은 얼마나 클까?$j$, content=$j${"quiz": [{"q": "가로 8cm, 세로 5cm, 높이 2cm인 직육면체의 부피는?", "answer": 2, "choices": ["15cm³", "40cm³", "80cm³", "160cm³"], "explain": "8 × 5 × 2 = 80cm³예요."}, {"q": "한 모서리가 4cm인 정육면체의 부피는?", "answer": 3, "choices": ["12cm³", "16cm³", "48cm³", "64cm³"], "explain": "4 × 4 × 4 = 64cm³예요."}, {"q": "3m³는 몇 cm³일까요?", "answer": 3, "choices": ["300cm³", "3000cm³", "300000cm³", "3000000cm³"], "explain": "1m³ = 1000000cm³이므로 3m³ = 3000000cm³예요."}, {"q": "부피가 120cm³인 직육면체의 가로가 6cm, 세로가 5cm예요. 높이는 몇 cm일까요?", "answer": 1, "choices": ["3cm", "4cm", "5cm", "6cm"], "explain": "6 × 5 = 30이고 30 × 높이 = 120이므로 높이는 4cm예요."}, {"q": "1cm³ 쌓기나무를 가로 3개, 세로 3개씩 4층으로 쌓았어요. 부피는?", "answer": 2, "choices": ["10cm³", "24cm³", "36cm³", "48cm³"], "explain": "한 층에 3 × 3 = 9개, 4층이면 9 × 4 = 36개라 36cm³예요."}], "intro": "두 상자 중 어느 쪽에 물건이 더 많이 들어갈까요? 겉으로 보기에 비슷해도 공간의 크기는 다를 수 있어요. 공간의 크기를 수로 나타내는 방법을 알아봐요.", "summary": ["부피는 물건이 공간에서 차지하는 크기예요.", "직육면체의 부피 = 가로 × 세로 × 높이, 정육면체의 부피 = 한 모서리 × 한 모서리 × 한 모서리예요.", "1m³ = 1000000cm³예요."], "keywords": [{"word": "부피", "meaning": "물건이 공간에서 차지하는 크기"}, {"word": "cm³(세제곱센티미터)", "meaning": "한 모서리가 1cm인 정육면체의 부피"}, {"word": "m³(세제곱미터)", "meaning": "한 모서리가 1m인 정육면체의 부피"}, {"word": "1m³ = 1000000cm³", "meaning": "1m = 100cm이므로 100 × 100 × 100 = 1000000(배)"}], "sections": [{"paras": ["어떤 물건이 공간에서 차지하는 크기를 부피라고 해요. 부피를 비교하려면 기준이 되는 단위가 필요해요.", "한 모서리가 1cm인 정육면체의 부피를 1cm³라 쓰고 1세제곱센티미터라고 읽어요. 이 쌓기나무가 몇 개 들어가는지 세면 부피를 알 수 있어요."], "figure": "한 모서리가 1cm인 쌓기나무와 그것으로 쌓은 직육면체 그림", "example": "1cm³ 쌓기나무 12개로 만든 직육면체 → 부피 12cm³", "heading": "부피와 1cm³"}, {"paras": ["가로 5cm, 세로 4cm, 높이 3cm인 직육면체를 생각해 봐요. ① 바닥 한 층에는 1cm³ 쌓기나무가 5 × 4 = 20개 깔려요.", "② 이런 층이 높이만큼 3층 있으니 20 × 3 = 60개예요. 그래서 직육면체의 부피 = 가로 × 세로 × 높이 = 60cm³예요."], "figure": "쌓기나무 20개가 한 층을 이루고 3층으로 쌓인 직육면체 그림", "example": "5 × 4 × 3 = 60cm³", "heading": "이렇게 풀어요: 직육면체의 부피"}, {"paras": ["정육면체는 가로, 세로, 높이가 모두 같아요. 그래서 정육면체의 부피 = 한 모서리 × 한 모서리 × 한 모서리예요.", "한 모서리가 6cm인 정육면체의 부피는 6 × 6 × 6 = 216cm³예요."], "figure": "한 모서리가 6cm라고 표시된 정육면체 그림", "example": "6 × 6 × 6 = 216cm³", "heading": "정육면체의 부피"}, {"paras": ["방이나 컨테이너처럼 큰 부피는 한 모서리가 1m인 정육면체의 부피 1m³(1세제곱미터)를 써요.", "1m = 100cm이므로 1m³ = 100 × 100 × 100 = 1000000cm³예요. 가로 2m, 세로 1m, 높이 3m인 상자의 부피는 6m³이고, 6000000cm³와 같아요."], "figure": "1m³ 정육면체 안에 작은 1cm³ 쌓기나무가 가득한 모습을 상상한 그림", "example": "1m³ = 1000000cm³, 2 × 1 × 3 = 6m³", "heading": "큰 부피의 단위 m³"}], "parent_tip": "1m³ = 100cm³로 잘못 아는 경우가 아주 많습니다. 가로·세로·높이가 모두 100배가 되므로 100 × 100 × 100이라는 점을 짚어 주세요. 집에 있는 상자의 길이를 재서 부피를 구하고 \"부피가 같은데 모양이 다른 상자도 있을까?\"라고 물어보면 좋습니다.", "expressions": []}$j$::jsonb where slug='m5-02';
update public.lessons set title=$j$섞인 물질을 어떻게 다시 나눌까?$j$, content=$j${"quiz": [{"q": "다음 중 혼합물이 __아닌__ 것은?", "answer": 3, "choices": ["팥빙수", "잡곡", "바닷물", "순수한 물"], "explain": "순수한 물은 한 가지 물질이에요. 나머지는 여러 물질이 섞인 혼합물이에요."}, {"q": "콩과 좁쌀이 섞여 있을 때 가장 쉽게 나누는 방법은?", "answer": 0, "choices": ["체로 거른다", "물에 녹인다", "불로 태운다", "자석을 댄다"], "explain": "콩과 좁쌀은 알갱이 크기가 달라서 체로 나눌 수 있어요."}, {"q": "모래와 철 가루를 나누는 데 알맞은 도구는?", "answer": 2, "choices": ["거름종이", "체", "자석", "돋보기"], "explain": "철 가루는 자석에 붙고 모래는 붙지 않아요."}, {"q": "소금과 모래 혼합물을 물에 녹여 거르면 거름종이 위에 남는 것은?", "answer": 1, "choices": ["소금", "모래", "소금물", "아무것도 안 남는다"], "explain": "모래는 물에 녹지 않아 거름종이 위에 남고, 소금은 물에 녹아 빠져나가요."}, {"q": "소금물에서 소금을 얻으려면 어떻게 해야 할까요?", "answer": 3, "choices": ["체로 거른다", "자석을 댄다", "얼린다", "물을 증발시킨다"], "explain": "물이 증발해 날아가면 소금만 남아요."}], "intro": "콩, 팥, 좁쌀이 한 그릇에 뒤섞였어요. 하나하나 손으로 골라내려면 너무 오래 걸리겠죠? 더 쉬운 방법이 있을까요?", "summary": ["혼합물은 여러 물질이 섞인 것이고, 섞여도 각 물질의 성질은 그대로예요.", "크기는 체, 철은 자석, 녹는 성질은 거름으로 나눠요.", "소금물의 물을 증발시키면 소금을 얻을 수 있어요."], "keywords": [{"word": "혼합물", "meaning": "두 가지 이상의 물질이 섞여 있는 것"}, {"word": "분리", "meaning": "섞여 있는 물질을 나누는 것"}, {"word": "체", "meaning": "알갱이 크기 차이로 물질을 나누는 도구"}, {"word": "거름", "meaning": "거름종이로 녹지 않은 물질을 걸러 내는 방법"}, {"word": "증발", "meaning": "물이 표면에서 수증기가 되어 날아가는 것"}], "sections": [{"paras": ["두 가지 이상의 물질이 섞여 있는 것을 '혼합물'이라고 해요. 섞여 있어도 각 물질의 성질은 그대로 남아 있어요.", "김밥, 팥빙수, 잡곡, 바닷물(물+소금)도 모두 혼합물이에요. 그래서 각 물질의 성질 차이를 이용하면 다시 나눌(분리할) 수 있어요."], "figure": "콩, 팥, 좁쌀이 섞인 그릇 그림", "example": "콩·팥·좁쌀을 섞어도 콩은 콩대로, 팥은 팥대로 크기와 색이 그대로예요.", "heading": "혼합물이란?"}, {"paras": ["알갱이의 크기가 다른 혼합물은 '체'로 나눌 수 있어요. 체의 눈보다 작은 알갱이는 빠져나가고 큰 알갱이는 체에 남아요.", "눈의 크기가 다른 체를 차례로 쓰면 콩, 팥, 좁쌀을 모두 나눌 수 있어요."], "figure": "눈 크기가 다른 체 두 개로 콩, 팥, 좁쌀을 차례로 분리하는 과정 그림", "example": "모래사장에서 체로 모래를 거르면 조개껍데기만 남아요.", "heading": "알갱이 크기로 나누기 – 체"}, {"paras": ["철로 된 물체가 섞여 있으면 자석으로 쉽게 골라낼 수 있어요. 자석에 붙는 성질을 이용한 것이지요.", "재활용 공장에서는 큰 자석으로 철 캔과 알루미늄 캔을 나눠요."], "figure": "모래와 철 가루 혼합물에 자석을 대어 철 가루만 끌려 나오는 모습", "example": "모래 속에 섞인 철 가루는 자석을 대면 자석에 달라붙어 나와요.", "heading": "자석으로 나누기"}, {"paras": ["소금과 모래가 섞여 있으면 먼저 물을 부어 저어요. 소금은 물에 녹고 모래는 녹지 않아요.", "이것을 거름종이를 올린 깔때기에 부으면 모래는 거름종이 위에 남고 소금물만 아래로 빠져요. 이렇게 거름종이로 거르는 것을 '거름'이라고 해요."], "figure": "깔때기에 거름종이를 끼우고 소금물과 모래를 부어 거르는 실험 장치 그림", "example": "커피를 내릴 때 커피 가루는 필터에 남고 커피 물만 내려오는 것도 거름이에요.", "heading": "물에 녹는 성질로 나누기 – 거름"}, {"paras": ["거름으로 얻은 소금물을 가열하거나 햇볕에 오래 두면 물이 증발해 날아가고 하얀 소금만 남아요. 가열할 때는 소금물이 튈 수 있으니 꼭 어른과 함께하고, 햇볕에 며칠 두는 방법이 더 안전해요.", "바닷가 염전에서는 바닷물을 햇볕과 바람에 증발시켜 소금을 얻어요."], "figure": "넓은 염전에 바닷물을 가두고 하얀 소금을 긁어모으는 모습", "example": "", "heading": "물을 날려 보내 나누기 – 증발"}], "parent_tip": "부모님께: 아이들은 소금이 물에 녹으면 '없어졌다'고 생각하곤 합니다. 소금물을 조금 맛보게 하거나 접시에 담아 며칠 두어 소금이 다시 나타나는 것을 보여 주세요. '주방에서 혼합물을 나누는 도구는 뭐가 있을까?'(체, 커피 필터, 국자 등)를 함께 찾아보는 것도 좋습니다.", "expressions": []}$j$::jsonb where slug='s3-05';
update public.lessons set title=$j$식초와 비눗물은 무엇이 다를까?$j$, content=$j${"quiz": [{"q": "푸른색 리트머스 종이를 붉은색으로 바꾸는 용액은?", "answer": 0, "choices": ["식초", "비눗물", "유리 세정제", "석회수"], "explain": "식초는 산성 용액이라 푸른색 리트머스 종이를 붉게 바꿔요."}, {"q": "페놀프탈레인 용액을 넣었을 때 붉은색으로 변하는 용액은?", "answer": 2, "choices": ["레몬즙", "식초", "비눗물", "탄산수"], "explain": "페놀프탈레인 용액은 염기성 용액에서 붉은색으로 변해요."}, {"q": "달걀 껍데기를 넣었을 때 기포가 생기며 녹는 용액은?", "answer": 0, "choices": ["산성 용액", "염기성 용액", "모든 용액", "어떤 용액도 녹이지 않음"], "explain": "산성 용액은 달걀 껍데기나 대리석을 녹여요."}, {"q": "두부를 넣었을 때 두부가 흐물흐물해지는 용액은?", "answer": 1, "choices": ["산성 용액", "염기성 용액", "물", "설탕물"], "explain": "염기성 용액은 두부나 삶은 달걀흰자를 녹여요."}, {"q": "속이 쓰릴 때 먹는 제산제의 원리로 옳은 것은?", "answer": 2, "choices": ["산성 물질로 위산을 강하게 한다", "위를 차갑게 한다", "염기성 물질로 위산의 산성을 약하게 한다", "음식을 녹인다"], "explain": "제산제는 염기성이라서 산성인 위산을 약하게 해요."}], "intro": "레몬즙은 시큼하고, 비눗물은 미끌미끌해요. 우리 주변의 용액은 성질에 따라 어떻게 나눌 수 있을까요?", "summary": ["지시약을 쓰면 용액을 산성과 염기성으로 분류할 수 있어요.", "산성은 대리석·달걀 껍데기를, 염기성은 두부·달걀흰자를 녹여요.", "산성과 염기성 용액을 섞으면 서로의 성질이 약해져요."], "keywords": [{"word": "지시약", "meaning": "용액의 성질에 따라 색깔이 변하는 물질"}, {"word": "산성 용액", "meaning": "푸른색 리트머스 종이를 붉게 바꾸는 용액"}, {"word": "염기성 용액", "meaning": "붉은색 리트머스 종이를 푸르게 바꾸는 용액"}, {"word": "리트머스 종이", "meaning": "산성·염기성을 알아보는 종이 지시약"}, {"word": "페놀프탈레인 용액", "meaning": "염기성 용액에서만 붉은색으로 변하는 지시약"}], "sections": [{"paras": ["용액의 성질에 따라 색깔이 변하는 물질을 '지시약'이라고 해요. 지시약을 쓰면 겉보기에 비슷한 용액도 산성과 염기성으로 나눌 수 있어요.", "리트머스 종이를 쓰면, 산성 용액은 푸른색 리트머스 종이를 붉은색으로, 염기성 용액은 붉은색 리트머스 종이를 푸른색으로 바꿔요."], "figure": "푸른색 리트머스 종이가 식초에서 붉게, 붉은색 리트머스 종이가 비눗물에서 푸르게 변하는 그림", "example": "식초에 푸른색 리트머스 종이를 넣으면 붉게 변해요. 식초는 산성이에요.", "heading": "지시약으로 용액 분류하기"}, {"paras": ["페놀프탈레인 용액은 산성 용액에서는 색깔이 변하지 않고, 염기성 용액에서는 붉은색으로 변해요.", "붉은 양배추로 만든 지시약은 산성 용액에서 붉은색 계열, 염기성 용액에서 푸른색이나 노란색 계열로 변해요. BTB 용액은 산성에서 노란색, 염기성에서 파란색으로 변해요."], "figure": "붉은 양배추 지시약이 담긴 시험관들이 산성(붉은색)부터 염기성(푸른·노란색)까지 색이 다른 모습", "example": "붉은 양배추 지시약에 레몬즙을 넣으면 붉게, 비눗물을 넣으면 푸르게 변해요.", "heading": "여러 가지 지시약"}, {"paras": ["산성 용액은 대리석이나 달걀 껍데기를 녹이는 성질이 있어요. 넣으면 기포가 생기면서 녹아요.", "염기성 용액은 두부나 삶은 달걀흰자 같은 단백질을 녹여 흐물흐물하게 만들어요."], "figure": "묽은 염산에 달걀 껍데기를 넣어 기포가 생기는 모습과 수산화 나트륨 용액에 두부가 흐물해진 모습", "example": "대리석으로 만든 문화재는 산성비에 조금씩 녹아 훼손될 수 있어요.", "heading": "산성 용액과 염기성 용액의 성질"}, {"paras": ["산성 용액에 염기성 용액을 조금씩 넣으면 산성이 점점 약해지다가 염기성으로 바뀌어요. 반대로 염기성 용액에 산성 용액을 넣으면 염기성이 점점 약해져요.", "이 성질은 생활에서 많이 쓰여요. 속이 쓰릴 때 먹는 제산제(염기성)는 위산(산성)을 약하게 하고, 생선을 손질한 도마를 식초(산성)로 닦으면 비린내(염기성)가 줄어요."], "figure": "산성 용액에 염기성 용액을 한 방울씩 넣을 때 지시약 색이 바뀌는 시험관 그림", "example": "벌레에게 물려 가려울 때 묽은 암모니아수가 든 염기성 약을 바르는 것도 같은 원리예요. (집에 있는 세제를 직접 바르면 절대 안 돼요!)", "heading": "산성 용액과 염기성 용액을 섞으면"}], "parent_tip": "부모님께: 아이들은 '산성은 위험하고 염기성은 안전하다'처럼 단순하게 생각하기도 합니다. 집에서 붉은 양배추 물을 끓여 식초, 레몬즙, 베이킹 소다 물, 비눗물 등에 넣어 색 변화를 보며 '어느 쪽이 산성일까?'를 함께 맞혀 보세요. 세제류는 반드시 보호자가 다뤄 주세요.", "expressions": []}$j$::jsonb where slug='s5-02';
update public.lessons set title=$j$바람은 왜 불고, 구름은 어떻게 생길까?$j$, content=$j${"quiz": [{"q": "바람이 부는 방향으로 옳은 것은?", "answer": 1, "choices": ["저기압에서 고기압으로", "고기압에서 저기압으로", "항상 북쪽에서 남쪽으로", "기압과 관계없다"], "explain": "공기는 기압이 높은 곳에서 낮은 곳으로 이동해요."}, {"q": "낮에 바닷가에서 바다에서 육지로 부는 바람은?", "answer": 1, "choices": ["육풍", "해풍", "계절풍", "태풍"], "explain": "낮에는 육지가 빨리 데워져 저기압이 되므로 바다에서 육지로 해풍이 불어요."}, {"q": "하늘 높이 올라간 공기 속 수증기가 응결해 떠 있는 것은?", "answer": 3, "choices": ["이슬", "서리", "안개", "구름"], "explain": "공기가 높이 올라가 차가워지면 수증기가 응결해 구름이 돼요."}, {"q": "우리나라 여름 날씨에 영향을 주는 공기 덩어리의 성질은?", "answer": 0, "choices": ["덥고 습하다", "춥고 건조하다", "따뜻하고 건조하다", "차갑고 습하다"], "explain": "여름에는 남동쪽 바다에서 오는 덥고 습한 공기 덩어리의 영향을 받아요."}, {"q": "습도가 높을 때 생기는 일로 알맞은 것은?", "answer": 0, "choices": ["빨래가 잘 마르지 않는다", "산불이 나기 쉽다", "피부가 건조해진다", "정전기가 잘 생긴다"], "explain": "공기 중 수증기가 많으면 빨래의 물이 잘 증발하지 않아요."}], "intro": "어떤 날은 빨래가 금방 마르고, 어떤 날은 눅눅해서 잘 안 말라요. 날씨는 왜 날마다 달라질까요?", "summary": ["습도는 공기 중 수증기의 양으로, 우리 생활에 영향을 줘요.", "수증기가 응결하면 이슬, 안개, 구름이 되고, 구름에서 비와 눈이 내려요.", "바람은 고기압에서 저기압으로 불며, 바닷가에서는 낮에 해풍, 밤에 육풍이 불어요."], "keywords": [{"word": "습도", "meaning": "공기 중에 수증기가 포함된 정도"}, {"word": "응결", "meaning": "수증기가 물방울로 변하는 것"}, {"word": "기압", "meaning": "공기의 무게 때문에 생기는 누르는 힘"}, {"word": "바람", "meaning": "기압 차이로 공기가 고기압에서 저기압으로 이동하는 것"}, {"word": "해풍", "meaning": "낮에 바다에서 육지로 부는 바람"}, {"word": "육풍", "meaning": "밤에 육지에서 바다로 부는 바람"}], "sections": [{"paras": ["공기 중에 수증기가 포함된 정도를 '습도'라고 해요. 습도는 건습구 습도계로 잴 수 있어요. 건구 온도와 습구 온도의 차이를 구해 습도표에서 찾으면 돼요.", "습도가 높으면 빨래가 잘 마르지 않고 음식이 쉽게 상해요. 습도가 낮으면 피부가 건조해지고 산불이 나기 쉬워요."], "figure": "건구 온도계와 젖은 헝겊을 감은 습구 온도계가 나란히 있는 건습구 습도계 그림", "example": "건구 온도와 습구 온도의 차이가 클수록 습도가 낮아요.", "heading": "습도"}, {"paras": ["공기 중의 수증기가 응결하면 여러 모습이 돼요. 밤에 차가워진 풀잎 표면에 수증기가 응결해 물방울로 맺히면 '이슬'이에요.", "지표면 가까이의 공기가 차가워져 수증기가 작은 물방울로 떠 있으면 '안개', 공기가 하늘 높이 올라가 차가워져 수증기가 물방울이나 얼음 알갱이로 떠 있으면 '구름'이에요."], "figure": "풀잎의 이슬, 땅 가까이 깔린 안개, 하늘 높이 떠 있는 구름을 한 장면에 그린 그림", "example": "구름 속 물방울이 커지고 무거워져 떨어지면 비, 얼음 알갱이가 녹지 않고 떨어지면 눈이 돼요.", "heading": "이슬, 안개, 구름"}, {"paras": ["공기의 무게 때문에 생기는 누르는 힘을 '기압'이라고 해요. 같은 부피일 때 차가운 공기는 따뜻한 공기보다 무거워 기압이 높아요. 주위보다 기압이 높은 곳을 '고기압', 낮은 곳을 '저기압'이라고 해요.", "두 지역 사이에 기압 차이가 생기면 공기가 고기압에서 저기압으로 이동하는데, 이것이 '바람'이에요."], "figure": "고기압에서 저기압으로 화살표가 향하는 바람 그림", "example": "바람을 불어 넣은 풍선의 입구를 놓으면 안쪽(높은 압력)의 공기가 바깥으로 빠져나가는 것과 비슷해요.", "heading": "고기압과 저기압, 그리고 바람"}, {"paras": ["낮에는 육지가 바다보다 빨리 데워져요. 육지 위는 저기압, 바다 위는 고기압이 되어 바다에서 육지로 바람이 부는데, 이것을 '해풍'이라고 해요.", "밤에는 육지가 바다보다 빨리 식어서 육지 위가 고기압, 바다 위가 저기압이 돼요. 그래서 육지에서 바다로 '육풍'이 불어요."], "figure": "낮에는 바다→육지(해풍), 밤에는 육지→바다(육풍)로 부는 바람을 나란히 비교한 그림", "example": "", "heading": "바닷가의 바람 – 해풍과 육풍"}, {"paras": ["우리나라는 계절마다 다른 공기 덩어리의 영향을 받아요. 공기 덩어리는 머물던 곳의 온도와 습도 성질을 닮아요.", "겨울에는 북서쪽 대륙에서 오는 차갑고 건조한 공기, 여름에는 남동쪽 바다에서 오는 덥고 습한 공기, 봄·가을에는 남서쪽 대륙에서 오는 따뜻하고 건조한 공기의 영향을 받아요."], "figure": "우리나라 주변에서 계절별로 영향을 주는 공기 덩어리의 방향과 성질을 표시한 지도", "example": "여름이 후텁지근하고 겨울이 춥고 건조한 까닭은 공기 덩어리 때문이에요.", "heading": "계절별 날씨와 공기 덩어리"}], "parent_tip": "부모님께: 아이들은 바람이 '저기압에서 고기압으로' 분다고 거꾸로 기억하는 경우가 많습니다. '공기가 꽉 찬 쪽(고기압)에서 덜 찬 쪽(저기압)으로 빠져나간다'고 풍선에 빗대어 설명해 보세요. 일기 예보를 함께 보며 '오늘 습도는 몇 %일까?'를 확인하는 것도 좋습니다.", "expressions": []}$j$::jsonb where slug='s5-06';
update public.activities set content=$j$[{"note": "살 것 없음 · 우유팩을 모아 두세요", "rows": [{"how": "깨끗이 씻어 말려요. 2개를 엇갈려 끼우면 정육면체 블록 1개가 돼요.", "kit": false, "name": "1L 우유팩 10개"}, {"how": "A~Z 26장 (A4 2장)", "kit": false, "name": "알파벳 카드 도안"}, {"how": "투명 테이프로 덮으면 오래 써요", "kit": false, "name": "풀, 가위, 테이프"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "우유팩 아랫부분을 높이 7cm 정도로 잘라 상자 2개를 만들고, 서로 입구를 맞대어 끼우면 정육면체 블록이 돼요.", "warn": "", "image": "assets/img/s_alphabet-blocks_1.jpg", "title": "블록 만들기"}, {"body": "알파벳 카드를 오려 블록 면에 하나씩 붙여요. 블록 5개면 26글자를 모두 붙일 수 있어요.", "warn": "", "image": "assets/img/s_alphabet-blocks_2.jpg", "title": "카드 붙이기"}, {"body": "블록을 굴려 위에 나온 글자를 읽고, 그 글자로 시작하는 낱말을 말해요. \"B! B is for ball!\"", "warn": "", "image": "assets/img/s_alphabet-blocks_3.jpg", "title": "굴려서 말하기"}, {"body": "블록을 돌려 가며 내 영어 이름이나 cat, dog 같은 짧은 낱말을 만들어 쌓아요.", "warn": "", "image": "assets/img/s_alphabet-blocks_4.jpg", "title": "이름 쌓기"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻과 쓰는 때"], "note": "", "rows": [["What letter is it?", "무슨 글자야? (블록을 굴린 뒤 물어요)"], ["It's B.", "B야."], ["B is for ball.", "B는 ball(공)의 B야. (글자와 낱말을 이어 말해요)"], ["Big B, little b.", "대문자 B, 소문자 b."]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/alphabet-cards.pdf", "desc": "대문자와 소문자, 그 글자로 시작하는 쉬운 낱말이 함께 있는 카드 26장. A4 2장.", "type": "template", "title": "알파벳 카드 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["3~4학년 영어는 알파벳을 보고 이름을 말하며, 대문자와 소문자를 짝짓는 데서 시작합니다. 글자 이름(비, 씨)과 낱말 속 소리(ㅂ, ㅋ)가 다르다는 것을 놀이 속에서 자연스럽게 느끼게 해 주세요. 발음이 걱정되면 사전 앱의 듣기 버튼을 아이와 함께 눌러 보세요."]}, {"label": "이렇게 칭찬해 주세요", "paras": ["Good job! · Great! · You did it!", "잘했어! · 멋져! · 해냈구나! 틀려도 \"Nice try!(좋은 시도야!)\"라고 말해 주세요."]}], "title": ""}, {"type": "more", "items": [{"body": "카드를 A부터 Z까지 줄 세우며 노래를 불러요.", "title": "알파벳 순서 기차"}, {"body": "B 카드를 들고 b로 시작하는 물건(book, bag)을 찾아요.", "title": "집 안 보물찾기"}, {"body": "대문자와 소문자를 따로 오려 뒤집어 놓고 짝을 찾아요.", "title": "짝 맞추기"}]}, {"type": "info", "items": [{"label": "도안", "value": "알파벳 카드 26장 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 알파벳 대소문자, 쉬운 낱말 읽기"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$[]$j$::jsonb)), updated_at=now() where slug='alphabet-blocks';
update public.activities set content=$j$[{"note": "공원·화단에서 재료를 조금씩 모아요", "rows": [{"how": "가운데를 잘라 아래는 그릇, 위는 뚜껑으로 써요", "kit": false, "name": "2L 투명 페트병"}, {"how": "맨 아래 물 빠짐 층", "kit": false, "name": "작은 자갈"}, {"how": "화분 흙", "kit": false, "name": "흙"}, {"how": "화단·공원에서 조금만 (허락받은 곳에서)", "kit": false, "name": "이끼와 작은 풀"}, {"how": "처음 한 번만 물을 뿌려요", "kit": false, "name": "분무기"}, {"how": "아래에서 내려받아요", "kit": false, "name": "관찰 일지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "페트병 가운데를 잘라 위아래로 나눠요.", "warn": "자르기는 어른이 해요.", "image": "assets/img/s_bottle-terrarium_1.jpg", "title": "병 자르기"}, {"body": "아래 병에 자갈 2cm, 흙 5cm를 차례로 넣어요.", "warn": "", "image": "assets/img/s_bottle-terrarium_2.jpg", "title": "층 쌓기"}, {"body": "이끼를 깔고 작은 풀을 심어요. 공벌레 한두 마리를 넣고 싶다면 먹이가 되는 마른 낙엽 몇 장도 함께 넣어 주세요.", "warn": "", "image": "assets/img/s_bottle-terrarium_3.jpg", "title": "식물 심기"}, {"body": "분무기로 흙이 촉촉해질 만큼만 물을 뿌리고, 위쪽 병을 덮어 테이프로 붙여요. 뚜껑도 닫아요.", "warn": "", "image": "assets/img/s_bottle-terrarium_4.jpg", "title": "물 주고 닫기"}, {"body": "햇빛이 직접 들지 않는 밝은 창가에 두고 일주일에 두 번 관찰 일지를 써요. 병 안쪽 물방울과 식물 상태를 봐요.", "warn": "", "image": "assets/img/s_bottle-terrarium_5.jpg", "title": "관찰하기"}], "notes": ["4주 관찰이 끝나면 넣었던 공벌레는 데려온 곳에 놓아 주세요."], "title": "실험 방법"}, {"type": "questions", "items": ["물을 다시 주지 않았는데 병 안이 촉촉한 까닭은 무엇일까요?", "아침과 저녁에 병 안쪽 물방울 양이 다른가요?", "식물이 시들었다면 어떤 환경 요인이 맞지 않았을까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["생태계는 식물, 동물 같은 생물과 햇빛, 물, 흙, 공기 같은 환경이 서로 영향을 주고받는 곳이에요. 병 속에서 식물은 햇빛을 받아 양분을 만들고, 물은 증발했다가 병 벽에서 물방울이 되어 다시 흙으로 떨어지며 돌고 돌아요."]}, {"label": "부모님께", "paras": ["5~6학년 '생물과 환경'은 생태계 구성 요소, 먹이 관계, 비생물 요소(빛, 온도, 물)가 생물에 미치는 영향을 다룹니다. 닫힌 병 안에서 물이 순환하는 모습은 생태계를 눈으로 보는 좋은 예입니다.", "곰팡이가 피면 실패가 아니라 분해자가 등장한 것이라는 점도 함께 이야기해 주세요. 다만 심하면 뚜껑을 열어 환기합니다.", "이렇게 물어보세요: \"병 속 생태계에서 한 가지가 사라진다면 무엇이 가장 먼저 영향을 받을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/bottle-terrarium.pdf", "desc": "4주 관찰 칸(주 2회)과 생태계 구성 요소 정리표. A4 1장.", "type": "template", "title": "미니 생태계 관찰 일지"}, {"type": "more", "items": [{"body": "똑같이 만든 병 두 개를 밝은 곳과 어두운 곳에 두고 비교해요.", "title": "빛 비교"}, {"body": "우리 동네 공원의 생물로 먹이 그물을 그려요.", "title": "먹이 그물 그리기"}, {"body": "사과 조각을 지퍼백에 넣어 곰팡이가 생기는 과정을 봐요.", "title": "분해자 관찰"}]}, {"type": "info", "items": [{"label": "도안", "value": "관찰 일지 (A4 1장)"}, {"label": "실험 키트", "value": "집과 공원 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 생물과 환경 (생태계)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["페트병 자르기는 어른이"]$j$::jsonb)), updated_at=now() where slug='bottle-terrarium';
update public.activities set content=$j$[{"note": "애벌레만 구하면 나머지는 집 재료", "rows": [{"how": "윗부분을 잘라 내 관찰통으로 써요", "kit": false, "name": "2L 투명 페트병"}, {"how": "입구를 덮어 공기는 통하고 애벌레는 못 나가게. 고무줄 1개로 묶고, 바닥에 깔 키친타월도 준비해요", "kit": false, "name": "양파망이나 거즈"}, {"how": "텃밭 배추·케일 잎 뒷면에서 찾거나 관찰 세트로 구해요", "kit": true, "name": "배추흰나비 애벌레"}, {"how": "애벌레 먹이. 농약이 묻지 않은 잎이어야 해요", "kit": false, "name": "싱싱한 배추·케일 잎"}, {"how": "번데기가 붙을 자리예요", "kit": false, "name": "나무젓가락 1개"}, {"how": "아래에서 내려받아요", "kit": false, "name": "관찰 일지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "페트병 윗부분을 잘라 내고, 바닥에 키친타월을 깔아요. 나무젓가락을 비스듬히 세워 넣어요.", "warn": "자르기는 어른이 해요.", "image": "assets/img/s_butterfly-life-cycle_1.jpg", "title": "관찰통 만들기"}, {"body": "애벌레가 붙은 잎째로 옮겨요. 손으로 직접 잡으면 다칠 수 있어요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_2.jpg", "title": "애벌레 옮기기"}, {"body": "양파망이나 거즈를 씌우고 고무줄로 묶어요. 햇빛이 바로 드는 곳은 피해요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_3.jpg", "title": "입구 덮기"}, {"body": "하루 한 번 시든 잎과 똥을 치우고 새 잎을 넣어요. 잎에 물방울이 많으면 닦아 줘요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_4.jpg", "title": "매일 먹이와 청소"}, {"body": "크기, 색, 움직임을 날짜별로 그리고 적어요. 번데기가 되면 건드리지 말고 기다려요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_5.jpg", "title": "관찰 일지 쓰기"}, {"body": "나비가 나와 날개가 마르면 밖에 나가 날려 보내 줘요.", "warn": "", "image": "assets/img/s_butterfly-life-cycle_6.jpg", "title": "나비 날려 보내기"}], "notes": ["애벌레를 구하기 어려우면 다른 곤충의 한살이 영상을 함께 보고, 관찰 일지는 그림 카드로 순서 맞히기를 해도 좋아요."], "title": "실험 방법"}, {"type": "questions", "items": ["애벌레는 허물을 몇 번 벗나요? 벗을 때마다 무엇이 달라지나요?", "번데기일 때는 먹지도 움직이지도 않는데, 안에서는 무슨 일이 생길까요?", "애벌레와 나비는 먹는 것이 어떻게 다를까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["배추흰나비는 알에서 깨어나 애벌레가 되고, 배추 잎을 먹으며 몇 번 허물을 벗고 자라요. 다 자라면 번데기가 되어 한동안 꼼짝하지 않다가, 어느 날 껍질을 뚫고 나비가 되어 나와요. 이렇게 알에서 어른이 되기까지의 과정을 한살이라고 해요."]}, {"label": "부모님께", "paras": ["배추흰나비처럼 알 → 애벌레 → 번데기 → 어른벌레를 거치는 것을 완전 탈바꿈이라고 하고, 번데기 단계가 없는 메뚜기·잠자리 같은 곤충은 불완전 탈바꿈을 합니다. 3학년 '동물의 한살이' 단원의 핵심 비교입니다.", "관찰이 끝나면 반드시 자연으로 돌려보내는 것까지가 활동이라는 점을 함께 이야기해 주세요.", "이렇게 물어보세요: \"사람의 한살이와 나비의 한살이는 무엇이 같고 무엇이 다를까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/butterfly-life-cycle.pdf", "desc": "날짜별 관찰 칸 8개와 한살이 순서 그림 카드. A4 1장.", "type": "template", "title": "한살이 관찰 일지"}, {"type": "more", "items": [{"body": "벗은 허물을 테이프로 일지에 붙여 크기를 비교해요.", "title": "허물 모으기"}, {"body": "개미, 매미, 잠자리의 한살이를 찾아 그림으로 그려요.", "title": "다른 곤충 비교"}, {"body": "관찰 일지 그림을 오려 순서 맞히기 놀이를 해요.", "title": "한살이 순서 카드"}]}, {"type": "info", "items": [{"label": "도안", "value": "한살이 관찰 일지 (A4 1장)"}, {"label": "실험 키트", "value": "배추흰나비 애벌레 관찰 세트 (준비 중)"}, {"label": "교육과정 연결", "value": "3~4학년 동물의 한살이 (완전 탈바꿈)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["페트병 자르기는 어른이"]$j$::jsonb)), updated_at=now() where slug='butterfly-life-cycle';
update public.activities set content=$j$[{"note": "살 것 없음 · 부엌에 있는 재료", "rows": [{"how": "잘게 찢어서 써요", "kit": false, "name": "적양배추 잎 2~3장"}, {"how": "전기포트 물 (어른이 부어요)", "kit": false, "name": "뜨거운 물"}, {"how": "유리컵이나 투명 플라스틱 컵", "kit": false, "name": "투명 컵 6개"}, {"how": "주방용 체나 거름망", "kit": false, "name": "체"}, {"how": "식초, 레몬즙", "kit": false, "name": "산성 재료"}, {"how": "베이킹소다, 비눗물", "kit": false, "name": "염기성 재료"}, {"how": "아래에서 내려받아 인쇄해요", "kit": false, "name": "색 비교표 도안"}], "type": "materials", "image": "assets/img/e7_mat.jpg"}, {"type": "steps", "items": [{"body": "잘게 찢은 잎을 그릇에 담고 뜨거운 물을 부어 10분 기다려요. 진한 보라색 물이 나오면 체로 걸러요.", "warn": "뜨거운 물은 어른이 다뤄요.", "image": "assets/img/e7_s1.jpg", "title": "양배추 물 우리기"}, {"body": "식은 양배추 물을 투명 컵 여러 개에 3cm씩 나눠 담아요. 한 컵은 비교용으로 그대로 둬요.", "warn": "", "image": "assets/img/s_cabbage-indicator_2.jpg", "title": "컵에 나눠 담기"}, {"body": "식초와 레몬즙을 한 숟가락씩 서로 다른 컵에 넣어요. 색이 어떻게 변하나요?", "warn": "", "image": "assets/img/e7_s2.jpg", "title": "산성 재료 넣기"}, {"body": "베이킹소다를 물에 녹여 다른 컵에 넣고, 비눗물도 넣어 봐요.", "warn": "", "image": "assets/img/s_cabbage-indicator_4.jpg", "title": "염기성 재료 넣기"}, {"body": "색 비교표 옆에 컵을 줄 세우고, 산성인지 염기성인지 기록표에 적어요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_cabbage-indicator_5.jpg", "title": "색 비교표와 맞춰 보기"}], "notes": ["안전: 락스, 변기 세정제 같은 청소용 세제는 절대 섞지 마세요. 위험한 기체가 나올 수 있어요. 실험한 물은 마시지 말고 싱크대에 버려요."], "title": "만드는 방법"}, {"pdf": "assets/pdf/ph-color-chart.pdf", "desc": "색 안내표와 내 실험 기록표가 들어 있어요. A4 1장, 컬러로 인쇄하면 좋아요.", "type": "template", "title": "산·염기 색 비교표"}, {"type": "questions", "items": ["가장 진한 분홍색이 된 컵은 무엇을 넣은 컵인가요?", "식초 컵에 베이킹소다를 조금씩 넣으면 어떤 일이 생기나요?", "우유, 사이다, 치약 녹인 물은 어느 쪽일까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["적양배추 속에는 '색깔 탐정' 물질이 들어 있어요. 이 탐정은 신맛 나는 산성을 만나면 분홍색 옷으로, 미끈미끈한 염기성을 만나면 파란색이나 초록색 옷으로 갈아입어요. 그래서 색만 보고도 산성인지 염기성인지 알 수 있어요."]}, {"label": "부모님께", "paras": ["적양배추에는 안토시아닌이라는 색소가 있어, 용액의 산성과 염기성 정도(pH)에 따라 색이 달라집니다. 이렇게 색으로 산성과 염기성을 알려 주는 물질을 지시약이라고 합니다. 식초에 베이킹소다를 넣으면 거품이 나며 색이 보라색 쪽으로 돌아가는데, 산과 염기가 서로의 성질을 약하게 만드는 중화 반응입니다.", "이렇게 물어보세요: \"양배추 물로 리트머스 종이 같은 지시약 종이를 만들 수 있을까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "키친타월을 양배추 물에 적셔 말린 뒤 잘라서 써요.", "title": "양배추 종이 만들기"}, {"body": "분홍 컵에 베이킹소다 물을 한 방울씩 넣어 보라색으로 되돌려요.", "title": "색 되돌리기"}, {"body": "면봉에 베이킹소다 물을 묻혀 글씨를 쓰고 말린 뒤 양배추 물을 바르면 초록색 글씨가 나타나요.", "title": "비밀 편지"}]}, {"type": "info", "items": [{"label": "도면", "value": "산·염기 색 비교표 (A4 1장)"}, {"label": "실험 키트", "value": "부엌 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 산과 염기 (지시약, 중화)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["뜨거운 물은 어른이"]$j$::jsonb)), updated_at=now() where slug='cabbage-indicator';
update public.activities set content=$j$[{"note": "반드시 어른이 곁에서 함께해요", "rows": [{"how": "작고 낮은 초가 안전해요", "kit": false, "name": "티라이트 초 1개"}, {"how": "잼병, 음료병처럼 입구가 넓은 것", "kit": false, "name": "크기가 다른 유리병 3개"}, {"how": "초 아래 받쳐요. 만일을 위해 젖은 행주나 냄비 뚜껑을 곁에 둬요 (촛농 불에는 물을 붓지 않아요)", "kit": false, "name": "쟁반과 물 한 컵"}, {"how": "불은 어른만 붙여요", "kit": false, "name": "라이터 (어른용)"}, {"how": "꺼질 때까지 시간을 재요", "kit": false, "name": "시계"}, {"how": "아래에서 내려받아요", "kit": false, "name": "기록표 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "탁자 위 물건을 치우고 쟁반에 초를 올려요. 머리카락은 묶고, 물 한 컵을 곁에 둬요.", "warn": "불은 어른만 붙이고 다뤄요.", "image": "assets/img/s_candle-jar_1.jpg", "title": "안전 준비"}, {"body": "어른이 불을 붙인 뒤 가장 작은 병을 덮고, 꺼질 때까지 시간을 재요.", "warn": "", "image": "assets/img/s_candle-jar_2.jpg", "title": "작은 병부터"}, {"body": "병이 식은 뒤 중간 병, 큰 병으로 바꿔 같은 방법으로 시간을 재요. 병은 뜨거우니 바로 만지지 않아요.", "warn": "병이 뜨거워요. 식을 때까지 기다려요.", "image": "assets/img/s_candle-jar_3.jpg", "title": "큰 병으로 반복"}, {"body": "병 크기와 꺼진 시간을 기록표에 적고, 어떤 관계가 있는지 이야기해요.", "warn": "", "image": "assets/img/s_candle-jar_4.jpg", "title": "결과 정리"}, {"body": "촛불을 끄는 다른 방법(입김, 뚜껑 덮기, 심지 집기)을 떠올리고, 각각 무엇을 없앤 것인지 나눠 봐요.", "warn": "", "image": "assets/img/s_candle-jar_5.jpg", "title": "소화 방법 찾기"}], "notes": ["안전: 아이 혼자 불을 붙이거나 다루지 않게 해 주세요. 실험이 끝나면 어른이 초를 끄고, 촛농이 완전히 굳어 식을 때까지 만지지 않아요. 초 불이 번지면 물을 붓지 말고 병이나 뚜껑을 덮어 꺼요."], "title": "실험 방법"}, {"type": "questions", "items": ["큰 병을 덮었을 때 촛불이 더 오래 탄 까닭은 무엇일까요?", "병 안쪽 벽에 무엇이 생겼나요?", "소화기는 불을 끌 때 무엇을 없애는 걸까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["불이 타려면 탈 물질, 산소, 불이 붙을 만큼의 온도 세 가지가 모두 있어야 해요. 병을 덮으면 촛불이 병 속 산소를 쓰다가 산소가 모자라서 꺼져요. 큰 병에는 공기가 더 많아서 더 오래 타요."]}, {"label": "부모님께", "paras": ["6학년 '연소와 소화' 단원은 연소의 조건(탈 물질, 산소, 발화점 이상의 온도)과, 이 중 하나 이상을 없애는 소화의 원리를 다룹니다. 병 안쪽에 맺히는 뿌연 물방울은 초가 탈 때 생긴 물입니다.", "병을 물 위에 덮어 물이 올라오는 실험은 산소 소비만으로 설명하기 어려운 부분이 있어 이 활동에서는 다루지 않았습니다. 시간 비교에 집중해 주세요.", "이렇게 물어보세요: \"우리 집에서 불이 나면 어떻게 대피하고, 소화기는 어디에 있을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/candle-jar.pdf", "desc": "병 크기별 시간 기록표와 소화의 세 가지 방법 정리 칸. A4 1장.", "type": "template", "title": "촛불 실험 기록표"}, {"type": "more", "items": [{"body": "소화기 위치와 사용 순서(안전핀 뽑기 → 노즐 잡기 → 손잡이 누르기)를 확인해요.", "title": "우리 집 소화기 찾기"}, {"body": "우리 집 대피 경로를 그려 현관에 붙여요.", "title": "대피 지도"}, {"title": "유리컵으로 비교", "body": "병 대신 크기가 다른 두꺼운 유리컵을 써서도 시간을 비교해요. 종이컵이나 플라스틱 컵은 불이 붙거나 녹을 수 있으니 절대 쓰지 않아요."}]}, {"type": "info", "items": [{"label": "도안", "value": "기록표 (A4 1장)"}, {"label": "실험 키트", "value": "티라이트 초 (생활용품점)"}, {"label": "교육과정 연결", "value": "5~6학년 연소와 소화"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["반드시 어른과 함께", "불 사용"]$j$::jsonb)), updated_at=now() where slug='candle-jar';
update public.activities set content=$j$[{"note": "식용색소만 있으면 돼요", "rows": [{"how": "하얀 부분이 많을수록 잘 보여요", "kit": false, "name": "셀러리 줄기 또는 배추 속잎"}, {"how": "마트 제과 코너의 액체 식용색소가 가장 잘 돼요. 수성 물감은 잘 올라가지 않을 수 있어요", "kit": false, "name": "식용색소 (빨강·파랑)"}, {"how": "색깔 물을 담아요", "kit": false, "name": "투명 컵이나 자른 페트병 2개"}, {"how": "잘린 단면을 자세히 봐요", "kit": false, "name": "돋보기"}, {"how": "아래에서 내려받아요", "kit": false, "name": "관찰 기록지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "컵 두 개에 물을 반쯤 담고 색소를 진하게 풀어요.", "warn": "", "image": "assets/img/s_colored-celery_1.jpg", "title": "색깔 물 만들기"}, {"body": "셀러리 아래쪽을 어른이 칼로 비스듬히 새로 잘라요. 자르고 바로 물에 꽂아야 잘 빨아올려요.", "warn": "칼은 어른이 써요.", "image": "assets/img/s_colored-celery_2.jpg", "title": "줄기 끝 자르기"}, {"body": "1시간, 3시간, 다음 날 아침에 잎과 줄기 색이 어떻게 변했는지 기록지에 그려요.", "warn": "", "image": "assets/img/s_colored-celery_3.jpg", "title": "시간마다 관찰"}, {"body": "다음 날 줄기를 가로로 잘라 단면을 돋보기로 봐요. 색이 든 점들이 보이나요?", "warn": "자르기는 어른이 칼로 해요.", "image": "assets/img/s_colored-celery_4.jpg", "title": "단면 보기"}, {"body": "줄기 아래를 세로로 반 갈라 한쪽은 빨강, 한쪽은 파랑 물에 꽂아 두면 잎은 어떻게 될까요?", "warn": "줄기 가르기는 어른이 칼로 해요.", "image": "assets/img/s_colored-celery_5.jpg", "title": "두 색 실험"}], "notes": [], "title": "실험 방법"}, {"type": "questions", "items": ["색은 줄기의 어느 부분을 따라 올라갔나요?", "잎 끝까지 색이 가는 데 얼마나 걸렸나요?", "잎을 다 떼어 낸 줄기도 물을 잘 빨아올릴까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["식물의 뿌리와 줄기 속에는 물이 지나가는 가느다란 관이 있어요. 이것을 물관이라고 해요. 잎에서 물이 수증기로 빠져나가면 아래에서 물이 계속 끌려 올라와서, 색깔 물이 잎까지 퍼져요."]}, {"label": "부모님께", "paras": ["6학년 '식물의 구조와 기능'은 뿌리의 흡수, 줄기의 물관, 잎의 증산 작용과 광합성을 다룹니다. 단면에서 보이는 색 점들이 물관 다발이며, 잎이 있을 때 물을 더 잘 끌어올리는 것은 증산 작용 때문입니다.", "잎을 뗀 줄기와 잎이 달린 줄기를 비교하면 증산 작용의 역할을 아이 스스로 발견할 수 있습니다.", "이렇게 물어보세요: \"큰 나무는 어떻게 꼭대기까지 물을 올려 보낼까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/colored-celery.pdf", "desc": "시간별 관찰 그림 칸과 단면 그리기 칸. A4 1장.", "type": "template", "title": "줄기 관찰 기록지"}, {"type": "more", "items": [{"body": "흰 카네이션이나 국화를 색깔 물에 꽂아 꽃잎을 물들여요.", "title": "흰 꽃 물들이기"}, {"body": "잎에 비닐봉지를 씌워 두고 안쪽에 맺히는 물방울을 봐요.", "title": "비닐 씌우기"}, {"body": "콩나물 뿌리를 돋보기로 보고 뿌리털을 찾아요.", "title": "뿌리 관찰"}]}, {"type": "info", "items": [{"label": "도안", "value": "관찰 기록지 (A4 1장)"}, {"label": "실험 키트", "value": "식용색소 (마트 제과 코너)"}, {"label": "교육과정 연결", "value": "5~6학년 식물의 구조와 기능 (물관, 증산 작용)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["칼은 어른이"]$j$::jsonb)), updated_at=now() where slug='colored-celery';
update public.activities set content=$j$[{"note": "자석 1개만 있으면 돼요", "rows": [{"how": "바느질 바늘. 클립을 곧게 펴서 3cm로 쓰면 더 안전해요.", "kit": false, "name": "바늘 1개"}, {"how": "막대자석이나 말굽자석. 냉장고 고무 자석은 힘이 약해서 잘 안 될 수 있어요.", "kit": true, "name": "자석 1개"}, {"how": "페트병 플라스틱 뚜껑", "kit": false, "name": "병뚜껑 1개"}, {"how": "국그릇이나 넓은 접시", "kit": false, "name": "넓은 그릇과 물"}, {"how": "바늘 고정용", "kit": false, "name": "셀로판테이프"}, {"how": "스마트폰 나침반 앱, 자석이 됐는지 확인할 클립 1개, 방향 표시용 작은 스티커", "kit": false, "name": "확인용"}], "type": "materials", "image": "assets/img/e2_mat.jpg"}, {"type": "steps", "items": [{"body": "자석의 한쪽 끝으로 바늘을 바늘귀에서 바늘 끝 방향으로 30번 문질러요. 꼭 한 방향으로만 문지르고, 한 번 문지른 뒤에는 자석을 들어 올려 처음 자리로 돌아가요.", "warn": "", "image": "assets/img/e2_s1.jpg", "title": "바늘을 자석으로 만들기"}, {"body": "바늘을 클립에 가까이 대 보세요. 클립이 살짝 끌려오면 성공이에요.", "warn": "", "image": "assets/img/s_floating-compass_2.jpg", "title": "자석이 됐는지 확인하기"}, {"body": "병뚜껑 안쪽에 바늘을 눕혀 셀로판테이프로 붙여요. 바늘이 뚜껑 한가운데를 지나가게 붙여야 균형이 잘 맞아요.", "warn": "", "image": "assets/img/e2_s2.jpg", "title": "병뚜껑에 붙이기"}, {"body": "그릇에 물을 담고 병뚜껑을 가운데에 살며시 띄워요. 뚜껑이 천천히 돌다가 한 방향에서 멈춰요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_floating-compass_4.jpg", "title": "물에 띄우기"}, {"body": "스마트폰 나침반 앱으로 북쪽을 확인해요. 바늘의 어느 끝이 북쪽을 가리키는지 작은 스티커로 표시하면 나만의 나침반 완성!", "warn": "", "image": "assets/img/s_floating-compass_5.jpg", "title": "방향 확인하고 표시하기"}], "notes": ["잘 안 될 때: 실험하는 동안 휴대폰, 스피커, 쇠숟가락은 그릇에서 멀리 두세요. 근처에 쇠붙이나 자석이 있으면 바늘이 그쪽으로 끌려가요."], "title": "만드는 방법"}, {"type": "questions", "items": ["뚜껑을 손가락으로 살짝 돌려 놓으면 어떻게 되나요?", "자석을 그릇 옆으로 천천히 가져가면 바늘이 어떻게 움직이나요?", "10번만 문지른 바늘과 30번 문지른 바늘은 무엇이 다른가요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["바늘을 자석으로 문지르면 바늘도 작은 자석이 돼요. 그런데 우리가 사는 지구도 아주아주 큰 자석이에요. 그래서 자석이 된 바늘은 언제나 북쪽과 남쪽을 가리켜요. 물 위에 띄우면 뚜껑이 마음대로 돌 수 있어서 바늘이 스스로 방향을 찾아가요."]}, {"label": "부모님께", "paras": ["쇠로 된 바늘을 자석으로 한 방향으로 문지르면 바늘이 자화되어 약한 자석이 됩니다. 지구는 거대한 자석이므로, 자유롭게 회전하는 자침은 지구 자기장을 따라 남북 방향으로 놓입니다. 물에 띄우면 마찰이 줄어 바늘이 쉽게 돌아갑니다. 어느 끝이 북쪽을 향할지는 문지른 자석의 극에 따라 달라지니 앱으로 확인해 표시하세요. 떨어뜨리거나 시간이 지나 자성이 약해지면 다시 문지르면 됩니다.", "이렇게 물어보세요: \"진짜 나침반 바늘은 왜 한쪽만 빨간색일까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "이면지에 동서남북을 그려 그릇 아래에 깔아요.", "title": "동서남북 판 만들기"}, {"body": "냉장고 옆에서는 바늘이 어떻게 될까요?", "title": "집 안 탐험"}, {"body": "베란다 창문이 어느 방향을 보는지 찾아봐요.", "title": "우리 집은 어느 쪽?"}]}, {"text": "안전: 작은 자석, 특히 동그란 강력 자석은 어린 동생이 삼키지 않도록 꼭 높은 곳에 보관해 주세요. 바늘은 실험 후 바늘꽂이에 바로 정리해요.", "type": "note"}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "막대자석 (구매 링크 준비 중)"}, {"label": "교육과정 연결", "value": "3~4학년 자석의 성질 (나침반 만들기)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["바늘은 어른과 함께"]$j$::jsonb)), updated_at=now() where slug='floating-compass';
update public.activities set content=$j$[{"note": "살 것 없음 · 색연필만 있으면 돼요", "rows": [{"how": "같은 수표 3장이 들어 있어요 (A4 2장)", "kit": false, "name": "1~100 수표 도안"}, {"how": "배수마다 다른 색으로 칠해요", "kit": false, "name": "색연필 3색 이상"}, {"how": "색칠 대신 칸을 덮어도 돼요", "kit": false, "name": "병뚜껑이나 바둑돌 (선택)"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "첫 번째 수표에서 2, 4, 6…처럼 2씩 뛰어 세며 노란색으로 칠해요. 어떤 무늬가 생기나요?", "warn": "", "image": "assets/img/s_hundred-chart-multiples_1.jpg", "title": "2의 배수 칠하기"}, {"body": "같은 수표에 3, 6, 9…를 파란 동그라미로 표시해요. 노란색과 파란 동그라미가 겹친 수를 찾아요.", "warn": "", "image": "assets/img/s_hundred-chart-multiples_2.jpg", "title": "3의 배수 표시하기"}, {"body": "두 표시가 겹친 6, 12, 18…이 2와 3의 공배수예요. 가장 작은 것은 무엇인가요? 그게 최소공배수예요.", "warn": "", "image": "assets/img/s_hundred-chart-multiples_3.jpg", "title": "공배수 찾기"}, {"body": "두 번째 수표에서 24를 고르고, 24를 나누어떨어지게 하는 수(1, 2, 3, 4, 6, 8, 12, 24)를 모두 색칠해요.", "warn": "", "image": "assets/img/s_hundred-chart-multiples_4.jpg", "title": "약수 찾기"}, {"body": "세 번째 수표에서 1을 지우고, 2를 남긴 채 2의 배수를 모두 지워요. 3, 5, 7도 같은 방법으로 해요. 남은 수가 소수예요.", "warn": "여기서 말하는 소수(素數)는 1과 자기 자신으로만 나누어떨어지는 수로, 0.1 같은 소수(小數)와 다른 말이에요. 중학교 1학년 내용과 이어지는 심화 활동이에요.", "image": "assets/img/s_hundred-chart-multiples_5.jpg", "title": "소수 체 거르기"}], "notes": ["5의 배수는 일의 자리가 0이나 5, 2의 배수는 일의 자리가 짝수라는 규칙도 수표에서 바로 보여요."], "title": "하는 방법"}, {"type": "questions", "items": ["2의 배수와 5의 배수를 모두 칠하면 겹치는 칸은 어디인가요?", "24와 36의 공약수는 무엇무엇일까요?", "약수가 딱 2개뿐인 수를 찾아볼까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["어떤 수를 나누어떨어지게 하는 수를 약수, 어떤 수를 1배, 2배, 3배 한 수를 배수라고 해요. 두 수의 배수에 공통으로 들어 있는 수가 공배수, 그중 가장 작은 수가 최소공배수예요. 수표에 색칠하면 배수가 일정한 간격으로 줄을 서는 게 보여요."]}, {"label": "부모님께", "paras": ["5학년 '약수와 배수'는 이어지는 '약분과 통분', '분수의 덧셈과 뺄셈'의 바탕입니다. 최대공약수·최소공배수를 계산 방법(공약수로 나누기)부터 외우기 전에 수표에서 눈으로 확인하게 하면 개념이 오래 남습니다.", "소수 체 거르기(에라토스테네스의 체)는 교과서 범위를 살짝 넘지만, 아이들이 아주 좋아하는 확장 활동입니다.", "이렇게 물어보세요: \"12와 18의 공배수 중 가장 작은 수는 수표에서 어디에 있을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/hundred-chart-multiples.pdf", "desc": "같은 수표 3장과 배수·약수 기록 칸. A4 2장.", "type": "template", "title": "1~100 수표"}, {"type": "more", "items": [{"body": "수표 일부를 오려 빙고판으로 쓰고 '4의 배수!'를 외쳐요.", "title": "배수 빙고"}, {"body": "6분, 8분마다 오는 버스가 다시 동시에 오는 시각을 공배수로 구해요.", "title": "버스 배차 문제"}, {"body": "콩 12개로 만들 수 있는 직사각형 모양을 모두 찾아 약수와 연결해요.", "title": "약수 직사각형"}]}, {"type": "info", "items": [{"label": "도안", "value": "1~100 수표 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 약수와 배수 (공약수, 공배수)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$[]$j$::jsonb)), updated_at=now() where slug='hundred-chart-multiples';
update public.activities set content=$j$[{"note": "살 것 없음 · 부엌 재료", "rows": [{"how": "같은 얼음 틀에서 꺼내요", "kit": false, "name": "같은 크기 얼음 5개"}, {"how": "얼음을 하나씩 담아요", "kit": false, "name": "지퍼백 5개"}, {"how": "녹이는 방법마다 써요", "kit": false, "name": "소금, 수건, 그릇"}, {"how": "하나는 냉장고에서 차갑게, 하나는 실온", "kit": false, "name": "페트병 2개"}, {"how": "녹는 시간을 재요", "kit": false, "name": "시계"}, {"how": "아래에서 내려받아요", "kit": false, "name": "관찰 기록지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "가족마다 얼음 녹이는 방법을 하나씩 골라요. 손으로 쥐기, 소금 뿌리기, 수건으로 싸기, 햇볕에 두기, 그대로 두기.", "warn": "", "image": "assets/img/s_ice-and-dew_1.jpg", "title": "방법 정하기"}, {"body": "지퍼백에 얼음을 넣고 같은 시각에 시작해요. 다 녹은 시각을 기록지에 적어요.", "warn": "", "image": "assets/img/s_ice-and-dew_2.jpg", "title": "동시에 시작"}, {"body": "가장 빨리 녹은 방법과 가장 늦게 녹은 방법을 찾아요. 수건으로 싼 얼음은 왜 늦게 녹았을까요?", "warn": "", "image": "assets/img/s_ice-and-dew_3.jpg", "title": "결과 비교"}, {"body": "냉장고에서 꺼낸 페트병과 실온 페트병을 나란히 두고 5분 기다려요. 어느 쪽 겉에 물방울이 맺히나요?", "warn": "", "image": "assets/img/s_ice-and-dew_4.jpg", "title": "컵 물방울 관찰"}, {"body": "맺힌 물방울을 휴지로 닦아 색이 있는지 봐요. 병 안의 음료가 새어 나온 걸까요?", "warn": "", "image": "assets/img/s_ice-and-dew_5.jpg", "title": "물방울 맛보기 대신 닦아 보기"}], "notes": [], "title": "실험 방법"}, {"type": "questions", "items": ["얼음이 녹으면 물의 양은 늘어날까요, 줄어들까요?", "차가운 병 겉의 물방울은 어디에서 왔을까요?", "겨울 아침 유리창이 뿌옇게 되는 것도 같은 까닭일까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["물은 얼음(고체), 물(액체), 수증기(기체)로 모습을 바꿔요. 따뜻한 열을 받으면 얼음이 녹아 물이 되고, 물이 증발하면 눈에 보이지 않는 수증기가 돼요. 공기 속 수증기가 차가운 병에 닿으면 다시 물방울로 변해서 병 겉에 맺혀요."]}, {"label": "부모님께", "paras": ["얼음이 녹는 것은 융해, 물이 수증기가 되는 것은 증발, 수증기가 차가운 표면에서 물방울이 되는 것은 응결입니다. 병 겉 물방울이 '병에서 샌 물'이 아니라 공기 중 수증기라는 것을 아이 스스로 추론하게 하는 것이 이 활동의 핵심입니다.", "수건으로 싼 얼음이 늦게 녹는 것은 수건이 바깥 열이 들어오는 것을 막기 때문입니다. 아이스박스와 같은 원리예요.", "이렇게 물어보세요: \"아이스크림을 오래 안 녹게 가져가려면 무엇으로 싸면 좋을까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/ice-and-dew.pdf", "desc": "얼음 녹이기 경주 기록표와 물방울 관찰 칸. A4 1장.", "type": "template", "title": "물의 상태 변화 기록지"}, {"type": "more", "items": [{"body": "녹기 전 얼음과 녹은 물의 무게를 저울로 비교해요.", "title": "얼음 무게 재기"}, {"body": "식용색소 얼음이 녹으며 물에 퍼지는 모습을 관찰해요.", "title": "색깔 얼음"}, {"body": "접시에 물을 담아 두고 하루마다 양을 표시해요.", "title": "물 증발 관찰"}]}, {"type": "info", "items": [{"label": "도안", "value": "관찰 기록지 (A4 1장)"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 물의 상태 변화 (얼음이 녹음, 증발, 응결)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["뜨거운 물은 어른이"]$j$::jsonb)), updated_at=now() where slug='ice-and-dew';
update public.activities set content=$j$[{"note": "살 것 없음", "rows": [{"how": "달력판으로 써요 (없으면 상자 판을 동그랗게)", "kit": false, "name": "종이접시 1개"}, {"how": "30칸 달력과 달 모양 5단계 카드", "kit": false, "name": "달 관찰 달력 도안"}, {"how": "본 모양 그대로 칠해요", "kit": false, "name": "연필, 색연필"}, {"how": "달 모양이 바뀌는 까닭을 실험해요", "kit": false, "name": "손전등, 공 (선택)"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안의 30칸 달력을 오려 종이접시에 붙여요.", "warn": "", "image": "assets/img/s_moon-phase-calendar_1.jpg", "title": "달력 붙이기"}, {"body": "저녁 같은 시각에 같은 곳에서 달을 찾아요. 보이는 모양을 칸에 그대로 칠해요. 구름 낀 날은 '구름'이라고 적어요.", "warn": "", "image": "assets/img/s_moon-phase-calendar_2.jpg", "title": "매일 같은 시각에 보기"}, {"body": "모양 카드를 보고 초승달, 상현달, 보름달, 하현달, 그믐달 중 무엇인지 적어요.", "warn": "", "image": "assets/img/s_moon-phase-calendar_3.jpg", "title": "이름 붙이기"}, {"body": "한 달이 지나면 달력을 보며 달 모양이 어떤 차례로 바뀌었는지 이어 말해요.", "warn": "", "image": "assets/img/s_moon-phase-calendar_4.jpg", "title": "차례 찾기"}, {"body": "어두운 방 한쪽에 손전등을 켜서 고정해 두고(태양), 공(달)을 팔을 뻗어 얼굴 앞에 든 채 제자리에서 천천히 한 바퀴 돌아요. 공의 밝은 부분이 어떻게 보이나요?", "warn": "", "image": "assets/img/s_moon-phase-calendar_5.jpg", "title": "손전등 실험"}], "notes": ["초승달·상현달은 해 진 뒤 저녁 하늘에서 보이고, 보름달은 해 질 무렵 동쪽에서 떠요. 보름 뒤로는 달이 날마다 늦게 떠서 하현달은 새벽~아침 남쪽 하늘, 그믐달은 해 뜨기 전 동쪽 하늘에서만 보여요. 저녁에 안 보이는 날은 다음 날 아침 일찍 찾아보거나 '안 보임'이라고 기록해 두면 됩니다."], "title": "실험 방법"}, {"type": "questions", "items": ["보름달 다음에는 달이 어느 쪽부터 줄어드나요?", "같은 모양의 달이 다시 보이기까지 며칠쯤 걸리나요?", "달은 왜 날마다 모양이 바뀌어 보일까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["달은 스스로 빛을 내지 않고 햇빛을 받아 반사해요. 달이 지구 둘레를 돌면서 우리에게 햇빛 받은 부분이 보이는 만큼만 밝게 보이기 때문에, 날마다 모양이 달라 보여요. 달 모양은 약 한 달마다 다시 처음으로 돌아와요."]}, {"label": "부모님께", "paras": ["달의 위상은 초승달 → 상현달 → 보름달 → 하현달 → 그믐달 순으로 약 29.5일 주기로 바뀝니다. 음력 날짜와 거의 맞아서 음력 15일 무렵이 보름달입니다.", "손전등과 공 실험은 3~4학년 수준에서 '보이는 부분이 달라진다'는 생각을 몸으로 이해하게 하는 데 목적이 있습니다. 정확한 궤도 설명보다 관찰한 차례를 말할 수 있으면 충분합니다.", "이렇게 물어보세요: \"추석이나 정월 대보름에는 왜 꼭 보름달이 뜰까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/moon-phase-calendar.pdf", "desc": "30칸 관찰 달력과 달 모양 5단계 카드. A4 1장.", "type": "template", "title": "달 관찰 달력"}, {"type": "more", "items": [{"body": "오레오 쿠키 크림을 긁어 달 모양 5단계를 만들어요.", "title": "달 쿠키"}, {"body": "휴대폰 달력에서 음력 날짜와 관찰한 달 모양을 맞춰 봐요.", "title": "음력 달력 찾기"}, {"body": "보름달을 쌍안경으로 보고 어두운 무늬를 그려요.", "title": "달 표면 관찰"}]}, {"type": "info", "items": [{"label": "도안", "value": "달 관찰 달력 (A4 1장)"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 지구와 달의 운동 (여러 날 동안 달의 모양 변화)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["밤 관찰은 어른과 함께"]$j$::jsonb)), updated_at=now() where slug='moon-phase-calendar';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "피자 상자나 택배 상자를 펼쳐서", "kit": false, "name": "두꺼운 종이 상자"}, {"how": "아래에서 내려받아 컬러로 인쇄해요", "kit": false, "name": "분수 원판 도안"}, {"how": "상자 자르기는 어른이 해요", "kit": false, "name": "풀, 가위, 커터칼"}, {"how": "조각 뒷면에 분수를 적어요", "kit": false, "name": "네임펜"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안을 인쇄해 원 6개를 오리고, 펼친 상자 판에 풀로 붙여요.", "warn": "", "image": "assets/img/s_pizza-fractions_1.jpg", "title": "도안 붙이기"}, {"body": "원 테두리와 안쪽 선을 따라 조각을 잘라요. 조각 뒷면에 1/2, 1/3처럼 분수를 적어 둬요.", "warn": "두꺼운 상자는 어른이 커터칼로 잘라 주세요.", "image": "assets/img/s_pizza-fractions_2.jpg", "title": "조각 자르기"}, {"body": "노란 '1' 원 위에 1/2 조각 두 개를 올려 보세요. 딱 맞게 덮이나요? 1/4 조각 몇 개로 덮을 수 있는지도 세어 봐요.", "warn": "", "image": "assets/img/s_pizza-fractions_3.jpg", "title": "전체 위에 덮어 보기"}, {"body": "조각 두 개를 골라 겹쳐 보고 더 큰 쪽을 맞혀요. \"1/3 피자와 1/4 피자 중 어느 쪽을 먹을래?\"", "warn": "", "image": "assets/img/s_pizza-fractions_4.jpg", "title": "크기 비교 게임"}, {"body": "1/2 조각 하나를 다른 조각들로 똑같이 덮어 보세요. 1/4로는 몇 개, 1/8로는 몇 개가 필요한가요?", "warn": "", "image": "assets/img/s_pizza-fractions_5.jpg", "title": "같은 크기 찾기"}], "notes": [], "title": "하는 방법"}, {"pdf": "assets/pdf/fraction-circles.pdf", "desc": "전체, 1/2, 1/3, 1/4, 1/6, 1/8 원판 6장. 분모마다 색이 달라 아이가 쉽게 구분해요. A4 1장.", "type": "template", "title": "분수 원판 도안"}, {"type": "questions", "items": ["아래 숫자가 커질수록 한 조각의 크기는 어떻게 되나요?", "1/4 조각 3개를 모으면 원의 얼마만큼이 될까요?", "크기가 다르게 자른 조각도 1/4이라고 부를 수 있을까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["피자를 똑같이 나눌수록 한 조각은 작아져요. 2명이 나누면 1/2, 4명이 나누면 1/4이에요. 아래 숫자는 몇 조각으로 똑같이 나눴는지, 위 숫자는 그중 몇 조각을 가졌는지를 알려 줘요."]}, {"label": "부모님께", "paras": ["분수는 '전체를 똑같이 나눈 것 가운데 몇'입니다. 3~4학년에서는 분수의 뜻과 단위분수(분자가 1인 분수)의 크기 비교를 다루고, 크기가 같은 분수는 5학년 '약분과 통분'에서 본격적으로 배웁니다. 조각을 직접 겹쳐 보면 '숫자가 크면 더 크다'는 흔한 착각, 즉 1/4이 1/2보다 크다는 생각을 자연스럽게 바로잡을 수 있습니다. '똑같이' 나누는 것이 핵심이라는 점도 꼭 짚어 주세요.", "이렇게 물어보세요: \"피자를 친구 몇 명이랑 나눠 먹으면 더 큰 조각을 먹을 수 있을까?\""]}], "title": "개념 정리"}, {"type": "more", "items": [{"body": "케이크나 사과를 나눌 때 \"이건 몇 분의 몇?\" 하고 물어요.", "title": "식탁에서 분수 말하기"}, {"body": "1/2 = 2/4 = 4/8을 조각으로 줄 세워요.", "title": "같은 크기 사슬"}, {"body": "\"3/8 피자 주세요\" 주문을 받아 조각을 골라 줘요.", "title": "분수 피자 가게"}]}, {"type": "info", "items": [{"label": "도안", "value": "분수 원판 6장 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 분수 (단위분수, 크기 비교)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["칼은 어른이"]$j$::jsonb)), updated_at=now() where slug='pizza-fractions';
update public.activities set content=$j$[{"note": "살 것 없음 · 종이접시나 도안", "rows": [{"how": "반지름 6cm 원과 붙이기 칸 (A4 2장)", "kit": false, "name": "원 16등분 도안"}, {"how": "도안 대신 접어서 써도 돼요", "kit": false, "name": "종이접시 1장 (선택)"}, {"how": "원의 둘레(원주)를 재요", "kit": false, "name": "실 50cm와 자"}, {"how": "조각을 잘라 붙여요", "kit": false, "name": "가위, 풀, 색연필"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "종이접시나 동그란 컵 둘레에 실을 감아 길이를 재고, 지름으로 나눠요. 3.1~3.2쯤이 나오나요? 이 값이 원주율(약 3.14)이에요.", "warn": "", "image": "assets/img/s_plate-circle-area_1.jpg", "title": "원주율 재기"}, {"body": "도안의 원을 위쪽 반원과 아래쪽 반원을 다른 색으로 칠해요.", "warn": "", "image": "assets/img/s_plate-circle-area_2.jpg", "title": "반쪽씩 색칠하기"}, {"body": "중심에서 나가는 선을 따라 16조각으로 잘라요. 피자 조각 같은 모양이 나와요.", "warn": "", "image": "assets/img/s_plate-circle-area_3.jpg", "title": "16조각 자르기"}, {"body": "도안 2쪽의 붙이기 칸에 한 조각은 뾰족한 쪽이 위, 다음 조각은 아래로 엇갈려 일렬로 붙여요. 직사각형에 가까운 모양이 돼요.", "warn": "", "image": "assets/img/s_plate-circle-area_4.jpg", "title": "엇갈려 붙이기"}, {"body": "세로는 반지름(6cm), 가로는 원주의 반(6 × 2 × 3.14 ÷ 2 = 18.84cm)이에요. 둘을 곱하면 원의 넓이예요.", "warn": "", "image": "assets/img/s_plate-circle-area_5.jpg", "title": "가로와 세로 찾기"}, {"body": "반지름 × 반지름 × 3.14 = 6 × 6 × 3.14 = 113.04cm². 모눈 칸 세기와도 비교해요.", "warn": "", "image": "assets/img/s_plate-circle-area_6.jpg", "title": "공식으로 확인하기"}], "notes": ["조각을 더 잘게(32조각) 나눌수록 더 반듯한 직사각형이 돼요. 아이와 '조각이 무한히 많으면?'을 이야기해 보세요."], "title": "하는 방법"}, {"type": "questions", "items": ["실로 잰 원주율이 정확히 3.14가 나오지 않는 이유는 무엇일까요?", "조각을 더 많이 자르면 모양이 어떻게 달라질까요?", "반지름이 2배가 되면 넓이는 몇 배가 될까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["원을 아주 잘게 잘라 엇갈려 붙이면 직사각형이 돼요. 이 직사각형의 세로는 원의 반지름, 가로는 원 둘레의 절반이에요. 그래서 원의 넓이는 반지름 × 반지름 × 3.14로 구할 수 있어요. 어떤 원이든 둘레를 지름으로 나누면 약 3.14가 나오는데, 이 값을 원주율이라고 해요."]}, {"label": "부모님께", "paras": ["6학년 '원의 넓이'는 원주율(지름에 대한 원주의 비율)과 원의 넓이 공식을 다룹니다. 공식을 외우기 전에 '왜 반지름을 두 번 곱하지?'를 이 활동으로 이해하면 응용 문제에서 덜 흔들립니다.", "원주율을 실로 잴 때 오차가 생기는 것이 자연스럽다는 것도 함께 이야기해 주세요. 측정과 계산의 차이를 배우는 좋은 기회입니다.", "이렇게 물어보세요: \"반지름이 4cm인 원과 8cm인 원의 넓이는 몇 배 차이일까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/plate-circle-area.pdf", "desc": "반지름 6cm 원 16등분, 직사각형 붙이기 칸, 원주율 기록표. A4 2장.", "type": "template", "title": "원 16등분 도안"}, {"type": "more", "items": [{"body": "냄비 뚜껑, 컵, 시계의 원주와 지름을 재서 비율을 표로 정리해요.", "title": "집 안 원주율 찾기"}, {"body": "지름 30cm 피자와 지름 20cm 피자 2판 중 어느 쪽이 더 많은지 넓이로 비교해요.", "title": "피자 가격 비교"}, {"body": "모눈종이(1cm 칸)에 반지름 6cm 원을 그려 칸을 세어 어림 넓이를 구해요.", "title": "모눈 세기"}]}, {"type": "info", "items": [{"label": "도안", "value": "원 넓이 도안 (A4 2장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "5~6학년 원의 넓이 (원주율, 원의 넓이)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$[]$j$::jsonb)), updated_at=now() where slug='plate-circle-area';
update public.activities set content=$j$[{"note": "살 것 없음 · 재활용품으로 만들어요", "rows": [{"how": "택배 상자 1개", "kit": false, "name": "무대 틀"}, {"how": "얇은 흰 이면지나 종이 포일(베이킹 페이퍼)", "kit": false, "name": "스크린"}, {"how": "우유팩을 펼친 판. 단단해서 오래 써요.", "kit": false, "name": "인형 판"}, {"how": "배달 음식에 딸려 온 나무젓가락", "kit": false, "name": "막대"}, {"how": "손전등이나 휴대폰 손전등", "kit": false, "name": "조명"}, {"how": "테이프, 가위, 커터칼(어른용)", "kit": false, "name": "도구"}, {"how": "그림자 인형 도안 A4 2장 (아래에서 내려받기)", "kit": false, "name": "도안"}], "type": "materials", "image": "assets/img/e3_mat.jpg"}, {"type": "steps", "items": [{"body": "상자 한 면에 테두리 3cm만 남기고 큰 네모 창을 그린 뒤 오려 내요. 창 반대쪽 면(뒷면)도 크게 오려 내거나 상자 뚜껑 쪽을 열어 두어야 손전등 빛이 스크린까지 들어오고, 그 뒤에서 인형을 움직일 수 있어요.", "warn": "커터칼은 어른이 사용해요.", "image": "assets/img/s_shadow-theater_1.jpg", "title": "무대 창 만들기"}, {"body": "창 안쪽에 흰 이면지를 팽팽하게 붙여요. 주름이 없을수록 그림자가 또렷하게 보여요.", "warn": "", "image": "assets/img/e3_s1.jpg", "title": "스크린 붙이기"}, {"body": "도안을 인쇄해 오린 뒤, 펼친 우유팩에 대고 따라 그려서 한 번 더 오려요. 아래쪽에 나무젓가락을 테이프로 단단히 붙이면 완성이에요. 색칠해도 좋아요. 그림자에는 모양만 나타나요.", "warn": "", "image": "assets/img/e3_s2.jpg", "title": "인형 만들고 막대 붙이기"}, {"body": "방을 어둡게 하고, 상자 뒤 1m쯤에서 손전등으로 스크린을 비춰요. 스크린과 손전등 사이에서 인형을 움직이며 이야기를 들려줘요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_shadow-theater_4.jpg", "title": "불 끄고 공연 시작"}], "notes": [], "title": "만드는 방법"}, {"pdf": "assets/pdf/shadow-puppets.pdf", "desc": "토끼, 거북이, 나무, 집, 해, 달. A4 2장, 실제 크기로 인쇄해 주세요. 점선은 나무젓가락을 붙이는 자리예요.", "type": "template", "title": "그림자 인형 도안"}, {"type": "questions", "items": ["인형을 손전등 가까이 가져가면 그림자 크기가 어떻게 되나요? 스크린 가까이 가져가면요?", "투명한 비닐, 이면지, 우유팩 조각을 비춰 보세요. 그림자가 어떻게 다른가요?", "손전등을 2개 켜면 그림자가 몇 개 생길까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["빛은 언제나 똑바로만 나아가요. 인형이 빛을 가로막으면 그 뒤로는 빛이 가지 못해서 까만 그림자가 생겨요. 인형이 손전등에 가까울수록 빛을 더 넓게 가려서 그림자가 커져요."]}, {"label": "부모님께", "paras": ["빛은 곧게 나아가는 성질(직진)이 있어서, 빛이 통과하지 못하는 불투명한 물체 뒤에는 물체 모양의 그림자가 생깁니다. 광원과 물체가 가까울수록 그림자는 커지고 테두리는 흐려집니다. 이면지 스크린은 빛을 일부만 통과시키는 반투명 물체라서 반대편에서도 그림자가 보입니다.", "이렇게 물어보세요: \"해가 질 때 내 그림자는 왜 길어질까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "집 창문을 오려 내고 사탕 포장지 같은 색 셀로판을 붙여 보세요.", "title": "색깔 그림자"}, {"body": "토끼와 거북이 이야기를 우리 가족 버전으로 꾸며요.", "title": "가족 인형극"}, {"body": "인형 없이 손만으로 개, 새, 게를 만들어 봐요.", "title": "손 그림자 놀이"}]}, {"type": "info", "items": [{"label": "도면", "value": "그림자 인형 도안 (A4 2장)"}, {"label": "실험 키트", "value": "집 재료로 충분해요 (손전등 없으면 휴대폰)"}, {"label": "교육과정 연결", "value": "3~4학년 빛과 그림자 (빛의 직진, 그림자의 크기)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["칼은 어른이"]$j$::jsonb)), updated_at=now() where slug='shadow-theater';
update public.activities set content=$j$[{"note": "살 것 없음 · 간식만 있으면 돼요", "rows": [{"how": "간식을 담는 접시로 써요", "kit": false, "name": "종이컵 4~6개"}, {"how": "젤리, 시리얼, 콩과자 등 셀 수 있는 것", "kit": false, "name": "작은 간식 24개"}, {"how": "아래에서 내려받아요", "kit": false, "name": "나눗셈 기록지 도안"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "간식 12개를 종이컵 3개에 하나씩 차례로 넣어요. 한 컵에 몇 개씩 들어갔나요? 12 ÷ 3 = 4.", "warn": "", "image": "assets/img/s_snack-division_1.jpg", "title": "똑같이 나누기"}, {"body": "이번에는 간식 12개를 4개씩 컵에 담아요. 컵이 몇 개 필요한가요? 12 ÷ 4 = 3.", "warn": "", "image": "assets/img/s_snack-division_2.jpg", "title": "묶어서 덜어 내기"}, {"body": "같은 12개인데 '몇 명에게 나누나'를 물으면 한 사람 몫이, '몇 개씩 담나'를 물으면 묶음 수가 답이 돼요. 기록지 두 칸에 그림으로 그려요.", "warn": "", "image": "assets/img/s_snack-division_3.jpg", "title": "두 방법 비교하기"}, {"body": "컵 3개 × 4개 = 12개. 나눗셈 답이 맞는지 곱셈으로 거꾸로 확인해요.", "warn": "", "image": "assets/img/s_snack-division_4.jpg", "title": "곱셈으로 확인하기"}, {"body": "간식 14개를 컵 3개에 나누면 2개가 남아요. 남는 수(나머지)는 나누는 수보다 항상 작아요.", "warn": "나머지는 3학년 2학기에 배우는 내용이에요. 어려워하면 넘어가도 돼요.", "image": "assets/img/s_snack-division_5.jpg", "title": "남는 것 알아보기"}], "notes": ["다 하고 나면 나눈 간식은 맛있게 먹어요. 가족 수대로 나누면 더 재미있어요."], "title": "하는 방법"}, {"type": "questions", "items": ["24개를 똑같이 나눌 수 있는 컵의 수를 모두 찾아볼까요?", "나눗셈 답을 곱셈으로 확인하는 방법을 말해 볼까요?", "20개를 6명에게 나누면 어떻게 될까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["나눗셈은 똑같이 나누는 계산이에요. '12개를 3명에게 똑같이 나누면 한 명이 몇 개?'처럼 나눌 수도 있고(12 ÷ 3 = 4), '12개를 4개씩 담으면 몇 봉지?'처럼 묶을 수도 있어요(12 ÷ 4 = 3). 어느 쪽이든 나눗셈식으로 써요."]}, {"label": "부모님께", "paras": ["3학년 나눗셈은 '똑같이 나누기(등분제)'와 '몇 번 덜어 내기(포함제)' 두 가지 뜻으로 소개됩니다. 아이가 문장제에서 헷갈려 하면 실물로 두 방법을 직접 해 보는 것이 가장 빠릅니다.", "곱셈구구를 거꾸로 쓰는 것이 나눗셈이라는 연결도 꼭 짚어 주세요.", "이렇게 물어보세요: \"12 ÷ 3 = 4를 보고 곱셈식을 두 개 만들어 볼까?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/snack-division.pdf", "desc": "나누기·묶기 그림 칸과 곱셈 확인 칸. A4 1장.", "type": "template", "title": "나눗셈 기록지"}, {"type": "more", "items": [{"body": "15 ÷ 5를 보고 간식, 연필, 스티커로 이야기 문제를 지어요.", "title": "나눗셈 이야기 만들기"}, {"body": "분수 활동의 피자 판으로 8조각을 2명, 4명에게 나눠요.", "title": "피자 나누기"}, {"body": "주사위 두 개로 수를 만들고 3으로 나눴을 때 나머지를 맞혀요.", "title": "나머지 찾기 놀이"}]}, {"type": "info", "items": [{"label": "도안", "value": "나눗셈 기록지 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 나눗셈 (등분제와 포함제, 곱셈과의 관계)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$[]$j$::jsonb)), updated_at=now() where slug='snack-division';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "다 마신 종이컵을 깨끗이 씻어서", "kit": false, "name": "종이컵 2개"}, {"how": "연실, 면실, 낚싯줄. 털실은 소리가 잘 안 전해져요.", "kit": false, "name": "실 3~5m"}, {"how": "반으로 부러뜨려 2조각. 클립으로 바꿔도 돼요.", "kit": false, "name": "이쑤시개 1개"}, {"how": "뾰족하게 깎은 연필 (송곳 대신)", "kit": false, "name": "연필"}, {"how": "실 자르기용", "kit": false, "name": "가위"}], "type": "materials", "image": "assets/img/e1_mat.jpg"}, {"type": "steps", "items": [{"body": "종이컵 안쪽에서 바닥 한가운데를 연필 끝으로 꾹 눌러 작은 구멍을 내요. 실이 겨우 들어갈 만큼 작게 뚫어야 소리가 잘 전해져요.", "warn": "어른과 함께 해요.", "image": "assets/img/e1_s1.jpg", "title": "컵 바닥에 작은 구멍 뚫기"}, {"body": "실 끝을 컵 바깥쪽 구멍으로 넣어서 컵 안쪽으로 빼내요.", "warn": "", "image": "assets/img/s_string-phone_2.jpg", "title": "실 끼우기"}, {"body": "컵 안쪽으로 나온 실을 이쑤시개 조각 가운데에 2~3번 단단히 묶어요. 이쑤시개가 구멍을 막아 줘서 실을 당겨도 빠지지 않아요.", "warn": "", "image": "assets/img/e1_s2.jpg", "title": "이쑤시개에 묶기"}, {"body": "실의 다른 끝도 두 번째 컵에 1~3번과 같은 방법으로 연결해요.", "warn": "", "image": "assets/img/s_string-phone_4.jpg", "title": "반대쪽도 똑같이"}, {"body": "두 사람이 실이 팽팽해질 때까지 멀리 떨어져요. 한 사람은 컵에 입을 대고 작게 말하고, 다른 사람은 컵을 귀에 대고 들어요. 맨 위 사진처럼요!", "warn": "", "image": "assets/img/s_string-phone_5.jpg", "title": "실을 팽팽하게 당겨 대화하기"}], "notes": [], "title": "만드는 방법"}, {"type": "questions", "items": ["실이 축 늘어졌을 때와 팽팽할 때, 소리가 어떻게 달라지나요?", "친구가 말하는 동안 실을 손가락으로 살짝 만져 보세요. 무엇이 느껴지나요?", "실 가운데를 손으로 꽉 잡으면 어떻게 될까요?"], "title": "관찰해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["말을 하면 컵 바닥이 아주 빠르게 부르르 떨려요. 이 떨림이 팽팽한 실을 타고 친구 컵까지 달려가서, 친구 컵 바닥도 똑같이 떨게 만들어요. 그래서 친구 귀에 내 목소리가 들려요. 실을 손으로 잡으면 떨림이 손에서 멈춰 버려서 소리가 끊겨요."]}, {"label": "부모님께", "paras": ["소리는 물체의 떨림(진동)이 물질을 통해 전달되는 현상입니다. 컵 바닥이 진동판 역할을 하고, 팽팽한 실이 진동을 반대편 컵 바닥까지 전달합니다. 실이 느슨하거나 중간을 잡으면 진동이 흡수되어 전달되지 않습니다.", "이렇게 물어보세요: \"실 말고 다른 걸로 이으면 어떻게 될까?\""]}], "title": "왜 그럴까?"}, {"type": "more", "items": [{"body": "면실, 낚싯줄, 털실 중 어느 것이 가장 잘 들릴까요?", "title": "실 바꿔 보기"}, {"body": "실을 이어 붙여 2m와 10m 실전화의 소리를 비교해요. 실이 길수록 더 팽팽하게 당겨야 해요.", "title": "길이 바꿔 보기"}, {"body": "실 두 개를 가운데에서 묶으면 셋이 함께 이야기할 수 있어요.", "title": "세 명이 통화하기"}]}, {"type": "info", "items": [{"label": "도면", "value": "필요 없어요"}, {"label": "실험 키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 소리의 성질 (소리의 발생과 전달)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["구멍 뚫기는 어른과 함께"]$j$::jsonb)), updated_at=now() where slug='string-phone';
update public.activities set content=$j$[{"note": "살 것 없음 · 택배 상자에 붙이면 튼튼해요", "rows": [{"how": "조각 선과 모양 카드 (A4 1장)", "kit": false, "name": "칠교 도안"}, {"how": "도안을 붙여 두꺼운 조각을 만들어요", "kit": false, "name": "얇은 택배 상자 판지"}, {"how": "조각마다 색을 칠하면 구분하기 쉬워요", "kit": false, "name": "풀, 가위, 색연필"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안의 큰 정사각형을 상자 판지에 풀로 붙여요.", "warn": "", "image": "assets/img/s_tangram_1.jpg", "title": "도안 붙이기"}, {"body": "선을 따라 큰 삼각형 2개, 중간 삼각형 1개, 작은 삼각형 2개, 정사각형 1개, 평행사변형 1개로 잘라요.", "warn": "두꺼운 판지는 어른이 칼로 잘라 주세요.", "image": "assets/img/s_tangram_2.jpg", "title": "일곱 조각 자르기"}, {"body": "삼각자나 책 모서리를 대 보며 직각이 있는 조각을 찾아 표시해요.", "warn": "", "image": "assets/img/s_tangram_3.jpg", "title": "직각 찾기"}, {"body": "도안 아래 도전 카드 3장(정사각형, 삼각형, 직사각형)을 보고 카드에 적힌 조각만 써서 같은 모양을 만들어요.", "warn": "", "image": "assets/img/s_tangram_4.jpg", "title": "도전 카드 풀기"}, {"body": "작은 삼각형 2개로 정사각형, 중간 삼각형, 평행사변형을 각각 만들 수 있는지 해 봐요.", "warn": "", "image": "assets/img/s_tangram_5.jpg", "title": "조각 합치기"}, {"body": "새로운 모양을 만들고 테두리를 따라 그려 가족에게 문제로 내요.", "warn": "", "image": "assets/img/s_tangram_6.jpg", "title": "나만의 모양"}], "notes": ["일곱 조각을 다시 정사각형으로 맞추는 것이 생각보다 어려워요. 막히면 큰 삼각형 2개부터 놓아 보세요."], "title": "하는 방법"}, {"type": "questions", "items": ["일곱 조각 중 직각이 있는 조각은 몇 개인가요?", "작은 삼각형 2개로 만들 수 있는 모양은 무엇무엇일까요?", "정사각형도 직사각형이라고 할 수 있을까요?"], "title": "생각해 봐요"}, {"type": "explain", "boxes": [{"label": "아이에게 읽어 주세요", "paras": ["꼭짓점에서 종이를 반듯하게 두 번 접었을 때 생기는 각을 직각이라고 해요. 직각이 있는 삼각형은 직각삼각형, 네 각이 모두 직각인 사각형은 직사각형이에요. 그중 네 변의 길이까지 모두 같으면 정사각형이에요. 그래서 정사각형은 직사각형의 한 종류랍니다."]}, {"label": "부모님께", "paras": ["3학년 '평면도형'은 선분·반직선·직선, 각과 직각, 직각삼각형·직사각형·정사각형을 다룹니다. 아이들이 '정사각형은 직사각형인가?'를 가장 헷갈려 하니, 칠교 조각을 직접 대 보며 조건을 하나씩 확인하게 해 주세요.", "4학년 다각형·사각형 분류(평행사변형, 사다리꼴)로 이어질 때 이 조각들을 다시 쓰면 좋습니다.", "이렇게 물어보세요: \"이 조각은 왜 직사각형이 아니라고 생각해?\""]}], "title": "왜 그럴까?"}, {"pdf": "assets/pdf/tangram.pdf", "desc": "칠교 정사각형(15cm)과 모양 만들기 도전 카드 3장. A4 1장.", "type": "template", "title": "칠교 도안"}, {"type": "more", "items": [{"body": "같은 모양 카드를 누가 더 빨리 만드는지 겨뤄요.", "title": "시간 재기 대결"}, {"body": "아무 모양 종이를 두 번 접어 직각 자를 만들고 집 안 직각을 찾아요.", "title": "종이 접어 직각 만들기"}, {"body": "모양 테두리만 그려 주고 조각 배치를 맞히게 해요.", "title": "그림자 맞히기"}]}, {"type": "info", "items": [{"label": "도안", "value": "칠교 도안 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 평면도형 (직각, 직각삼각형, 직사각형, 정사각형)"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$["두꺼운 판지 자르기는 어른이"]$j$::jsonb)), updated_at=now() where slug='tangram';
update public.activities set content=$j$[{"note": "살 것 없음 · 모두 집에 있는 재료", "rows": [{"how": "이면지에 인쇄해도 돼요 (A4 1장)", "kit": false, "name": "날씨 돌림판 도안"}, {"how": "과자 상자나 택배 상자를 펼쳐서", "kit": false, "name": "두꺼운 종이"}, {"how": "화살표를 돌릴 수 있게 고정해요 (없으면 압정과 지우개)", "kit": false, "name": "할핀 1개"}, {"how": "벽이나 현관문에 걸 때 써요", "kit": false, "name": "풀, 가위, 끈"}], "type": "materials", "image": null}, {"type": "steps", "items": [{"body": "도안을 두꺼운 종이에 붙이고 큰 원과 화살표를 오려요.", "warn": "", "image": "assets/img/s_weather-wheel_1.jpg", "title": "판 만들기"}, {"body": "원 가운데 점과 화살표 아래쪽 점을 맞추고 할핀으로 꽂아요. 화살표가 빙글빙글 도는지 확인해요.", "warn": "", "image": "assets/img/s_weather-wheel_2.jpg", "title": "화살표 달기"}, {"body": "아이 눈높이에 맞춰 현관문이나 창문 옆에 걸어요.", "warn": "", "image": "assets/img/s_weather-wheel_3.jpg", "title": "현관에 걸기"}, {"body": "학교 가기 전에 부모님이 \"How's the weather today?\" 하고 물으면, 아이가 창밖을 보고 화살표를 돌리며 대답해요.", "warn": "", "image": "assets/img/s_weather-wheel_4.jpg", "title": "매일 아침 1분"}], "notes": [], "title": "하는 방법"}, {"head": ["영어", "뜻"], "note": "돌림판 낱말: sunny(맑은), cloudy(흐린), rainy(비 오는), snowy(눈 오는), windy(바람 부는), hot(더운)", "rows": [["How's the weather today?", "오늘 날씨 어때?"], ["It's sunny. / It's rainy.", "맑아. / 비가 와."], ["Take your umbrella!", "우산 챙겨! (rainy일 때)"], ["Let's go outside!", "밖에 나가자! (sunny일 때)"]], "type": "table", "title": "핵심 표현"}, {"pdf": "assets/pdf/weather-wheel.pdf", "desc": "날씨 그림 6칸 원판, 화살표, 아침 대화 문장. A4 1장.", "type": "template", "title": "날씨 돌림판 도안"}, {"type": "explain", "boxes": [{"label": "부모님께", "paras": ["외국어는 짧게라도 매일 쓰는 것이 가장 효과적입니다. 하루 1분 날씨 대화를 아침 습관으로 만들어 보세요. 한 달이면 날씨 낱말 6개와 질문·대답 표현이 자연스럽게 입에 붙어요."]}, {"label": "수학도 함께", "paras": ["한 달 동안 날씨를 달력에 기록하면, 수학 '재활용품 막대그래프'처럼 날씨 그래프도 그릴 수 있어요."]}], "title": ""}, {"type": "more", "items": [{"body": "\"It's cold. Wear your coat!\" 날씨에 맞는 옷을 말해요.", "title": "옷 입히기 놀이"}, {"body": "TV 기상캐스터처럼 내일 날씨를 영어로 발표해요.", "title": "일기 예보관"}, {"body": "지금 다른 나라 날씨를 찾아보고 비교해요.", "title": "세계 날씨"}]}, {"type": "info", "items": [{"label": "도안", "value": "날씨 돌림판과 화살표 (A4 1장)"}, {"label": "키트", "value": "집에 있는 재료로 충분해요"}, {"label": "교육과정 연결", "value": "3~4학년 날씨 묻고 답하기"}]}]$j$::jsonb, caution=array(select jsonb_array_elements_text($j$[]$j$::jsonb)), updated_at=now() where slug='weather-wheel';
